func _init():
	var path := "res://scripts/mobile/VirtualJoystick.gd"
	print("P2 exists=", ResourceLoader.exists(path))
	var res = load(path)
	print("P2 load=", res, " is_gdscript=", res is GDScript)
	if res is GDScript:
		var gd: GDScript = res
		print("P2 can_instantiate=", gd.can_instantiate())
		print("P2 src_len=", gd.source_code.length())
		print("P2 global_name=", gd.get_global_name())
		print("P2 methods=", gd.get_script_method_list().size(), " props=", gd.get_script_property_list().size())
		var inst = gd.new()
		print("P2 inst=", inst, " inst_script=", inst.get_script() if inst else null)
	# 全局类注册表里 VirtualJoystick 指向谁
	if ProjectSettings.has_method("get_global_class_list"):
		for e in ProjectSettings.get_global_class_list():
			if str(e.get("class", "")) == "VirtualJoystick":
				print("P2 globalclass=", e)
	# 是否有 .gdignore 之类把目录排除了
	print("P2 gdignore_in_mobile=", FileAccess.file_exists("res://scripts/mobile/.gdignore"))
	for p in ["res://scripts/mobile/VirtualJoystick.gd", "res://scripts/mobile/TouchController.gd"]:
		print("P2 file_size ", p, "=", FileAccess.get_file_as_string(p).length())
	quit()
