{"file_path":"C:\Users\18749\Documents\honor-king\scripts\net\NetClientBattle.gd","new_string":"func _apply_hero_act(nid: int, act: int, yaw: float) -> void:
	var v: Dictionary = _views.get(nid, {})
	if v.is_empty() or not v.has("ap"):
		return
	var nn: Node3D = v.node
	if nn != null and is_instance_valid(nn):
		nn.rotation.y = yaw   # 攻击朝向（host 用 rotation.y 面向目标，同约定）
	var now := Time.get_ticks_msec()
	v.att_until = now + 620
	var ap: AnimationPlayer = v.ap
	var is_hero := int(v.type) == NET_HERO
	var clip := ""
	if not is_hero:
		# 小兵/野怪：clip 命名与英雄不同，用建 view 时缓存的关键字匹配结果
		clip = str(v.get("atk_clip", ""))
	else:
		# 英雄：act=1 远程射击（同 host _attack_anim 的 holding-* 档），act=0 近战左右交替
		if act == 1:
			clip = "holding-both-shoot" if str(v.get("name", "")) in ["后羿", "孙尚香", "元流之子"] else "holding-right-shoot"
		else:
			v.melee_flip = not bool(v.get("melee_flip", false))
			clip = "attack-melee-left" if bool(v.melee_flip) else "attack-melee-right"
		if not ap.has_animation(clip):
			clip = str(v.get("atk_clip", ""))   # 老模型只有单侧挥击时兜底
	if clip != "" and ap.has_animation(clip):
		ap.play(clip)
		v.anim = "attack"
		v.att_clip = clip
		v.att_play = now
