func _bullet_kind(bl: Bullet) -> int:
	if bl.is_houyi_ult:
		return 4
	var bsrc = bl.source
	if bsrc == null or not is_instance_valid(bsrc):
		return 0
	if bsrc is Turret:
		return 1
	if bsrc is Minion:
		if bsrc.display_name == "ranged":
			return 2
		if bsrc.display_name == "siege":
			return 3
	if bsrc is Hero and float(bsrc.attack_range) > 400.0:
		return 1
	return 0

=== client bullet visual dispatch ===
		m.visible = true
	else:
>>		m = _make_bullet_visual(kind)
		_vis_root.add_child(m)
	return {"m": m, "x": 0.0, "y": 0.0, "z": 0.0,
		"px": 0.0, "py": 0.0, "pz": 0.0,
		"vx": 0.0, "vy": 0.0, "vz": 0.0,
		"arr_ms": 0, "team": team, "kind": kind}

# kind>=1000 为定制视觉（v7 idx7 vkind，host 换过默认弹体的技能弹），派发到 _make_bullet_bespoke。
# 路径缺失时回退旧圆柱（保留队伍色近似），与 host Bullet.gd 的回退球体同一思路。
>>func _make_bullet_visual(kind: int) -> Node3D:
	if kind >= 1000:
		return _make_bullet_bespoke(kind - 1000)
	if kind == 4:
		# 后羿R：自组太阳火箭（同 host Bullet.gd is_houyi_ult 分支）；放平到水平并朝速度向
		var root := Node3D.new()
		root.name = "HouyiUltArrow"
