{"content":"extends Node

func _list(dir: String, out: Array) -> void:
	var d := DirAccess.open(dir)
	if d == null:
		return
	d.list_dir_begin()
	var f := d.get_next()
	while f != "":
		if d.current_is_dir():
			if not f.begins_with("."):
				_list(dir.path_join(f), out)
		elif f.ends_with(".glb"):
			out.append(dir.path_join(f))
		f = d.get_next()

func _bbox(n: Node, xf: Transform3D, acc: Array) -> void:
	if n is MeshInstance3D and n.mesh != null:
		var a: AABB = xf * n.get_aabb()
		acc[0] = a if acc[0] == null else (acc[0] as AABB).merge(a)
	for c in n.get_children():
		var cxf := xf
		if c is Node3D:
			cxf = xf * (c as Node3D).transform
		_bbox(c, cxf, acc)

func _ready() -> void:
	var files: Array = []
	_list("res://model", files)
	files.sort()
	for p in files:
		var ps = load(p)
		if ps == null:
			print("M|", p, "|LOAD_FAIL")
			continue
		var inst = ps.instantiate()
		add_child(inst)
		var acc: Array = [null]
		_bbox(inst, Transform3D.IDENTITY, acc)
		var aabb = acc[0]
		if aabb == null:
			print("M|", p, "|NO_MESH")
		else:
			var s: Vector3 = aabb.size
			print("M|", p, "|w=%.2f h=%.2f d=%.2f ymin=%.2f" % [s.x, s.y, s.z, aabb.position.y])
		inst.queue_free()
	print("M|DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\devsize\size.gd"}

