func _ready() -> void:
	for p in [
		"res://scripts/entities/MeshFactory.gd",
		"res://scripts/entities/Bullet.gd",
		"res://scripts/entities/Turret.gd",
		"res://scripts/net/NetClientBattle.gd",
	]:
