	add_child(orb)
	print("T orb children=", orb.get_child_count())
	var T = load("res://scripts/entities/Turret.gd")
	var t = T.new()
	t.display_name = "crystal"
	t.team = 0
	add_child(t)
	T.play_collapse(t, 1.6, get_parent())
	await get_tree().create_timer(2.4).timeout
	print("T collapse finished, children=", t.get_child_count())
	get_tree().quit()
