{"content":"extends Node

const NetModels = preload("res://scripts/net/NetModels.gd")

func _ready() -> void:
	for p in [
		"res://scripts/net/NetModels.gd",
		"res://scripts/entities/Minion.gd",
		"res://scripts/net/NetClientBattle.gd",
	]:
		var s = load(p)
		print("C ", p, " gd=", s is GDScript)
	for t in ["melee", "ranged", "siege", "super", "dragon", "storm", "shadow_dragon"]:
		var raw: float = float(NetModels.MINION_RAW_H.get(t, 0.84))
		var sc: float = NetModels.minion_scale(t)
		print("S %s scale=%.3f world_h=%.2f" % [t, sc, raw * sc])
	# 实机：主机兵线模型实际尺寸
	for t in ["melee", "siege", "shadow_dragon"]:
		var m = load("res://scripts/entities/Minion.gd").new()
		m.display_name = t
		m.team = 0
		add_child(m)
		if m.anim_player != null:
			m.anim_player.stop()
		print("H %s root_children=%d visual_scale=%s" % [t, m.get_child_count(), str(m.visual.scale) if m.visual else "-"])
	print("S done")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\devmin\check.gd"}

