const SkillArt = preload("res://scripts/ui/SkillArt.gd")
var done := false
func _draw() -> void:
	var ids := SkillDatabase.skills.keys()
	var groups := {}
	for id in ids:
		var s := str(id)
		var base := s
		for suf in ["_q", "_w", "_r", "_e"]:
			if s.ends_with(suf):
				base = s.substr(0, s.length() - 2)
				break
		if not groups.has(base):
			groups[base] = []
		groups[base].append(s)
	var same := []
	for g in groups.keys():
		var ms := []
		for sid in groups[g]:
			var sk: Skill = SkillDatabase.skills[sid]
			if sk == null: continue
			ms.append(SkillArt.motif_for(sk, 0))
			SkillArt.draw_bg(self, Vector2(200, 200), 46, str(g), sk, ms.size() - 1, true, true)
		if ms.size() >= 3 and ms.size() == ms.count(ms[0]):
			same.append("%s=%s" % [g, ms[0]])
	print("I heroes=", groups.size(), " all_same=", same.size(), " ", same)
	print("I ok")
	done = true
func _process(_d: float) -> void:
	if done: get_tree().quit()
