{"file_path":"C:\Users\18749\Documents\honor-king\scripts\ui\UiKit.gd","new_string":"## —— 圆角胶囊 / 物品图标 / 推荐装备卡：战况带、技能名条、推荐位共用的绘制原语 ——
## 圆角底 + 1px 冷边；accent 不透明时在左侧画一条竖色条（阵营/元素标识）
func chip(ci: CanvasItem, rect: Rect2, alpha := 0.86, radius := 14.0, accent := Color(0, 0, 0, 0)) -> void:
	ci.draw_style_box(flat(alpha, int(radius), 1, C_PANEL_EDGE, Color(0, 0, 0, 0), 0.0, 6.0), rect)
	if accent.a > 0.01:
		ci.draw_rect(Rect2(rect.position + Vector2(5.0, rect.size.y * 0.26),
			Vector2(3.0, rect.size.y * 0.48)), accent)

## 物品图标位：品质色圆角方块 + 名称首字（项目无美术资源，统一占位）
func item_icon(ci: CanvasItem, rect: Rect2, tier: int, item_name: String) -> void:
	var qc: Color = QUALITY_COLORS[clampi(tier, 1, 5)]
	ci.draw_style_box(flat(0.92, int(rect.size.y * 0.28), 2, qc.darkened(0.10),
		qc.darkened(0.80), 0.0, 4.0), rect)
	var gl := item_name.substr(0, 1) if item_name != "" else "装"
	var fs := int(rect.size.y * 0.54)
	var pos := rect.position + Vector2(0.0, rect.size.y * 0.5 + fs * 0.36)
	ci.draw_string_outline(font(), pos, gl, HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, fs, 3, Color(0, 0, 0, 0.7))
	ci.draw_string(font(), pos, gl, HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, fs, qc.lightened(0.55))

## 推荐装备卡：品质图标 + 名称 + 状态行（可买/还差/槽满/已成型）+ 金币进度条
func rec_card(ci: CanvasItem, rect: Rect2, item_name: String, tier: int, cost: int, gold: int,
		maxed: bool, slot_full: bool) -> void:
	var can := cost > 0 and gold >= cost
	var accent := C_GOLD if can else (C_DANGER if slot_full else C_PANEL_EDGE)
	chip(ci, rect, 0.90, 14.0, accent)
	var pad := 6.0
	var ic := Rect2(rect.position + Vector2(pad, pad), Vector2(rect.size.y - pad * 2.0, rect.size.y - pad * 2.0))
	item_icon(ci, ic, tier, item_name)
	var tx := ic.position.x + ic.size.x + 10.0
	var avail := rect.position.x + rect.size.x - tx - 8.0
	var nm := item_name if item_name != "" else ("已成型" if maxed else "无推荐")
	var fs := int(rect.size.y * 0.27)
	ci.draw_string_outline(font(), Vector2(tx, rect.position.y + rect.size.y * 0.40), nm,
		HORIZONTAL_ALIGNMENT_LEFT, avail, fs, 3, Color(0, 0, 0, 0.8))
	ci.draw_string(font(), Vector2(tx, rect.position.y + rect.size.y * 0.40), nm,
		HORIZONTAL_ALIGNMENT_LEFT, avail, fs, Color(1, 1, 1, 0.96))
	var sub := "-"
	if maxed: sub = "已成型"
	elif cost > 0: sub = ("%d 金 · 可买" % cost) if can else ("还差 %d 金" % (cost - gold))
	var sfs := int(rect.size.y * 0.20)
