content.arguments:
{"command":"$p = (Resolve-Path 'scripts\mobile\TouchActionButton.gd'); $t = [System.IO.File]::ReadAllText($p)
$t = $t.Replace("var label_font_size := 0.0", "var icon_kind := `"`"           # 非空时画程序化功能图标（推塔/小兵/回城…），不再画文字`nvar label_font_size := 0.0")
$old = @'
	var fs := int(label_font_size) if label_font_size > 0.0 else int(maxf(22.0, radius * 0.58))
'@
$new = @'
	if icon_kind != "":
		IconArt.draw_icon(self, center, radius * 0.98, icon_kind, not _active and not hold_to_act and label_text == "")
		return
	var fs := int(label_font_size) if label_font_size > 0.0 else int(maxf(22.0, radius * 0.58))
'@
$t = $t.Replace($old, $new)
if (-not $t.Contains("const IconArt = preload")) {
	$t = $t.Replace("class_name TouchActionButton", "class_name TouchActionButton`nconst IconArt = preload(`"res://scripts/ui/IconArt.gd`")")
}
[System.IO.File]::WriteAllText($p, $t)
Write-Output ("kind=" + $t.Contains("var icon_kind")) ("icon=" + $t.Contains("IconArt.draw_icon"))
Select-String -Path $p -Pattern 'class_name|const IconArt' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Add icon rendering to action buttons"}

