func _process(delta: float) -> void:
	if not visible or data.is_empty():
		return
	var rem := float(data.get("respawn", 0.0))
	if rem <= 0.0:
		set_process(false)
		return
	_tick_acc += delta
	if _tick_acc < 0.1:
		return
	var step := _tick_acc
	_tick_acc = 0.0
	data["respawn"] = maxf(0.0, rem - step)
	if int(ceil(rem)) != int(ceil(float(data["respawn"]))):
		queue_redraw()

