$t = $t.Replace("const SNAPSHOT_HZ := 15.0", "const DeathRecapView = preload(`"res://scripts/ui/DeathRecapView.gd`")`nconst SNAPSHOT_HZ := 15.0")
$old = @'
func _pack_death_recap(h: Hero) -> Dictionary:
	var now := Time.get_ticks_msec() / 1000.0
	var source_data := {}
	var order: Array = []
	var log_rows: Array = []   # 逐击明细（镜像主机 _show_death_recap 前段逐行攻击记录）：[src,amount,is_magic,crit,skill_key,time_ago]
	for log in h.damage_log:
		if now - float(log.time) > 7.0:
			continue
		var src := str(log.source)
		log_rows.append([src, roundf(float(log.amount)),
			(1 if log.is_magic else 0), (1 if log.get("crit", false) else 0),
			_recap_skill_key(int(log.skill_id)), now - float(log.time)])
		if not source_data.has(src):
			source_data[src] = {}
			order.append(src)
		var key := _recap_skill_key(int(log.skill_id))
		if not source_data[src].has(key):
			source_data[src][key] = [0.0, 0.0]   # [物理, 法术]
		source_data[src][key][1 if log.is_magic else 0] += float(log.amount)
	var rows: Array = []
	for src in order:
		var bars: Array = []
		var tot := 0.0; var ph := 0.0; var mg := 0.0
		for key in source_data[src]:
			var d: Array = source_data[src][key]
			var s := float(d[0]) + float(d[1])
			if s <= 0.0:
				continue
			bars.append([key, roundf(float(d[0])), roundf(float(d[1]))])
			tot += s; ph += float(d[0]); mg += float(d[1])
		rows.append({"src": src, "total": roundf(tot), "phys": roundf(ph), "mag": roundf(mg), "bars": bars})
	return {"cc": h.get_cc_duration(7.0), "rows": rows, "log": log_rows}
'@
$new = @'
func _pack_death_recap(h: Hero) -> Dictionary:
	# 与主机 UI_Manager._show_death_recap 共用同一份 payload 构建（单一真源，避免两端漂移）
	var battle = get_tree().get_first_node_in_group("battle_manager")
	return DeathRecapView.build(h, battle)
'@
