func _close() -> void:
	UiKit.hide_panel(self, 0.10)
	_closed = true

# ---------- 布局（内容几何，供 _draw 与 _gui_input 共用） ----------

func _content_h() -> float:
	var rows: Array = _payload.get("rows", [])
	var log_a: Array = _payload.get("log", [])
	var h := 0.0
	if not log_a.is_empty():
		h += 36.0 + log_a.size() * LOG_H + 10.0
	h += rows.size() * SRC_BLOCK
	return h

func _panel_rect(area: Vector2, content_h: float) -> Rect2:
	# 同 host：面板固定 520×1280 居中（超出视口时收窄到 94% 高）
	var max_h := minf(PANEL_MAX_H, area.y * 0.94)
	max_h = minf(max_h, 150.0 + content_h)
	return Rect2((area.x - PANEL_W) * 0.5, (area.y - max_h) * 0.5, PANEL_W, max_h)

# ---------- 绘制 ----------

func _text(pos: Vector2, txt: String, sz: int, col: Color) -> void:
	draw_string(_f, pos + Vector2(1.5, 1.5), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, sz, Color(0, 0, 0, 0.5))
	draw_string(_f, pos, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, sz, col)

func _draw() -> void:
	if not visible:
		return
	var vp := get_viewport()
	if vp == null:
		return
	var area := vp.get_visible_rect().size
	var us := _us()
	draw_rect(Rect2(Vector2.ZERO, area), Color(0, 0, 0, 0.5))   # 同 host death_overlay：黑 0.5
	var rows: Array = _payload.get("rows", [])
	var log_a: Array = _payload.get("log", [])
	var cc := float(_payload.get("cc", 0.0))
	var content_h := _content_h()
	var panel := _panel_rect(area, content_h)
	draw_rect(panel, Color(0, 0, 0, 0.85))                       # 同 host _apply_panel_style(panel, 0.85)
	draw_rect(panel, Color(0.9, 0.2, 0.2, 0.85), false, 3.0)
	var x := panel.position.x
	_text(Vector2(x + 24, panel.position.y + 36), "死亡回放 (近7秒)", int(round(20 * us)), Color.RED)
	_text(Vector2(x + 24, panel.position.y + 76), "受控时长: %.1f 秒" % cc, int(round(15 * us)), Color(0.82, 0.6, 1.0))
	# 关闭 ✕ 命中（右上，同 host Button：右侧留 8、上方留 8、50×50）
	var close_r := Rect2(panel.position.x + PANEL_W - 58.0, panel.position.y + 8.0, 50.0, 50.0)
	_text(Vector2(close_r.position.x + 14.0, close_r.position.y + 38.0), "×", int(round(26 * us)), Color.WHITE)
	# 内容区（固定头部下方，超高可滚）
	var y0 := panel.position.y + 150.0
	var win_h := maxf(0.0, panel.size.y - 150.0 - 14.0)
	var scroll_max := maxf(0.0, content_h - win_h)
	if _scroll > scroll_max:
		_scroll = scroll_max
	var c := y0 - _scroll
	var win_bot := y0 + win_h
	# 前段：逐击明细
	if not log_a.is_empty():
		if c + 22.0 >= y0 and c < win_bot:
			_text(Vector2(x + 24, c + 22.0), "攻击记录", int(round(15 * us)), Color.WHITE)
		c += 34.0
		for lg in log_a:
			if c + LOG_H >= y0 and c < win_bot:
				_draw_log_row(x, c, lg)
			c += LOG_H
		c += 8.0
	# 分隔线
	if c + 6.0 - 3.0 < win_bot:
		draw_rect(Rect2(x + 20, c + 3.0, PANEL_W - 40, 1.0), Color(1, 1, 1, 0.25))
	# 后段：按来源+技能汇总条形
	for row in rows:
		if c + SRC_BLOCK >= y0 and c < win_bot:
			_draw_source_block(x, c, row)
		c += SRC_BLOCK
	if rows.is_empty() and log_a.is_empty():
		_text(Vector2(x + 24, y0 + 8.0), "（近7秒无伤害记录）", int(round(15 * us)), Color(0.7, 0.7, 0.7))

func _draw_log_row(x: float, y: float, lg: Array) -> void:
	var us := _us()
	var src := str(lg[0])
	var dmg := int(lg[1])
	var is_magic := int(lg[2]) == 1
	var crit := int(lg[3]) == 1
	var skill := str(lg[4])
	var ago := float(lg[5])
	# 字号同 host _show_death_recap：来源/伤害 13、暴击 12、技能 12、时间 11（均 ×ui_scale）
	_text(Vector2(x + 24, y + 16.0), src, int(round(13 * us)), Color.WHITE)
	var dcol := Color(1.0, 0.83, 0.2) if crit else (Color.PURPLE if is_magic else Color.ORANGE)
	_text(Vector2(x + 148, y + 16.0), "-%d" % dmg, int(round(13 * us)), dcol)
	if crit:
		_text(Vector2(x + 236, y + 16.0), "暴击!", int(round(12 * us)), Color(1.0, 0.93, 0.35))
	_text(Vector2(x + 296, y + 16.0), skill, int(round(12 * us)), Color.GRAY)
	_text(Vector2(x + PANEL_W - 132, y + 16.0), "%.1fs前" % ago, int(round(11 * us)), Color(0.62, 0.7, 0.82))

func _draw_source_block(x: float, y: float, row: Dictionary) -> void:
	var us := _us()
	var src := str(row["src"])
	var total := int(row["total"]); var phys := int(row["phys"]); var mag := int(row["mag"])
	_text(Vector2(x + 24, y + 24.0), src, int(round(15 * us)), Color.WHITE)   # host 来源标题 15×us
	var bars: Array = row["bars"]
	if bars.is_empty():
		return
	var bw := (PANEL_W - 48.0) / maxf(bars.size(), 1)
	var bx := x + 24.0
	var col_max := 0.0
	for b in bars:
		col_max = maxf(col_max, float(b[1]) + float(b[2]))
	var cy := y + 44.0
	for b in bars:
		var key := str(b[0]); var pv := float(b[1]); var mv := float(b[2])
		var st := pv + mv
		var bar_h := maxf(4.0, st / maxf(col_max, 1.0) * BAR_H)
		var by := cy + BAR_H - bar_h
		if pv > 0.0:
			var ph_h := pv / st * bar_h
			draw_rect(Rect2(bx, by, BAR_W, ph_h), Color(Color.ORANGE, 0.85))   # 同 host 物理橙 0.85
			by += ph_h
		if mv > 0.0:
			var mg_h := mv / st * bar_h
			draw_rect(Rect2(bx, by, BAR_W, mg_h), Color(Color.MEDIUM_PURPLE, 0.85))  # 同 host 法术紫 0.85
		draw_rect(Rect2(bx, cy, BAR_W, BAR_H), Color(1, 1, 1, 0.2), false, 1.5)
		_text(Vector2(bx, cy - 8.0), str(int(st)), int(round(10 * us)), Color.WHITE)
		_text(Vector2(bx, cy + BAR_H + 20.0), key, int(round(10 * us)), Color.GRAY)
		bx += bw
	_text(Vector2(x + 24, cy + BAR_H + 48.0), "  总计: %d (物理:%d 法术:%d)" % [total, phys, mag],
			int(round(13 * us)), Color.LIGHT_GRAY)

# ---------- 输入 ----------

func _unhandled_input(ev: InputEvent) -> void:
	if not (ev is InputEventKey and (ev as InputEventKey).pressed and not (ev as InputEventKey).echo):
		return
	if (ev as InputEventKey).keycode == KEY_ESCAPE and visible:
		_close()

func _gui_input(ev: InputEvent) -> void:
	if not (ev is InputEventMouseButton and (ev as InputEventMouseButton).pressed):
		return
	var mb := ev as InputEventMouseButton
	var vp := get_viewport()
	if vp == null:
		return
	var area := vp.get_visible_rect().size
	var panel := _panel_rect(area, _content_h())
	if not panel.has_point(mb.position):
		# 点面板外：左键关闭（同 host 语义）；滚轮无效
		if mb.button_index == MOUSE_BUTTON_LEFT:
			_close()
		return
	if mb.button_index == MOUSE_BUTTON_LEFT:
		var close_r := Rect2(panel.position.x + PANEL_W - 58.0, panel.position.y + 8.0, 50.0, 50.0)
		if close_r.has_point(mb.position):
			_close()
		return
	if mb.button_index == MOUSE_BUTTON_WHEEL_UP or mb.button_index == MOUSE_BUTTON_WHEEL_DOWN:
		var win_h := maxf(0.0, panel.size.y - 150.0 - 14.0)
		var scroll_max := maxf(0.0, _content_h() - win_h)
		if scroll_max > 0.0:
			var step := 42.0
			if mb.button_index == MOUSE_BUTTON_WHEEL_DOWN:
				step = -step
			_scroll = clampf(_scroll - step, 0.0, scroll_max)
			queue_redraw()

