class_name NetRosterPanel
extends Control
## P3c：接管客户端的「属性 C / 队伍 T」面板——host `_rpc_roster` 行 + own 快照 → 队伍名册。
## P3g：行 >16 段时直接用 host 烘焙字段（[16]总经济 [17]AI [18]职业 [19]阵亡 [20][21]复活读秒
##   [22]属性徽章 [23]技能行 [24]装备行），阵亡英雄也进名单并压暗；≤16 段旧载荷走近似回退。
## 版式对齐 host UI_Manager._create_hero_detail_panel / _refresh_hero_detail_panel：
## 全屏 0.4 遮罩 + 居中 2160 宽满高黑底(0.88)面板 + 标题「战场信息」(44,16) 28 金 +
## 副标题 (48,58) 13 灰 + 金线 (44,82) 360×3 + 右上 ×（-56..-6 / 6..56，26 号）+ 团队统计头
## （我方 青 / VS 金 / 敌方 红，font_main+2/+4）+ 按总经济降序的单列英雄卡（圆角 8、队伍底色、
## 左侧 4px 队伍描边、自己加金边）→ 卡内 60px 头像盘 / 状态·名字·Lv / 属性圆徽章行 + 技能行 /
## KDA·总经济·装备行。attr 视图在名单下方追加 host attribute_panel 同款属性表
## （2 列 ×9 行、行高 26s、列宽 200s、基础白 / +装备绿 / +增益橙）。
## 只读复刻：不参与模拟、绝不回写 host。面板打开时自驱动 0.5s 节流请求 C_ROSTER。
## 画布与 host 同处 2400×1400 stretch 坐标；字号与属性表按 host ui_scale() 同公式缩放。

const REQ_INTERVAL := 0.5
const BASE_W := 2400.0            # host ui_scale() 的基准虚拟宽

# —— host _create_hero_detail_panel 几何（虚拟画布单位，本身不乘 ui_scale）——
const PANEL_W := 2160.0           # offset_left/right = ∓1080
const CONTENT_TOP := 78.0         # scroll.offset_top
const TEAM_HDR_H := 55.0
const CARD_GAP := 4.0             # vbox separation
const CARD_MIN_H := 52.0
const DISC_W := 60.0              # HeroDisc custom_minimum_size.x
const LEFT_W := 180.0             # left_box custom_minimum_size.x
const RIGHT_W := 340.0            # right_box custom_minimum_size.x
const CLOSE_W := 50.0             # close_btn offset -56..-6 / 6..56

# —— host 配色（UI_Manager 同值）——
const C_ALLY := Color(0.0, 0.886, 1.0)
const C_ENEMY := Color(1.0, 0.33, 0.264)
const C_ALLY_BG := Color(0.0, 0.22, 0.4, 0.78)
const C_ENEMY_BG := Color(0.42, 0.07, 0.07, 0.78)
const C_SUB := Color(0.75, 0.78, 0.84, 0.9)
const C_GOLD_LINE := Color(1.0, 0.82, 0.2, 0.3)
const C_OWN_EDGE := Color(1.0, 0.85, 0.3, 0.85)
const C_DIM := Color(0, 0, 0, 0.4)
const C_PANEL_BG := Color(0, 0, 0, 0.88)

# —— host attribute_panel 属性表（_create_attribute_panel / _build_attr_row 同值）——
const ATTR_ROWS_PER_COL := 9
const ATTR_ROW_H := 26.0
const ATTR_COL_W := 200.0
const ATTR_GAP := 12.0
const ATTR_PAD := 12.0
const ATTR_LEGEND_H := 24.0
const C_ATTR_NAME := Color(0.92, 0.92, 0.92, 0.95)
const C_ATTR_BASE := Color.WHITE
const C_ATTR_EQUIP := Color(0.45, 0.9, 0.4)
const C_ATTR_BUFF := Color(1.0, 0.62, 0.25)

var rows := []        # host roster payload（见 NetSession._pack_roster_row）
var own := {}         # 本帧 own 快照（高亮自己 / 属性表 own.sa）
var view := "team"    # "attr" | "team"
var _req_at := 0.0
var _f := UiKit.font()
var _sb_ally: StyleBoxFlat = null
var _sb_enemy: StyleBoxFlat = null
var _sb_own: StyleBoxFlat = null
var _sb_dim: StyleBoxFlat = null

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_STOP
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	visible = false
	_sb_ally = _card_sb(C_ALLY_BG, C_ALLY)
	_sb_enemy = _card_sb(C_ENEMY_BG, C_ENEMY)
	_sb_own = UiKit.flat(0.0, 8, 2, C_OWN_EDGE, Color(0, 0, 0, 0), 0.0)
	_sb_dim = UiKit.flat(0.38, 8, 0, Color.TRANSPARENT, Color(0, 0, 0, 0.38), 0.0)

# host 英雄卡 StyleBox：圆角 8 + 左侧 4px 队伍描边 + 其余 1px，内边距 6/2
func _card_sb(bg: Color, border: Color) -> StyleBoxFlat:
	var sb := UiKit.flat(bg.a, 8, 1, border, bg, 6.0)
	sb.border_width_left = 4
	sb.content_margin_top = 2
	sb.content_margin_bottom = 2
	return sb

func _process(delta: float) -> void:
	if not visible:
		return
	# 打开期间 0.5s 节流拉取 + 读最新行（host 立即回 _rpc_roster）
	var now := Time.get_ticks_msec() / 1000.0
	if now - _req_at >= REQ_INTERVAL:
		_req_at = now
		NetSession.send_command([NetSession.C_ROSTER])
	rows = NetSession.get_roster_payload()
	queue_redraw()

# host ui_scale() 同公式：maxf(1, 视口宽/2400) × 1.35（不写死分辨率）
func _us() -> float:
	return UiKit.scale()

func _fs(base: float) -> float:
	return float(int(round(base * _us())))

func _text(pos: Vector2, txt: String, sz: float, col: Color) -> void:
	var isz := int(round(sz))
	draw_string(_f, pos + Vector2(1.5, 1.5), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, isz, Color(0, 0, 0, 0.55))
	draw_string(_f, pos, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, isz, col)

func _tw(txt: String, sz: float) -> float:
	return _f.get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, int(round(sz))).x

func _th(sz: float) -> float:
	return _f.get_height(int(round(sz)))

func _asc(sz: float) -> float:
	return _f.get_ascent(int(round(sz)))

# 纵向居中堆叠若干行文字（等价 host VBoxContainer）
func _vstack(x: float, center_y: float, txts: Array, szs: Array, cols: Array, sep: float) -> void:
	var total := 0.0
	for i in range(txts.size()):
		total += _th(szs[i])
		if i > 0:
			total += sep
	var y := center_y - total * 0.5
	for i in range(txts.size()):
		_text(Vector2(x, y + _asc(szs[i])), str(txts[i]), float(szs[i]), cols[i])
		y += _th(szs[i]) + sep

func _panel_rect() -> Rect2:
	var vp := get_viewport()
	var area := (vp.get_visible_rect().size if vp != null else size)
	# host hero_detail_panel：水平居中 2160 宽、垂直满高
	return Rect2(Vector2((area.x - PANEL_W) * 0.5, 0.0), Vector2(PANEL_W, area.y))

# host close_btn：锚右上，offset -56..-6 / 6..56
func _close_rect(p: Rect2) -> Rect2:
	return Rect2(Vector2(p.end.x - 56.0, p.position.y + 6.0), Vector2(CLOSE_W, CLOSE_W))

# host attribute_panel 尺寸：2列×9行 + 图例，全部 × ui_scale
func _attr_w() -> float:
	var s := _us()
	return ATTR_PAD * 2.0 * s + ATTR_COL_W * 2.0 * s + ATTR_GAP * s

func _attr_h() -> float:
	var s := _us()
	return ATTR_PAD * 2.0 * s + ATTR_LEGEND_H * s + ATTR_ROW_H * s * float(ATTR_ROWS_PER_COL)

# host 卡片高度公式（panel_h=1000、统计头 55、卡间距 4）→ 再按可用高度收紧防溢出
func _metrics(n: int, avail: float) -> Dictionary:
	if n <= 0:
		return {"h": CARD_MIN_H, "main": 12.0, "sub": 11.0}
	var h := maxf(CARD_MIN_H, (1000.0 - TEAM_HDR_H - CARD_GAP * float(n)) / float(n))
	h = maxf(CARD_MIN_H, minf(h, (avail - CARD_GAP * float(n)) / float(n)))
	var fm := float(maxi(12, int(h / 4.2)))
	return {"h": h, "main": fm, "sub": maxf(11.0, fm - 2.0)}

# host：按总经济降序（新载荷用 total_gold_earned，旧载荷回退当前金币）
func _sorted() -> Array:
	var out := rows.duplicate()
	out.sort_custom(_sort_by_gold)
	return out

func _sort_by_gold(a: Array, b: Array) -> bool:
	return _gold_total(a) > _gold_total(b)

# 团队合计：经济=total_gold 合计 / 击杀 合计 / 经验（P3h：仅行 >25 段时求和并标 has_exp）
func _team_sum(list: Array, team: int) -> Array:
	var gold := 0
	var exp := 0
	var kills := 0
	var has_exp := false
	for e in list:
		if int(e[2]) != team:
			continue
		gold += _gold_total(e)
		kills += int(e[6])
		if e.size() > 25:
			exp += int(e[25])
			has_exp = true
	return [gold, exp, kills, has_exp]

func _gold_txt(v: int) -> String:
	if v >= 1000:
		return "%.1fk" % (float(v) / 1000.0)
	return str(v)

func _draw() -> void:
	var vp := get_viewport()
	if vp == null:
		return
	var area := vp.get_visible_rect().size
	var p := _panel_rect()
	# 全屏遮罩（host hero_detail_dim 0.4）+ 黑底面板（host _apply_panel_style 0.88，无圆角无描边）
	draw_rect(Rect2(Vector2.ZERO, area), C_DIM)
	draw_rect(p, C_PANEL_BG)
	# 标题区：host hd_title(44,16) 28 金 / hd_sub(48,58) 13 灰 / 金线(44,82) 360×3
	var t_sz := _fs(28)
	_text(Vector2(p.position.x + 44.0, p.position.y + 16.0 + _asc(t_sz)), "战场信息", t_sz, UiKit.C_GOLD)
	var s_sz := _fs(13)
	var sub := "按总经济排序 · 点击空白处关闭"
	if view == "attr":
		sub = "按总经济排序 · 下方为本机英雄属性 · 点击空白处关闭"
	_text(Vector2(p.position.x + 48.0, p.position.y + 58.0 + _asc(s_sz)), sub, s_sz, C_SUB)
	draw_rect(Rect2(p.position + Vector2(44.0, 82.0), Vector2(360.0, 3.0)), C_GOLD_LINE)
	# 右上关闭 ×（host close_btn 50×50 / 字号 26）
	var cb := _close_rect(p)
	var csb := UiKit.flat(0.95, 5, 1, Color(1, 1, 1, 0.25), Color(0.22, 0.23, 0.26, 0.95), 0.0)
	draw_style_box(csb, cb)
	var x_sz := _fs(26)
	_text(Vector2(cb.position.x + (CLOSE_W - _tw("×", x_sz)) * 0.5,
			cb.position.y + (CLOSE_W - _th(x_sz)) * 0.5 + _asc(x_sz)), "×", x_sz, Color(1, 1, 1, 0.9))
	# 名单：团队统计头 + 按总经济降序的单列英雄卡
	var list := _sorted()
	var attr_h := (_attr_h() + 16.0) if view == "attr" else 0.0
	var avail := p.size.y - CONTENT_TOP - TEAM_HDR_H - 20.0 - attr_h - 16.0
	var met := _metrics(list.size(), avail)
	var card_h: float = float(met["h"])
	var fm: float = float(met["main"])
	var fs_: float = float(met["sub"])
	var self_nid := int(own.get("nid", -1))
	var y_hdr := p.position.y + CONTENT_TOP
	_draw_team_header(p, y_hdr, list, _fs(fm + 2.0), _fs(fm), _fs(fm + 4.0))
	draw_rect(Rect2(p.position.x + 8.0, y_hdr + TEAM_HDR_H + 6.0, PANEL_W - 16.0, 1.0), Color(1, 1, 1, 0.12))
	var y_card := y_hdr + TEAM_HDR_H + 16.0
	for e in list:
		_draw_card(Rect2(Vector2(p.position.x, y_card), Vector2(PANEL_W, card_h)),
				e, self_nid, _fs(fm), _fs(fs_))
		y_card += card_h + CARD_GAP
	if view == "attr":
		_draw_attr_table(Vector2(p.position.x + 30.0, y_card + 16.0), self_nid)

# host team_hbox：我方(青) 经济/击杀 → VS(金) → 敌方(红)，块内标题在上、统计在下
func _draw_team_header(p: Rect2, y: float, list: Array, title_sz: float, info_sz: float, vs_sz: float) -> void:
	var ally := _team_sum(list, 0)
	var enemy := _team_sum(list, 1)
	var has_exp := bool(ally[3]) or bool(enemy[3])
	var a_title := "我方"
	var a_info := _team_info(ally, has_exp)
	var e_title := "敌方"
	var e_info := _team_info(enemy, has_exp)
	var vs := " VS "
	var x := p.position.x
	_draw_team_block(Vector2(x, y + 2.0), a_title, title_sz, C_ALLY, a_info, info_sz)
	x += maxf(_tw(a_title, title_sz), _tw(a_info, info_sz)) + 50.0
	_text(Vector2(x, y + 2.0 + _asc(vs_sz)), vs, vs_sz, UiKit.C_GOLD)
	x += _tw(vs, vs_sz) + 50.0
	_draw_team_block(Vector2(x, y + 2.0), e_title, title_sz, C_ENEMY, e_info, info_sz)

# host 团队头信息行：`经济: %s  经验: %d  击杀: %d`；旧载荷（无 [25] exp）省略经验段
func _team_info(t: Array, has_exp: bool) -> String:
	if has_exp:
		return "经济: %s  经验: %d  击杀: %d" % [_gold_txt(int(t[0])), int(t[1]), int(t[2])]
	return "经济: %s  击杀: %d" % [_gold_txt(int(t[0])), int(t[2])]

func _draw_team_block(pos: Vector2, title: String, t_sz: float, t_col: Color, info: String, i_sz: float) -> void:
	_text(Vector2(pos.x, pos.y + _asc(t_sz)), title, t_sz, t_col)
	_text(Vector2(pos.x, pos.y + _th(t_sz) + 4.0 + _asc(i_sz)), info, i_sz, Color.WHITE)

func _draw_card(card: Rect2, e: Array, self_nid: int, fm: float, fs_: float) -> void:
	var is_ally := int(e[2]) == 0
	var is_own := int(e[0]) == self_nid
	var dead := _is_dead(e)
	# 卡片底色/描边（host StyleBoxFlat：我方蓝底青边 / 敌方红底红边），自己额外加金边
	draw_style_box(_sb_ally if is_ally else _sb_enemy, card)
	if dead:
		draw_style_box(_sb_dim, card)   # 阵亡压暗一档
	if is_own:
		draw_style_box(_sb_own, card)
	var cy := card.position.y + card.size.y * 0.5
	var x := card.position.x + 10.0   # border_left 4 + content_margin 6
	# 1) 头像盘（host HeroDisc 60 宽：阵营外环 + 血量状态弧 + 职业字）
	var maxhp := maxf(1.0, float(e[5]))
	var ratio := clampf(float(e[4]) / maxhp, 0.0, 1.0)
	_draw_disc(Rect2(Vector2(x, card.position.y + 2.0), Vector2(DISC_W, card.size.y - 4.0)),
			is_ally, ratio, _role_of(e), dead)
	x += DISC_W + 8.0
	# 2) 状态 / 名字 / 等级（host left_box 180 宽：font_main、font_main、font_sub，1px 行距）
	var nm := str(e[1])
	if _is_ai(e):
		nm += "[AI]"
	var name_col := Color.WHITE if is_ally else Color(1.0, 0.55, 0.55)
	if is_own:
		nm = ">> " + nm
		name_col = Color(1.0, 0.88, 0.4)
	# 状态行：host 阵亡→复活读秒(红) / hp<30%→残血(橙) / 其余 存活(绿)
	var st_txt := "存活"
	var st_col := Color.GREEN
	if dead:
		st_txt = _dead_text(e)
		st_col = Color.RED
	elif ratio < 0.3:
		st_txt = "残血"
		st_col = Color.ORANGE
	_vstack(x, cy, [st_txt, nm, "Lv.%d" % int(e[3])], [fm, fm, fs_],
			[_dim(st_col, dead), _dim(name_col, dead), _dim(UiKit.C_GOLD, dead)], 1.0)
	# 3) 中间（属性圆徽章 + 技能行）、4) 右侧（KDA/总经济/装备）；右列按装备文本宽撑开（host 每件 min 80）
	var right_w := maxf(RIGHT_W, _equip_w(e, fs_))
	var mid_x := x + LEFT_W + 8.0
	var mid_r := card.end.x - 7.0 - right_w - 8.0
	_draw_mid(mid_x, mid_r, cy, e, is_own, fs_, dead)
	var rx := card.end.x - 7.0 - right_w
	_draw_right(Rect2(Vector2(rx, card.position.y + 2.0), Vector2(right_w, card.size.y - 4.0)),
			e, cy, fs_, dead)

# 装备行列宽：host eq_hbox 每件 min 80 宽 + 3 间距（文本随主动 CD 后缀变宽）
func _equip_w(e: Array, fs_: float) -> float:
	var eqs := _equip_list(e)
	var eq_sz := maxf(10.0, fs_ - 1.0)
	var w := 0.0
	var n := mini(eqs.size(), 6)
	if n <= 0:
		return 0.0
	for i in range(n):
		var t := str(eqs[i][0])
		w += maxf(80.0, _tw(t, eq_sz)) + 3.0
	return w

# host HeroDisc：暗内盘 + 阵营色外环 + 血量弧(绿→黄→红) + 职业字；阵亡灰环、无血量弧
func _draw_disc(box: Rect2, is_ally: bool, ratio: float, role: String, dead: bool) -> void:
	var c := box.position + box.size * 0.5
	var r := minf(box.size.x, box.size.y) * 0.5 - 2.0
	if r <= 4.0:
		return
	var st := _role_style(role)
	var team_col := C_ALLY if is_ally else C_ENEMY
	if dead:
		team_col = Color(0.32, 0.32, 0.36)
	draw_circle(c, r, Color(0.02, 0.04, 0.07, 0.92))
	draw_arc(c, r, 0, TAU, 32, team_col, 3.0, true)
	if not dead and ratio > 0.0:
		var hc := Color(0.35, 1.0, 0.5) if ratio > 0.5 else (Color(1.0, 0.85, 0.25) if ratio > 0.25 else Color(1.0, 0.3, 0.3))
		draw_arc(c, r - 5.0, -PI / 2.0, -PI / 2.0 + TAU * ratio, 24, hc, 3.0, true)
	var gs := float(int(r * 0.8))
	if gs < 6.0:
		return
	var gcol: Color = st[1]
	if dead:
		gcol = Color(0.6, 0.6, 0.64)
	draw_string(_f, Vector2(c.x - r, c.y + gs * 0.2), str(st[0]),
			HORIZONTAL_ALIGNMENT_CENTER, r * 2.0, int(gs), gcol.lightened(0.25))

# host HeroDisc._role_style：职业 → [单字, 主题色]
func _role_style(role: String) -> Array:
	match role:
		"刺客": return ["刺", Color(0.95, 0.55, 0.95)]
		"法师": return ["法", Color(0.55, 0.62, 1.0)]
		"射手": return ["射", Color(1.0, 0.62, 0.28)]
		"战士": return ["战", Color(1.0, 0.42, 0.3)]
		"辅助": return ["辅", Color(0.45, 0.9, 0.55)]
		_: return ["英", Color(0.9, 0.9, 0.9)]

# —— P3g 新载荷（行 >16 段）读取；旧载荷保持原近似 ——
func _is_new(e: Array) -> bool:
	return e.size() > 16

func _gold_total(e: Array) -> int:
	return int(e[16]) if _is_new(e) else int(e[9])

func _is_ai(e: Array) -> bool:
	return e.size() > 17 and int(e[17]) == 1

func _role_of(e: Array) -> String:
	return str(e[18]) if e.size() > 18 else ""

func _is_dead(e: Array) -> bool:
	return e.size() > 19 and int(e[19]) == 1

# host 状态行：阵亡 → 「阵亡 Ns」读秒（红）
func _dead_text(e: Array) -> String:
	var rem := float(e[20]) if e.size() > 20 else 0.0
	return "阵亡 %ds" % int(ceil(rem))

func _chips_of(e: Array) -> Array:
	var out: Array = []
	if e.size() > 22:
		out = e[22]
	return out

func _skills_of(e: Array) -> Array:
	var out: Array = []
	if e.size() > 23:
		out = e[23]
	return out

func _equips_of(e: Array) -> Array:
	var out: Array = []
	if e.size() > 24:
		out = e[24]
	return out

# 阵亡卡压暗：内容色统一降亮
func _dim(col: Color, dead: bool) -> Color:
	return col.darkened(0.4) if dead else col

# 中间区：属性圆徽章行（host row_attrs：图标 20 + 4 间距 + 数值 tint.lightened(0.35)，chip 间距 14）
# + 技能行（host row_skills）。新载荷直接画 host 烘焙好的 [glyph,Color,text] / [text,Color]；
# 旧载荷回退到基础 16 段近似（攻/法/甲/抗/速 + 本机英雄 own 技能）。
func _draw_mid(x0: float, x1: float, cy: float, e: Array, is_own: bool, fs_: float, dead: bool) -> void:
	var chips := _chips_of(e) if _is_new(e) else _legacy_chips(e)
	var skills := _skills_of(e) if e.size() > 23 else _skill_texts(is_own)
	var icon := 20.0
	var r1 := maxf(icon, _th(fs_))
	var has_sk := skills.size() > 0
	var r2 := _th(fs_) if has_sk else 0.0
	var total := r1 + (1.0 + r2 if has_sk else 0.0)
	var y1 := cy - total * 0.5
	var cx := x0
	for c in chips:
		var t := str(c[2]) if c.size() > 2 else ""
		if cx + icon + 4.0 + _tw(t, fs_) > x1:
			break
		var tint: Color = c[1] if c.size() > 1 else Color.WHITE
		_draw_stat_icon(Vector2(cx + icon * 0.5, y1 + r1 * 0.5), icon * 0.5,
				str(c[0]), _dim(tint, dead))
		_text(Vector2(cx + icon + 4.0, y1 + (r1 - _th(fs_)) * 0.5 + _asc(fs_)), t, fs_,
				_dim(tint.lightened(0.35), dead))
		cx += icon + 4.0 + _tw(t, fs_) + 14.0
	if not has_sk:
		return
	var y2 := y1 + r1 + 1.0
	var sx := x0
	for c in skills:
		var t := str(c[0])
		if sx + _tw(t, fs_) > x1:
			break
		var col: Color = c[1] if c.size() > 1 else Color.WHITE
		_text(Vector2(sx, y2 + _asc(fs_)), t, fs_, _dim(col, dead))
		sx += _tw(t, fs_) + 8.0

# 旧载荷（16 段）徽章：只有 血/攻/法/甲/抗/速
func _legacy_chips(e: Array) -> Array:
	return [
		["heart", Color(0.45, 1.0, 0.55), "%d/%d" % [int(e[4]), int(e[5])]],
		["sword", Color(1.0, 0.62, 0.24), "%d" % int(e[11])],
		["spark", Color(0.72, 0.5, 1.0), "%d" % int(e[12])],
		["shield", Color(1.0, 0.78, 0.3), "%d" % int(e[13])],
		["gem", Color(0.4, 0.88, 1.0), "%d" % int(e[14])],
		["chev", Color(0.45, 0.9, 0.7), "%.0f" % float(e[15])],
	]

# 旧载荷技能行：仅本机英雄能用 own 快照（levels/cd/summoner_name/summoner_cd）近似
func _skill_texts(is_own: bool) -> Array:
	var out: Array = []
	if not is_own:
		return out
	var lv: Array = own.get("levels", [])
	var cd: Array = own.get("cd", [])
	for i in range(mini(3, lv.size())):
		if int(lv[i]) <= 0:
			continue
		var rem := float(cd[i]) if i < cd.size() else 0.0
		var cd_t := "(%.1fs)" % rem if rem > 0.0 else "(就绪)"
		out.append(["技能%d Lv.%d %s" % [i + 1, int(lv[i]), cd_t],
				Color.GRAY if rem > 0.0 else Color.LIGHT_CYAN])
	var sn := str(own.get("summoner_name", ""))
	if sn != "":
		var scd := float(own.get("summoner_cd", 0.0))
		out.append(["%s %s" % [sn, ("(%.1fs)" % scd if scd > 0.0 else "(就绪)")],
				Color.GRAY if scd > 0.0 else UiKit.C_GOLD])
	return out

# 装备行：新载荷用 host 烘焙文本（含主动 CD），旧载荷回退 ItemDatabase 名称
func _equip_list(e: Array) -> Array:
	var eqs := _equips_of(e) if e.size() > 24 else []
	if not eqs.is_empty() or e.size() > 24:
		return eqs
	var out: Array = []
	var ek: Array = e[10]
	for i in range(mini(ek.size(), 6)):
		var iid := str(ek[i])
		var it := ItemDatabase.get_item(iid)
		out.append([str(it.get("name", iid)) if not it.is_empty() else iid, Color.LIGHT_GREEN])
	return out

# 右侧：host right_box(340) —— KDA 白 / 总经济 金 / 装备行（host 烘焙文本+配色，每件 min 80 宽、间距 3）
func _draw_right(box: Rect2, e: Array, cy: float, fs_: float, dead: bool) -> void:
	var eq_sz := maxf(10.0, fs_ - 1.0)
	var r1 := _th(fs_)
	var r3 := _th(eq_sz)
	var total := r1 * 2.0 + 2.0 + r3
	var y := cy - total * 0.5
	_text(Vector2(box.position.x, y + _asc(fs_)),
			"K: %d  D: %d  A: %d" % [int(e[6]), int(e[7]), int(e[8])], fs_, _dim(Color.WHITE, dead))
	y += r1 + 1.0
	_text(Vector2(box.position.x, y + _asc(fs_)), "总经济: %d" % _gold_total(e), fs_, _dim(UiKit.C_GOLD, dead))
	y += r1 + 1.0
	var eqs := _equip_list(e)
	if eqs.is_empty():
		_text(Vector2(box.position.x, y + _asc(eq_sz)), "装备: 无", eq_sz, _dim(Color.DIM_GRAY, dead))
		return
	var x := box.position.x
	for i in range(mini(eqs.size(), 6)):
		var it: Array = eqs[i]
		var t := str(it[0])
		var col: Color = it[1] if it.size() > 1 else Color.LIGHT_GREEN
		_text(Vector2(x, y + _asc(eq_sz)), t, eq_sz, _dim(col, dead))
		x += maxf(80.0, _tw(t, eq_sz)) + 3.0

# host StatIcon：彩色圆徽章 + 矢量图形（爱心/剑/四芒星/盾/宝石/双箭头）
func _draw_stat_icon(c: Vector2, r: float, shape: String, tint: Color) -> void:
	draw_circle(c, r, tint.darkened(0.62))
	draw_arc(c, r, 0, TAU, 24, tint, 2.0, true)
	var k := r * 0.72
	var col := tint.lightened(0.35)
	match shape:
		"heart":
			draw_circle(c + Vector2(-0.42, -0.12) * k, k * 0.5, col)
			draw_circle(c + Vector2(0.42, -0.12) * k, k * 0.5, col)
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-0.92, 0.0) * k, c + Vector2(0.92, 0.0) * k, c + Vector2(0.0, 0.98) * k]), col)
		"sword":
			var e0 := c + Vector2(-0.5, 0.7) * k
			var e1 := c + Vector2(0.85, -0.55) * k
			var d := (e1 - e0).normalized()
			var n := Vector2(-d.y, d.x)
			draw_line(e0 - n * k * 0.28, e0 + n * k * 0.28, col, 1.8)
			draw_line(e0, e1, col, 3.0)
			draw_circle(e0 - d * k * 0.18, k * 0.1, col)
		"spark":
			var pts := PackedVector2Array()
			for i in range(8):
				var ang := float(i) * PI / 4.0 + PI / 8.0
				var rad := k * 0.85 if i % 2 == 0 else k * 0.2
				pts.append(c + Vector2(cos(ang), sin(ang)) * rad)
			draw_colored_polygon(pts, col)
		"shield":
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-0.82, -0.7) * k, c + Vector2(0.82, -0.7) * k,
				c + Vector2(0.82, 0.1) * k, c + Vector2(0.0, 0.96) * k,
				c + Vector2(-0.82, 0.1) * k]), col)
		"gem":
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(0.0, -0.92) * k, c + Vector2(0.66, -0.22) * k,
				c + Vector2(0.0, 0.92) * k, c + Vector2(-0.66, -0.22) * k]), col)
		"chev":
			for sx in PackedFloat32Array([0.0, 0.45]):
				var xo: float = c.x + sx * k
				draw_line(Vector2(xo - k * 0.3, c.y - k * 0.5), Vector2(xo + k * 0.05, c.y), col, 2.0)
				draw_line(Vector2(xo - k * 0.3, c.y + k * 0.5), Vector2(xo + k * 0.05, c.y), col, 2.0)
		"bolt":
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(0.15, -0.95) * k, c + Vector2(-0.7, 0.16) * k,
				c + Vector2(-0.05, 0.16) * k, c + Vector2(-0.15, 0.95) * k,
				c + Vector2(0.7, -0.16) * k, c + Vector2(0.05, -0.16) * k]), col)
		"drop":
			draw_circle(c + Vector2(0.0, -0.2) * k, k * 0.52, col)
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-0.52, -0.06) * k, c + Vector2(0.52, -0.06) * k, c + Vector2(0.0, 0.98) * k]), col)
		"cross":
			draw_arc(c, k * 0.4, 0, TAU, 24, col, 1.6, true)
			draw_line(c, c + Vector2(0, -1) * k * 0.68, col, 2.0)
			draw_line(c, c + Vector2(0, 1) * k * 0.68, col, 2.0)
			draw_line(c, c + Vector2(-1, 0) * k * 0.68, col, 2.0)
			draw_line(c, c + Vector2(1, 0) * k * 0.68, col, 2.0)
			draw_circle(c, k * 0.1, col)
		"dmg":
			draw_line(c + Vector2(-0.68, -0.68) * k, c + Vector2(0.68, 0.68) * k, col, 2.6)
			draw_line(c + Vector2(0.68, -0.68) * k, c + Vector2(-0.68, 0.68) * k, col, 2.6)
		"pierce":
			draw_line(c + Vector2(-0.85, 0.38) * k, c + Vector2(0.85, 0.38) * k, col, 2.0)
			draw_line(c + Vector2(0.0, 0.55) * k, c + Vector2(0.0, -0.6) * k, col, 2.2)
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(0.0, -0.98) * k, c + Vector2(-0.24, -0.56) * k, c + Vector2(0.24, -0.56) * k]), col)
		"tough":
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-0.8, -0.7) * k, c + Vector2(0.8, -0.7) * k,
				c + Vector2(0.8, 0.1) * k, c + Vector2(0.0, 0.95) * k,
				c + Vector2(-0.8, 0.1) * k]), col)
			draw_line(c + Vector2(-0.4, 0.05) * k, c + Vector2(-0.12, 0.33) * k, Color.WHITE, 2.2)
			draw_line(c + Vector2(-0.12, 0.33) * k, c + Vector2(0.42, -0.28) * k, Color.WHITE, 2.2)
		"clock":
			draw_arc(c, k * 0.68, 0, TAU, 28, col, 1.8, true)
			draw_line(c, c + Vector2(0, -0.4) * k, col, 1.8)
			draw_line(c, c + Vector2(0.36, 0) * k, col, 1.8)
			draw_circle(c, k * 0.07, col)

# C 视图属性段：完全照 host UI_Manager._create_attribute_panel / _build_attr_row ——
# 黑底 0.5 子面板 + 图例（基础 白 / +装备 绿 / +增益 橙）+ 2 列 × 9 行
# （行高 26s、列宽 200s、间距 12s、内边距 12s，字体 13s/图例 12s）。
func _draw_attr_table(pos: Vector2, _self_nid: int) -> void:
	var s := _us()
	var pad := ATTR_PAD * s
	var colw := ATTR_COL_W * s
	var gap := ATTR_GAP * s
	var row_h := ATTR_ROW_H * s
	var legend_h := ATTR_LEGEND_H * s
	draw_rect(Rect2(pos, Vector2(_attr_w(), _attr_h())), Color(0, 0, 0, 0.5))
	# 图例（host legend RichTextLabel 12s：基础 白 / +装备 #72e35f / +增益 #ffa04a）
	var lsz := _fs(12)
	var lx := pos.x + pad
	var ly := pos.y + pad + _asc(lsz)
	for lg in [["基础", Color.WHITE], ["+装备", C_ATTR_EQUIP], ["+增益", C_ATTR_BUFF]]:
		var lt := str(lg[0])
		_text(Vector2(lx, ly), lt, lsz, lg[1])
		lx += _tw(lt, lsz) + 12.0
	var sa: Array = own.get("sa", [])
	var cfg: Array = UiManager.ATTRIBUTE_ROWS
	var n := mini(cfg.size(), int(sa.size() / 3))
	var rsz := _fs(13)
	if n <= 0:
		_text(Vector2(pos.x + pad, pos.y + pad + legend_h + _asc(rsz)),
				"（等待 host 推送 own.sa 属性）", rsz, Color(1, 1, 1, 0.6))
		return
	for i in range(n):
		var c: Dictionary = cfg[i]
		var col := int(i / ATTR_ROWS_PER_COL)
		var ri := i % ATTR_ROWS_PER_COL
		var x0 := pos.x + pad + float(col) * (colw + gap)
		var y0 := pos.y + pad + legend_h + float(ri) * row_h
		_draw_attr_row(Vector2(x0, y0 + _asc(rsz)), str(c.get("name", "")), sa, i,
				float(c.get("mult", 1.0)), bool(c.get("pct", false)), rsz)

# host _build_attr_row：名字 0.92 灰 + 基础白 / +装备绿 / +增益橙（负值不加号），全 0 显示白色 0
func _draw_attr_row(at: Vector2, nm: String, sa: Array, i: int, mult: float, pct: bool, sz: float) -> void:
	_text(at, nm + "  ", sz, C_ATTR_NAME)
	var x := at.x + _tw(nm + "  ", sz)
	var cols: Array = [C_ATTR_BASE, C_ATTR_EQUIP, C_ATTR_BUFF]
	var wrote := false
	for k in range(3):
		var v := float(sa[i * 3 + k])
		if absf(v * mult) < 0.05:
			continue
		if k > 0 and v > 0.0:
			_text(Vector2(x, at.y), "+", sz, cols[k])
			x += _tw("+", sz)
		var t := _attr_txt(v, mult, pct)
		_text(Vector2(x, at.y), t, sz, cols[k])
		x += _tw(t, sz)
		wrote = true
	if not wrote:
		_text(Vector2(x, at.y), "0", sz, C_ATTR_BASE)

func _attr_txt(v: float, mult: float, pct: bool) -> String:
	var x := v * mult
	if pct:
		var r := roundf(x * 10.0) / 10.0
		if absf(r - roundf(r)) < 0.05:
			return "%d%%" % int(roundf(r))
		return "%.1f%%" % r
	return "%d" % int(roundf(x))

func _gui_input(ev: InputEvent) -> void:
	var press := (ev is InputEventMouseButton and (ev as InputEventMouseButton).pressed and (ev as InputEventMouseButton).button_index == MOUSE_BUTTON_LEFT) or (ev is InputEventScreenTouch and (ev as InputEventScreenTouch).pressed)
	if not press:
		return
	var p := (ev as InputEventMouseButton).position if ev is InputEventMouseButton else (ev as InputEventScreenTouch).position
	var panel := _panel_rect()
	# host：点右上 × 或点面板外（hero_detail_dim 遮罩）→ 关闭
	if _close_rect(panel).grow(8.0).has_point(p):
		hide_panel()
		return
	if not panel.has_point(p):
		hide_panel()

func show_panel(v: String) -> void:
	view = v
	_req_at = 0.0
	rows = NetSession.get_roster_payload()
	UiKit.show_panel(self, 0.14)
	queue_redraw()

func hide_panel() -> void:
	UiKit.hide_panel(self, 0.10)
	queue_redraw()

