content.arguments:
{"command":"$p = (Resolve-Path 'scripts\net\NetShopPanel.gd')
function Replace-Func($path, $name, $body) {
  $lines = [System.IO.File]::ReadAllLines($path)
  $s = -1; for ($i=0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match "^func $name\(") { $s = $i; break } }
  if ($s -lt 0) { return "MISS $name" }
  $e = -1; for ($i=$s+1; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '^func ') { $e = $i-1; break } }
  if ($e -lt 0) { $e = $lines.Count-1 }
  $out = New-Object System.Collections.Generic.List[string]
  for ($i=0; $i -lt $s; $i++) { $out.Add($lines[$i]) }
  foreach ($l in ($body -split "`r?`n")) { $out.Add($l) }
  for ($i=$e+1; $i -lt $lines.Count; $i++) { $out.Add($lines[$i]) }
  [System.IO.File]::WriteAllLines($path, $out)
  return "OK $name (was $($e-$s+1))"
}

$header = @'
func _draw_header(panel: Rect2, rs: float) -> void:
	# host 标题：商店 + 金币 + 可买件数（P0）
	var fs := 20.0 * rs
	var n := 0
	for cat in _tab_labels:
		n += _cat_afford_count(str(cat))
	_text(Vector2(panel.position.x + 20.0 * rs, panel.position.y + 10.0 + fs * 0.82),
		"商店  |  金币: %d  |  可买 %d 件" % [_gold, n], fs, Color(1.0, 0.84, 0.0))
'@
Replace-Func $p '_draw_header' $header

$tabs = @'
func _draw_tabs(panel: Rect2, rs: float) -> void:
	var fs := 14.0 * rs
	var tw := 96.0 * rs
	var th := 42.0 * rs
	var gap := 6.0 * rs
	var x0 := panel.position.x + 20.0 * rs
	var y0 := panel.position.y + 45.0
	for i in range(_tab_labels.size()):
		var cat: String = _tab_labels[i]
		var r := Rect2(x0 + i * (tw + gap), y0, tw, th)
		_hot.append({"r": r, "k": "tab", "a": i})
		var tint: Color = _cat_style(cat)[1]
		var sel := i == _tab
		var bg := Color(0.18, 0.2, 0.26, 0.95) if sel else Color(0.05, 0.07, 0.11, 0.88)
		var bc := tint if sel else Color(1, 1, 1, 0.14)
		_box(r, bg, bc, 1, 9, 4 if sel else 0)
		var tc := Color(1.0, 0.92, 0.4) if sel else tint.lightened(0.55)
		_text_c(r.position.x + tw * 0.5, r.position.y + th * 0.5 + fs * 0.36, cat, fs, tc)
		# 可买件数角标
		var cnt := _cat_afford_count(cat)
		if cnt > 0:
			_text_r(r.end.x - 5.0, r.position.y + 12.0 * rs, str(cnt), 10.0 * rs, Color(0.55, 1.0, 0.6))
'@
Replace-Func $p '_draw_tabs' $tabs

$grid = @'
func _draw_grid(panel: Rect2, rs: float) -> void:
	var gx0 := panel.position.x + PANEL_W * GRID_L
	var gx1 := panel.position.x + PANEL_W * GRID_R
	var gy0 := panel.position.y + GRID_TOP
	var gy1 := panel.end.y + GRID_BOTTOM
	var list := _items_of_tab(_tab)
	# 选择记忆：仍存在则保留，否则回退到第一件买得起
	var keep := false
	for k_id in list:
		if str(k_id) == _sel:
			keep = true
	if not keep:
		var pick := ""
		for a_id in list:
			if _afford(str(a_id)):
				pick = str(a_id)
				break
		if pick == "" and not list.is_empty():
			pick = str(list[0])
		_sel = pick
	var gap := 6.0 * rs
	var row_gap := 4.0 * rs
	var card_w := ((gx1 - gx0) - gap) * 0.5
	var rows_vis := maxi(1, int((gy1 - gy0 + row_gap) / (CARD_H + row_gap)))
	var max_scroll := maxi(0, ceili(float(list.size()) / 2.0) - rows_vis)
	_scroll = clampi(_scroll, 0, max_scroll)
	var start := _scroll * 2
	for n in range(start, mini(list.size(), start + rows_vis * 2)):
		var id: String = str(list[n])
		var col := (n - start) % 2
		var row := int((n - start) * 0.5)
		var r := Rect2(gx0 + col * (card_w + gap), gy0 + row * (CARD_H + row_gap), card_w, CARD_H)
		_draw_card(r, id, rs)
'@
Replace-Func $p '_draw_grid' $grid

$card = @'
func _draw_card(r: Rect2, id: String, rs: float) -> void:
	_hot.append({"r": r, "k": "item", "a": id})
	var it: Dictionary = ItemDatabase.get_item(id)
	var tier: int = int(it.get("tier", 1))
	var tcol: Color = _tier_color(tier)
	var owned: bool = _slot_of(id) >= 0
	var can: bool = _afford(id)
	var sel: bool = id == _sel
	var pay: int = _need_cost(id)
	var diff: bool = pay < int(it.get("cost", 0))
	var rec: bool = id == _rec
	var bg := Color(0.1, 0.12, 0.2, 0.96) if sel else Color(0.04, 0.06, 0.1, 0.9)
	var bc := tcol if sel else Color(tcol.r, tcol.g, tcol.b, 0.35)
	_box(r, bg, bc, 1, 8)
	# 图标：品质色 item_icon（与 host / 推荐装 / 装备栏统一）
	_draw_item_icon(Rect2(r.position + Vector2(8.0, (CARD_H - BADGE) * 0.5), Vector2(BADGE, BADGE)), id)
	var fs_name := 16.0 * rs
	var fs_price := 13.0 * rs
	var fs_tag := 12.0 * rs
	var top := r.position.y + 8.0
	var bx := r.position.x + 8.0 + BADGE + 10.0
	_text(Vector2(bx, top + fs_name * 0.95), str(it.get("name", id)), fs_name, Color.WHITE)
