[System.IO.File]::WriteAllText($p, $t)
"synth=" + $t.Contains('for rid in it["requires"]:')
"actbar=" + $t.Contains("func _draw_action_bar")
"dby=" + $t.Contains("GRID_BOTTOM - 96.0")
"buysell_gone=" + (-not $t.Contains('"再买一件"'))
"call=" + $t.Contains("	_draw_action_bar(panel, rs)")

$p=(Resolve-Path 'scripts\net\NetShopPanel.gd'); $t=[System.IO.File]::ReadAllText($p)

# 1) 详情列可视高预留底部操作条
$t = $t -replace '(?m)^\tvar dby := panel\.end\.y \+ GRID_BOTTOM\r?$', "`tvar dby := panel.end.y + GRID_BOTTOM - 96.0"

# 2) 合成树：文本 → 图标路径
$oldSynth = @'
	if it.has("requires"):
		_text(Vector2(dx, y), "合成: " + ItemDatabase.get_synthesis_tree(_sel), 11.0 * rs, Color.GRAY)
		y += 11.0 * rs * 1.4 + 6.0
		if ItemDatabase.can_build(_sel, _equip):
			_text(Vector2(dx, y), "合成差价: %d金 (素材已拥有)" % ItemDatabase.get_synthesis_cost(_sel, _equip), 14.0 * rs, Color.GREEN)
			y += 14.0 * rs * 1.4 + 6.0
'@
$newSynth = @'
	if it.has("requires"):
		var bx2 := dx
		for rid in it["requires"]:
			var sid := str(rid)
			var rhas := _slot_of(sid) >= 0
			var irect := Rect2(bx2, y, 40.0, 40.0)
			_draw_item_icon(irect, sid)
			if not rhas:
				_box(irect, Color(0, 0, 0, 0.45), Color(0, 0, 0, 0), 0, 0)
			var ritem: Dictionary = ItemDatabase.get_item(sid)
			var ltxt := "已合成" if rhas else "+%d金" % int(ritem.get("cost", 0))
			_text(Vector2(bx2, y + 40.0 + 10.0 * rs), ltxt, 10.0 * rs, Color(0.45, 1.0, 0.5) if rhas else Color(1.0, 0.5, 0.42))
			bx2 += 46.0
		y += 40.0 + 10.0 * rs + 8.0
		if ItemDatabase.can_build(_sel, _equip):
			_text(Vector2(dx, y), "可立即合成（仍需补 %d 金）" % ItemDatabase.get_synthesis_cost(_sel, _equip), 12.0 * rs, Color(0.45, 1.0, 0.5))
			y += 12.0 * rs * 1.4 + 6.0
'@
$t = $t.Replace($oldSynth, $newSynth)

# 3) 移除详情内联购买/出售块，改为花费行（按钮固定在底部操作条）
$t = [regex]::Replace($t, '(?s)# 购买 / 出售（host：250×36 按钮 \+ 花费行 \+ 出售行）.*?(?=# 总装备加成)', @'
# 花费行（购买/出售按钮固定在面板底部，见 _draw_action_bar）
	_sep(dx, dx + dw - 8.0, y)
	y += 12.0
	_text(Vector2(dx, y), "实付: %d 金%s" % [_need_cost(_sel), " (含合成抵扣)" if _has_component(_sel) else ""], 12.0 * rs, Color(1.0, 0.82, 0.3))
	y += 12.0 * rs + 12.0


'@)

# 4) 底部操作条绘制
$t = $t.Replace("`t_draw_close(panel, rs)", "`t_draw_action_bar(panel, rs)`n`t_draw_close(panel, rs)")

# 5) 追加辅助函数
$t = $t + @'

# 品质色装备图标（与 host UiKit.item_icon 同源）
func _draw_item_icon(r: Rect2, id: String) -> void:
	var it: Dictionary = ItemDatabase.get_item(str(id))
	UiKit.item_icon(self, r, int(it.get("tier", 1)), str(it.get("name", id)))

func _cat_afford_count(cat: String) -> int:
	var n := 0
	for id in CATS.get(cat, []):
		var sid := str(id)
		var it: Dictionary = ItemDatabase.get_item(sid)
		if it.is_empty():
			continue
		if _slot_of(sid) >= 0 and int(it.get("tier", 1)) >= 3:
			continue
		if _afford(sid):
			n += 1
	return n

# 固定底部操作条：购买（金）/ 还差 N 金（红，禁用）/ 已拥有 + 出售
func _draw_action_bar(panel: Rect2, rs: float) -> void:
	if _sel == "":
		return
	var it: Dictionary = ItemDatabase.get_item(_sel)
	if it.is_empty():
		return
	var slot := _slot_of(_sel)
	var owned := slot >= 0
	var tier := int(it.get("tier", 1))
	var dx := panel.position.x + PANEL_W * DETAIL_L
	var dw := PANEL_W * (DETAIL_R - DETAIL_L)
	var bh := 46.0 * rs
	var by := panel.end.y - 42.0 - bh
	var can_more := not owned or tier < 3
	var pay := _need_cost(_sel)
	var br := Rect2(dx, by, dw * 0.62, bh)
	if not can_more:
		_box(br, Color(0.20, 0.22, 0.28, 0.95), Color(1, 1, 1, 0.14), 1, 8)
		_text_c(br.position.x + br.size.x * 0.5, br.position.y + bh * 0.5 + 15.0 * rs * 0.36, "已拥有", 15.0 * rs, Color(0.8, 0.84, 0.9))
	elif _gold >= pay and (_equip.size() < 6 or _has_component(_sel)):
		_hot.append({"r": br, "k": "buy", "a": _sel})
		_box(br, Color(0.88, 0.72, 0.16, 0.98), Color(1.0, 0.9, 0.45, 0.95), 1, 8)
		_text_c(br.position.x + br.size.x * 0.5, br.position.y + bh * 0.5 + 15.0 * rs * 0.36, "购买 %d 金" % pay, 15.0 * rs, Color(0.08, 0.07, 0.04))
	else:
		_box(br, Color(0.42, 0.20, 0.20, 0.95), Color(1.0, 0.45, 0.4, 0.7), 1, 8)
		var msg := ("还差 %d 金" % maxi(pay - _gold, 0)) if _gold < pay else "装备栏已满"
		_text_c(br.position.x + br.size.x * 0.5, br.position.y + bh * 0.5 + 14.0 * rs * 0.36, msg, 14.0 * rs, Color(1.0, 0.6, 0.55))
	if owned:
		var sr := Rect2(dx + dw * 0.64, by, dw * 0.36, bh)
		_hot.append({"r": sr, "k": "sell", "a": slot})
		_box(sr, Color(0.20, 0.30, 0.44, 0.95), Color(0.55, 0.75, 0.95, 0.8), 1, 8)
		_text_c(sr.position.x + sr.size.x * 0.5, sr.position.y + bh * 0.5 + 14.0 * rs * 0.36, "出售 +%d" % int(int(it.get("cost", 0)) * 0.7), 14.0 * rs, Color(0.75, 0.88, 1.0))
'@
[System.IO.File]::WriteAllText($p, $t)
"synth=" + $t.Contains('for rid in it["requires"]:')
"actbar=" + $t.Contains("func _draw_action_bar")
"dby=" + $t.Contains("GRID_BOTTOM - 96.0")
