content.text:
func _pack_hero(e: Node) -> Array:
	# 尾字段 idx9.. = mana / maxmana / shield / exp / exp_to_next（客户端世界血条按主机
	# HeroInfoControl 规格绘制蓝条/护盾，等级环经验弧用后两段）；idx14 = 暗印摘要（黄段+层数）
	return [_net_id_for(e), 0, e.team, e.global_position.x, e.global_position.z, e.health, _maxhp_of(e), e.level, str(e.display_name),
		e.mana, _maxmana_of(e), e.shield_remaining, int(e.exp), int(e.exp_to_next),
		_pack_lyf(e)]


func _maxmana_of(e: Node) -> float:
	if e.get("actual_mana_max") != null:
		return e.actual_mana_max
	if e.get("max_mana") != null:
		return e.max_mana
	return 0.0

---
func _pack_unit(e: Node, type_code: int, extra = null) -> Array:
	# 尾字段：extra(仅防御塔=被攻击标记 idx8) 之后恒接暗印摘要 lyf（idx8 或 idx9）——
	# 客户端按 type+长度守卫读取（旧 host 无此字段则默认空）
	var row := [_net_id_for(e), type_code, e.team, e.global_position.x, e.global_position.z, e.health, _maxhp_of(e), str(e.display_name)]
	if extra != null:
		row.append(extra)
	row.append(_pack_lyf(e))
	return row

# 李元芳暗印摘要：[[源英雄名, 层数, 预测实际伤害], …]（客户端血条黄段/层数文字 1:1 复刻主机）
func _pack_lyf(e: Node) -> Array:
	var out: Array = []
	if e.has_method("lyf_mark_summary"):
		for m in e.lyf_mark_summary():
			var src = m["source"]
---

content.arguments:
{"file_path":"C:\Users\18749\Documents\honor-king\scripts\ui\MinimapDraw.gd","content":"extends RefCounted
## 小地图共享绘制库（host Minimap.gd / client NetMiniMap.gd 同一套视觉，防止两端漂移）
## 只做「怎么画」：数据由两端各自喂（世界坐标 → 小地图坐标由调用方的 _world_to_minimap 完成）

const FONT: Font = ThemeDB.fallback_font

# ---------- 地形 ----------

## 世界坐标 → 地形底色（ae 版：河道渐变 + 分路暖灰 + 野区冷绿灰 + 轻微纹理）
static func world_color(wx: float, wz: float) -> Color:
	var jungle := Color(0.095, 0.125, 0.135)
	var lane := Color(0.215, 0.205, 0.185)
	var river := Color(0.075, 0.185, 0.275)
	var dist_diag: float = absf(wx - wz) / sqrt(2.0)
	if dist_diag <= 10.0:
		# 河道中心更亮，靠岸更暗（斜向柔光带，不是硬边）
		var u: float = 1.0 - dist_diag / 10.0
		return river.lerp(Color(0.16, 0.36, 0.46), 0.45 * u * u)
	var lane_farm: float = absf(absf(wx) - 55.0)
	var lane_mid: float = absf(wz + wx) / sqrt(2.0)
	var lane_clash: float = absf(absf(wz) - 55.0)
	if lane_farm <= 8.0 or lane_mid <= 8.0 or lane_clash <= 8.0:
		return lane
	# 野区：低频正弦做微弱色差，避免整块死板
	var n: float = sin(wx * 0.55) * cos(wz * 0.47)
	return jungle.lightened(maxf(n, 0.0) * 0.028)

## 生成地形底图：先在 120×120 逻辑网格取色，再双线性放大到 px，网格交界处压暗做出「等高线」
static func terrain_texture(px: int, map_size: float, grid: int = 120) -> ImageTexture:
	var cells := PackedColorArray()
	cells.resize(grid * grid)
	for gy in range(grid):
		for gx in range(grid):
			var wx: float = (float(gx) + 0.5) * map_size / float(grid) - map_size * 0.5
			var wz: float = (float(gy) + 0.5) * map_size / float(grid) - map_size * 0.5
			cells[gy * grid + gx] = world_color(wx, wz)
	var img := Image.create(px, px, false, Image.FORMAT_RGBA8)
	var step: float = float(grid) / float(px)
	for py in range(px):
		var fy: float = (float(py) + 0.5) * step - 0.5
		var y0: int = clampi(int(floor(fy)), 0, grid - 1)
		var y1: int = mini(y0 + 1, grid - 1)
		var ty: float = clampf(fy - float(y0), 0.0, 1.0)
		for px_i in range(px):
			var fx: float = (float(px_i) + 0.5) * step - 0.5
			var x0: int = clampi(int(floor(fx)), 0, grid - 1)
			var x1: int = mini(x0 + 1, grid - 1)
			var tx: float = clampf(fx - float(x0), 0.0, 1.0)
			var c00: Color = cells[y0 * grid + x0]
			var c10: Color = cells[y0 * grid + x1]
			var c01: Color = cells[y1 * grid + x0]
			var c11: Color = cells[y1 * grid + x1]
			var c: Color = c00.lerp(c10, tx).lerp(c01.lerp(c11, tx), ty)
			# 网格交界（分类跳变）压暗 → 河岸/分路边缘有细描边
			var v: float = absf(c00.r - c11.r) + absf(c00.g - c11.g) + absf(c00.b - c11.b)
			if v > 0.05:
				c = c.darkened(0.35)
			# 暗角：四周压暗，让底图与边框融合
			var nx: float = absf(float(px_i) / float(px) * 2.0 - 1.0)
			var ny: float = absf(float(py) / float(px) * 2.0 - 1.0)
			var vig: float = maxf(nx, ny)
			if vig > 0.82:
				c = c.darkened((vig - 0.82) / 0.18 * 0.55)
			img.set_pixel(px_i, py, c)
	return ImageTexture.create_from_image(img)

# ---------- 防御塔 ----------

## 塔分级：外塔方 / 内塔带内框 / 高地菱形 / 水晶六边形；血量底部填充；摧毁画灰 X
static func draw_turret(ci: CanvasItem, pos: Vector2, ratio: float, col: Color, ttype: String, alive: bool = true) -> void:
	var size: float = 8.0
	if ttype == "inner":
		size = 9.0
	elif ttype == "high":
		size = 10.0
	elif ttype == "crystal":
		size = 13.0
	var h: float = size * 0.5
	if ttype == "high" or ttype == "crystal":
		if ttype == "crystal":
			# 六边形
			var pts := PackedVector2Array()
			for i in range(6):
				var a: float = -PI / 2.0 + TAU * float(i) / 6.0
				pts.append(pos + Vector2(cos(a), sin(a)) * h)
			ci.draw_colored_polygon(pts, Color(0.05, 0.06, 0.08, 0.95))
			if alive and ratio > 0.0:
				ci.draw_colored_polygon(pts, Color(col.r, col.g, col.b, 0.85))
			ci.draw_polyline(pts + PackedVector2Array([pts[0]]), Color.BLACK, 1.2)
			if not alive:
				_dead_x(ci, pos, h + 1.0)
			return
		# 菱形
		var d := PackedVector2Array([pos + Vector2(0, -h), pos + Vector2(h, 0), pos + Vector2(0, h), pos + Vector2(-h, 0)])
		ci.draw_colored_polygon(d, Color(0.05, 0.06, 0.08, 0.95))
		if alive and ratio > 0.0:
			var fh: float = h * 2.0 * clampf(ratio, 0.0, 1.0)
