## 塔分级：外塔方 / 内塔带内框 / 高地菱形 / 水晶六边形；血量底部填充；摧毁画灰 X
static func draw_turret(ci: CanvasItem, pos: Vector2, ratio: float, col: Color, ttype: String, alive: bool = true) -> void:
	var size: float = 8.0
	if ttype == "inner":
		size = 9.0
	elif ttype == "high":
		size = 10.0
	elif ttype == "crystal":
		size = 13.0
	var h: float = size * 0.5
	if ttype == "high" or ttype == "crystal":
		if ttype == "crystal":
			# 六边形
			var pts := PackedVector2Array()
			for i in range(6):
				var a: float = -PI / 2.0 + TAU * float(i) / 6.0
				pts.append(pos + Vector2(cos(a), sin(a)) * h)
			ci.draw_colored_polygon(pts, Color(0.05, 0.06, 0.08, 0.95))
			if alive and ratio > 0.0:
				ci.draw_colored_polygon(pts, Color(col.r, col.g, col.b, 0.85))
			ci.draw_polyline(pts + PackedVector2Array([pts[0]]), Color.BLACK, 1.2)
			if not alive:
				_dead_x(ci, pos, h + 1.0)
			return
		# 菱形
		var d := PackedVector2Array([pos + Vector2(0, -h), pos + Vector2(h, 0), pos + Vector2(0, h), pos + Vector2(-h, 0)])
		ci.draw_colored_polygon(d, Color(0.05, 0.06, 0.08, 0.95))
		if alive and ratio > 0.0:
			var fh: float = h * 2.0 * clampf(ratio, 0.0, 1.0)
			ci.draw_rect(Rect2(pos.x - h, pos.y + h - fh, h * 2.0, fh), col)
		ci.draw_polyline(d + PackedVector2Array([d[0]]), Color.BLACK, 1.2)
		if not alive:
			_dead_x(ci, pos, h + 1.0)
		return
	# 方塔（外/内）
	ci.draw_rect(Rect2(pos - Vector2(h, h), Vector2(size, size)), Color(0.05, 0.06, 0.08, 0.95))
	if alive and ratio > 0.0:
		var fill_h: float = size * clampf(ratio, 0.0, 1.0)
		ci.draw_rect(Rect2(pos.x - h, pos.y + h - fill_h, size, fill_h), col)
	if ttype == "inner":
		ci.draw_rect(Rect2(pos - Vector2(h + 1.0, h + 1.0), Vector2(size + 2.0, size + 2.0)), Color.BLACK, false, 1.0)
	ci.draw_rect(Rect2(pos - Vector2(h, h), Vector2(size, size)), Color.BLACK, false, 1.0)
	if not alive:
		_dead_x(ci, pos, h + 1.0)

static func _dead_x(ci: CanvasItem, pos: Vector2, r: float) -> void:
	var gc := Color(0.75, 0.78, 0.82, 0.85)
	ci.draw_line(pos + Vector2(-r, -r), pos + Vector2(r, r), gc, 1.5)
	ci.draw_line(pos + Vector2(-r, r), pos + Vector2(r, -r), gc, 1.5)

# ---------- 英雄 ----------

## 英雄标记：阵营色圆 + 朝向箭头 + 内圈血量弧；本人白边加粗；阵亡灰点 + 复活倒计时
static func draw_hero(ci: CanvasItem, pos: Vector2, dir: Vector2, base: Color, hp_ratio: float, is_self: bool, dead: bool = false, respawn: float = 0.0) -> void:
	if dead:
		ci.draw_circle(pos, 6.0, Color(0.35, 0.38, 0.42, 0.85))
		ci.draw_arc(pos, 6.0, 0, TAU, 16, Color(0.62, 0.66, 0.72, 0.9), 1.2)
		if respawn > 0.0:
			ci.draw_string(FONT, pos + Vector2(-9.0, 4.0), str(int(ceil(respawn))), HORIZONTAL_ALIGNMENT_LEFT, -1, 11, Color.WHITE)
		return
	var col: Color = base.darkened(1.0 - clampf(hp_ratio, 0.0, 1.0))
	# 朝向箭头（先画，压在圆下）
	var d: Vector2 = dir.normalized() if dir.length() > 0.001 else Vector2(0, -1)
	var tip: Vector2 = pos + d * 11.0
	var side: Vector2 = Vector2(-d.y, d.x) * 4.0
	ci.draw_colored_polygon(PackedVector2Array([tip, pos + d * 4.0 + side, pos + d * 4.0 - side]), col.lightened(0.12))
	ci.draw_circle(pos, 6.0, col)
	if is_self:
		ci.draw_arc(pos, 7.6, 0, TAU, 20, Color(1, 1, 1, 0.95), 2.0)
	# 血量弧
	var ring_col: Color = base.lightened(0.55)
	ci.draw_arc(pos, 4.2, -PI / 2.0, -PI / 2.0 + TAU * clampf(hp_ratio, 0.0, 1.0), 16, ring_col, 1.5)

# ---------- 小兵 ----------

## 同类点合并：阈值内聚成一簇，返回 [{p:Vector2, n:int}]（减少糊成一片、也让「兵多」可读）
static func cluster(points: Array, thr: float) -> Array:
	var out: Array = []
	for p: Vector2 in points:
		var merged := false
		for c in out:
			var cp: Vector2 = c["p"]
			if cp.distance_to(p) <= thr:
				var n: int = int(c["n"]) + 1
				c["p"] = (cp * float(n - 1) + p) / float(n)
				c["n"] = n
				merged = true
				break
		if not merged:
			out.append({"p": p, "n": 1})
	return out

static func draw_clusters(ci: CanvasItem, clusters: Array, col: Color, r: float) -> void:
	for c in clusters:
		var p: Vector2 = c["p"]
		var n: int = int(c["n"])
		ci.draw_circle(p, r, col)
		if n > 1:
			ci.draw_string(FONT, p + Vector2(r * 0.6, -r * 0.6), "×" + str(n), HORIZONTAL_ALIGNMENT_LEFT, -1, 10, Color(1, 1, 1, 0.9))

# ---------- 摄像头视野框 ----------

## 相机看到的 4 个地面角点（世界 y=0 平面与视锥求交）→ 小地图矩形；失败返回空数组
static func viewport_corners(cam: Camera3D, to_minimap: Callable) -> Array:
	if cam == null or not is_instance_valid(cam):
		return []
	var vp: Vector2 = cam.get_viewport().get_visible_rect().size
	var corners: Array = []
	for sc: Vector2 in [Vector2(0, 0), Vector2(vp.x, 0), Vector2(vp.x, vp.y), Vector2(0, vp.y)]:
		var o: Vector3 = cam.project_ray_origin(sc)
		var d: Vector3 = cam.project_ray_normal(sc)
		if absf(d.y) < 0.0001:
			return []
		var t: float = -o.y / d.y
		if t <= 0.0:
			return []
		corners.append(to_minimap.call(o + d * t))
	return corners

static func draw_viewport(ci: CanvasItem, corners: Array, dashed: bool = false) -> void:
	if corners.size() != 4:
		return
	var col := Color(1, 1, 1, 0.38)
	var pts := PackedVector2Array([corners[0], corners[1], corners[2], corners[3], corners[0]])
	if dashed:
		for i in range(4):
			var a: Vector2 = pts[i]
			var b: Vector2 = pts[i + 1]
			var seg: int = 5
			for k in range(seg):
				if k % 2 == 0:
					ci.draw_line(a.lerp(b, float(k) / seg), a.lerp(b, float(k + 1) / seg), col, 1.5)
	else:
		ci.draw_polyline(pts, col, 1.5)
	# 内侧微光，避免细线在复杂地形上看不见
	ci.draw_polyline(pts, Color(1, 1, 1, 0.10), 4.0)
"}

