{"command":"$p=(Resolve-Path 'scripts\ui\MinimapDraw.gd'); $t=[System.IO.File]::ReadAllText($p)
$add = @'

# ---------- 视野迷雾 ----------

## 可见性网格：sources=[{p:Vector3(世界), r:float(世界半径)}]，返回 n×n 布尔格（true=有视野）
static func fog_grid(sources: Array, map_size: float, cell: float = 10.0) -> Array:
	var n: int = int(ceil(map_size / cell))
	var grid: Array = []
	for gy in range(n):
		var row: Array = []
		row.resize(n)
		for gx in range(n):
			row[gx] = false
		grid.append(row)
	for s in sources:
		var p: Vector3 = s["p"]
		var r: float = float(s["r"])
		var minx: int = clampi(int(floor((p.x - r + map_size * 0.5) / cell)), 0, n - 1)
		var maxx: int = clampi(int(floor((p.x + r + map_size * 0.5) / cell)), 0, n - 1)
		var minz: int = clampi(int(floor((p.z - r + map_size * 0.5) / cell)), 0, n - 1)
		var maxz: int = clampi(int(floor((p.z + r + map_size * 0.5) / cell)), 0, n - 1)
		for gy2 in range(minz, maxz + 1):
			for gx2 in range(minx, maxx + 1):
				if bool(grid[gy2][gx2]):
					continue
				var cx: float = (float(gx2) + 0.5) * cell - map_size * 0.5
				var cz: float = (float(gy2) + 0.5) * cell - map_size * 0.5
				if Vector2(cx - p.x, cz - p.z).length() <= r:
					grid[gy2][gx2] = true
	return grid

## 未探索/无视野格压暗（半透明黑），让「没视野」和「没人」可区分
static func draw_fog(ci: CanvasItem, grid: Array, size_px: float, alpha: float = 0.36) -> void:
	var n: int = grid.size()
	if n == 0:
		return
	var cs: float = size_px / float(n)
	var col := Color(0.0, 0.0, 0.0, alpha)
	for gy in range(n):
		var row: Array = grid[gy]
		for gx in range(n):
			if not bool(row[gx]):
				ci.draw_rect(Rect2(float(gx) * cs, float(gy) * cs, cs + 0.7, cs + 0.7), col)

# ---------- 目标（暴君/主宰）计时 ----------

## entries=[{label, t(秒), alive, color}]，贴小地图左下角两行
static func draw_objectives(ci: CanvasItem, entries: Array, size_px: float) -> void:
	var y: float = size_px - 8.0
	for i in range(entries.size() - 1, -1, -1):
		var e: Dictionary = entries[i]
		var alive: bool = bool(e.get("alive", false))
		var t: float = float(e.get("t", 0.0))
		var txt := ""
		if alive:
			txt = "%s 已刷新" % str(e.get("label", ""))
		elif t > 0.0:
			txt = "%s %02d:%02d" % [str(e.get("label", "")), int(t) / 60, int(t) % 60]
		if txt == "":
			continue
		var col: Color = Color(1.0, 0.86, 0.4) if alive else Color(1, 1, 1, 0.8)
		ci.draw_rect(Rect2(7.0, y - 8.0, 3.0, 3.0), e.get("color", Color.WHITE))
		ci.draw_string(FONT, Vector2(13.0, y), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 11, col)
		y -= 14.0
'@
[System.IO.File]::WriteAllText($p, $t + $add)
"ok=" + (Get-Content $p).Count","description":"Add fog and objective drawing helpers"}

