$t = $t.Replace("	# —— 我方防御塔被攻击警告圈（最上层）——`n", "	# —— 视野迷雾（我方英雄/小兵/塔 + 泉水；未覆盖区域压暗）——`n`tMinimapDraw.draw_fog(self, MinimapDraw.fog_grid(_fog_sources(), MAP_SIZE), MINIMAP_SIZE)`n`t# —— 暴君/主宰 刷新倒计时 ——`n`tMinimapDraw.draw_objectives(self, _obj_entries(), MINIMAP_SIZE)`n`t# —— 我方防御塔被攻击警告圈（最上层）——`n")
$t = $t + @'

# ---------- 视野迷雾 / 目标计时（与主机同源数据形状） ----------
func _fog_sources() -> Array:
	var out: Array = []
	for nid in views:
		var v: Dictionary = views[nid]
		var typ := int(v.get("type", -1))
		if typ == NET_JUNGLE:
			continue
		if int(v.get("team", 9)) != player_team:
			continue
		if float(v.get("hp", 0.0)) <= 0.0:
			continue
		var r := 14.0
		if typ == NET_MINION:
			r = 8.0
		elif typ == NET_TURRET:
			r = 16.0
		out.append({"p": _view_pos(v), "r": r})
	out.append({"p": Vector3(-58.0, 0.0, 58.0), "r": 24.0})
	return out

func _obj_entries() -> Array:
	if obj.size() < 4:
		return []
	return [
		{"label": "暴君", "t": float(obj[0]), "alive": int(obj[1]) != 0, "color": Color(0.95, 0.6, 0.35)},
		{"label": "主宰", "t": float(obj[2]), "alive": int(obj[3]) != 0, "color": Color(0.55, 0.8, 1.0)},
	]
'@
[System.IO.File]::WriteAllText($p,$t)
"var=" + $t.Contains("var obj: Array = []") + " draw=" + $t.Contains("draw_objectives(self") + " fog=" + $t.Contains("fog_grid(_fog_sources()")","description":"Add fog and objective timers to client minimap"}

