{"command":"New-Item -ItemType Directory -Force -Path devn | Out-Null
@'
extends Control
const MD = preload("res://scripts/ui/MinimapDraw.gd")
func _ready() -> void:
	var src: Array = [{"p": Vector3(-58.0, 0.0, 58.0), "r": 24.0}, {"p": Vector3(0.0, 0.0, 0.0), "r": 14.0}]
	var g: Array = MD.fog_grid(src, 120.0)
	var vis := 0
	for row in g:
		for c in row:
			if bool(c): vis += 1
	print("N grid=", g.size(), " vis=", vis)
	for p in ["res://scripts/ui/Minimap.gd", "res://scripts/net/NetMiniMap.gd", "res://scripts/net/NetSession.gd", "res://scripts/net/NetClientBattle.gd"]:
		var s = load(p)
		print("N ", p.get_file(), "=", s != null and s is GDScript)
	print("N done")
	get_tree().quit()
'@ | Set-Content -Encoding UTF8 devn\check.gd
@'
[gd_scene load_steps=2 format=3]

[ext_resource type="Script" path="res://devn/check.gd" id="1"]

[node name="Check" type="Control"]
script = ExtResource("1")
'@ | Set-Content -Encoding UTF8 devn\check.tscn
New-Item -ItemType Directory -Force -Path .cache | Out-Null
Copy-Item -LiteralPath 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' -Destination '.cache\godot47.exe' -Force
$g = (Resolve-Path '.cache\godot47.exe')
$a = Start-Process -FilePath $g -ArgumentList '--headless','--path','.','res://devn/check.tscn','--quit-after','400' -NoNewWindow -PassThru -RedirectStandardOutput 'devn\c.out' -RedirectStandardError 'devn\c.err'
$d = $a.WaitForExit(240000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devn\c.out, devn\c.err -ErrorAction SilentlyContinue | Select-String -Pattern '^N |SCRIPT ERROR|Parse Error' -Context 0,1 | Select-Object -First 10 | ForEach-Object { $_.Line.Trim(); if($_.Context.PostContext){ $_.Context.PostContext | ForEach-Object { "   " + $_.Trim() } } }","description":"Probe fog grid and scripts","timeoutMs":300000}

