if (-not $t.Contains("var ui_block: bool")) {
  $t = $t.Replace("`t# 移动控制`n`t# 远程接管直驱：net_axis/net_joy 非零时视为键盘/摇杆本地输入（见 _net_move_mode）`n`tvar net_driven := net_joy != Vector2.ZERO or net_axis != Vector3.ZERO", "`t# 移动控制`n`t# 全屏面板（商店/英雄面板）打开时：不响应键盘/摇杆`n`tvar ui_block: bool = (not is_ai) and UiManager.blocks_gameplay_input()`n`t# 远程接管直驱：net_axis/net_joy 非零时视为键盘/摇杆本地输入（见 _net_move_mode）`n`tvar net_driven := net_joy != Vector2.ZERO or net_axis != Vector3.ZERO")
