{"command":"$p = (Resolve-Path 'scripts\ui\MinimapDraw.gd'); $t = [System.IO.File]::ReadAllText($p)
$inner = @"
	"inner":
		# 内塔：八边形塔基（与方外塔、菱形高地塔、六边水晶形成四种不同轮廓）
		if alive:
			ci.draw_circle(pos, h + 3.2, Color(col.r, col.g, col.b, 0.13))
			ci.draw_circle(pos, h + 1.0, Color(col.r, col.g, col.b, 0.22))
		var pts := PackedVector2Array()
		for i in range(8):
			var a: float = -PI / 2.0 + TAU * float(i) / 8.0 + PI / 8.0
			pts.append(pos + Vector2(cos(a), sin(a)) * h)
		ci.draw_colored_polygon(pts, dark)
		if alive and ratio > 0.0:
			var fh: float = h * 2.0 * clampf(ratio, 0.0, 1.0)
			ci.draw_rect(Rect2(pos.x - h * 0.70, pos.y + h - fh, h * 1.40, fh), col)
		if alive:
			var core := PackedVector2Array()
			for i in range(8):
				var a2: float = -PI / 2.0 + TAU * float(i) / 8.0 + PI / 8.0
				core.append(pos + Vector2(cos(a2), sin(a2)) * h * 0.44)
			ci.draw_colored_polygon(core, lit.darkened(0.08))
			ci.draw_polyline(pts + PackedVector2Array([pts[0]]), Color(1, 1, 1, 0.50), 1.2)
		else:
			_dead_x(ci, pos, h + 1.0)
		ci.draw_polyline(pts + PackedVector2Array([pts[0]]), Color.BLACK, 1.4)
		return
"@
$inner = $inner.Replace("`r`n", "`n")
$t = [regex]::Replace($t, '(?m)^\t"high":', [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $inner + "`t`"high`":" })
[System.IO.File]::WriteAllText($p, $t)
"inner_added=" + $t.Contains('内塔：八边形塔基')","description":"Add octagon shape for inner turret"}

