	# —— 外塔：方形塔身 + 城垛 + 白描边 ——
	ci.draw_rect(Rect2(pos - Vector2(h + 1.4, h + 1.4), Vector2(size + 2.8, size + 2.8)), Color(0.055, 0.065, 0.085, 0.95))
