Now write `scripts/entities/DecorMesh.gd`. Key API:

```gdscript
extends RefCounted
const ROCK := preload("res://scripts/entities/DecorMesh.gd")  # no, self
```
No preload needed.

Functions:
- `static func rock_material() -> ShaderMaterial`
- `static func leaf_material() -> ShaderMaterial`
- `static func wall_visual(seed_val: int = 0) -> Node3D`
- `static func bush_visual(seed_val: int = 0) -> Node3D`
- `static func grass_mesh() -> Mesh` (tuft for MultiMesh)
- internal `_build_wall_mesh(rng)`, `_build_bush_mesh(rng)`, `_add(mesh, xf)` via SurfaceTool.append_from.

SurfaceTool `append_from(mesh, surface, transform)` requires mesh with surfaces; SphereMesh has 1 surface ✓.

Mesh sizes:
wall: total height ~3.0 (matches collision 3). boulders:
- base: 3 rocks radius ~0.55 squashed y 0.5 at y 0.35 (offset around)
- mid: 2 rocks r 0.45 at y 1.0
- upper: 2 rocks r 0.38 at y 1.6
- cap: 1 rock r 0.34 at y 2.15 + one small at 2.5
- moss disc cylinder r 0.95
Hmm collision is 0.4×3×0.4 → visual width ~1.1 > collision but walls in game are decorative blockers; slightly bigger visual than collider is acceptable/fine (the old GLB at scale 1.3 was probably ~1 unit wide too).

bush: blobs radius 0.35-0.7, spread within radius 0.75, heights up to 1.5; plus blades around perimeter up to y 1.7; plus base disc radius 1.0. Collision box 2×2×2 ✓ visual ~2.4 wide.

Careful with MultiMesh grass tuft: mesh origin at ground, height ~1.1 normalized later (scale computed by target_height / aabb height) ✓.

Additionally, for MultiMesh + custom ShaderMaterial: MultiMeshInstance3D uses material_override ✓ set on mmi. Add `material_override` param to `_make_cluster`? I'll add optional `mat: Material` param.

Shaders: keep code compact but correct.

Rock shader code:

```
shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx;
uniform vec4 rock_a : source_color = vec4(0.46, 0.43, 0.38, 1.0);
uniform vec4 rock_b : source_color = vec4(0.22, 0.21, 0.19, 1.0);
uniform vec4 moss_col : source_color = vec4(0.20, 0.34, 0.13, 1.0);
uniform vec4 dirt_col : source_color = vec4(0.15, 0.13, 0.10, 1.0);
uniform float moss_band = 1.35;

varying vec3 wp;
varying vec3 wn;

float hash13(vec3 p) {
	p = fract(p * 0.3183099 + vec3(0.71, 0.113, 0.419));
	p *= 17.0;
	return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

float vnoise(vec3 x) {
	vec3 i = floor(x);
	vec3 f = fract(x);
	f = f * f * (3.0 - 2.0 * f);
	float a = mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x);
	float b = mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x);
	float c = mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x);
	float d = mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x);
	return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}

void vertex() {
	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	wn = normalize((MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz);
}

void fragment() {
	float n = vnoise(wp * 2.6);
	float n2 = vnoise(wp * 11.0);
	float grains = vnoise(wp * 34.0);
	vec3 base = mix(rock_b.rgb, rock_a.rgb, smoothstep(0.28, 0.78, n * 0.75 + n2 * 0.35));
	base *= 0.82 + 0.36 * grains;
	float up = clamp(wn.y, 0.0, 1.0);
	float moss = smoothstep(moss_band, 0.35, wp.y) * smoothstep(0.15, 0.75, up);
	float moss_n = smoothstep(0.35, 0.75, vnoise(wp * 5.0 + vec3(7.0)));
	moss *= 0.55 + 0.75 * moss_n;
	base = mix(base, moss_col.rgb * (0.75 + 0.6 * n2), clamp(moss, 0.0, 1.0));
	float dirt = smoothstep(0.45, 0.05, wp.y);
	base = mix(base, dirt_col.rgb, dirt * 0.55);
	ALBEDO = base;
	ROUGHNESS = 0.95 - 0.12 * moss;
	SPECULAR = 0.14;
}
```

Leaf shader:
```
shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx, cull_back;

uniform vec4 leaf_dark : source_color = vec4(0.06, 0.17, 0.07, 1.0);
uniform vec4 leaf_mid : source_color = vec4(0.16, 0.34, 0.12, 1.0);
uniform vec4 leaf_lit : source_color = vec4(0.38, 0.58, 0.20, 1.0);
uniform float sway = 0.14;
uniform float sway_speed = 1.15;

varying vec3 wp;
varying float vh;

float hash13(vec3 p) { ... }

float vnoise(vec3 x) { ... }

void vertex() {
	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	vh = clamp(VERTEX.y, 0.0, 3.0);
	vec3 o = (MODEL_MATRIX * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
	float ph = o.x * 0.42 + o.z * 0.33;
	float t = TIME * sway_speed;
	float gust = sin(t + ph) * 0.65 + sin(t * 1.63 + ph * 1.7) * 0.35;
	float w = sway * vh * vh * 0.25;
	VERTEX.x += gust * w;
	VERTEX.z += gust * w * 0.55;
}

void fragment() {
	float n = vnoise(wp * 4.5);
	float n2 = vnoise(wp * 13.0 + vec3(4.0));
	vec3 base = mix(leaf_dark.rgb, leaf_mid.rgb, smoothstep(0.25, 0.7, n));
	base = mix(base, leaf_lit.rgb, smoothstep(0.45, 0.95, n2) * 0.75);
	base = mix(base, leaf_lit.rgb, clamp(vh * 0.28, 0.0, 1.0) * 0.55);
	ALBEDO = base;
	ROUGHNESS = 0.72;
	SPECULAR = 0.18;
	BACKLIGHT = base * 0.55;
}
```

Now geometry builders.

```gdscript
static func _sphere_mesh(radial: int, rings: int) -> SphereMesh:
	var sm := SphereMesh.new()
	sm.radial_segments = radial
	sm.rings = rings
	sm.radius = 1.0
	sm.height = 2.0
	return sm

static func _append_rock(st: SurfaceTool, base_mesh: Mesh, pos: Vector3, scale_v: Vector3, rot: Vector3) -> void:
	var b := Basis.from_euler(rot).scaled(scale_v)
	st.append_from(base_mesh, 0, Transform3D(b, pos))
```

Wall builder:
```gdscript
static func wall_visual(seed_val: int = 0) -> Node3D:
	var rng := RandomNumberGenerator.new()
	rng.seed = seed_val * 7919 + 13
	var root := Node3D.new()
	root.name = "WallVisual"
	var mesh := _build_wall_mesh(rng)
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.material_override = rock_material()
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	root.add_child(mi)
	return root
```

_build_wall_mesh:
```gdscript
static func _build_wall_mesh(rng: RandomNumberGenerator) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var rock := _sphere_mesh(8, 5)
	var layers := [
		[0.30, Vector2(0.62, 0.46)],   # [y, (水平半径, 高度比例)]
		[0.92, Vector2(0.55, 0.40)],
		[1.52, Vector2(0.47, 0.34)],
		[2.08, Vector2(0.40, 0.28)],
		[2.58, Vector2(0.30, 0.22)],
	]
	for l in layers:
		var y: float = float(l[0])
		var rp: Vector2 = l[1]
		var n: int = 2 if rp.x > 0.5 else 1
		for i in range(n):
			var ang: float = rng.randf_range(0.0, TAU) + float(i) * PI
			var off: float = 0.085 * rp.x / 0.6
			var p := Vector3(cos(ang) * off, y, sin(ang) * off)
			var sx: float = rp.x * rng.randf_range(0.85, 1.15)
			var sy: float = rp.y * rng.randf_range(0.9, 1.2)
			var sz: float = rp.x * rng.randf_range(0.8, 1.05)
			_append_rock(st, rock, p, Vector3(sx, sy, sz),
				Vector3(rng.randf_range(-0.25, 0.25), rng.randf_range(0.0, TAU), rng.randf_range(-0.25, 0.25)))
	# 基底碎石
	for i in range(5):
		var a: float = rng.randf_range(0.0, TAU)
