Rock shader code:

```
shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx;
uniform vec4 rock_a : source_color = vec4(0.46, 0.43, 0.38, 1.0);
uniform vec4 rock_b : source_color = vec4(0.22, 0.21, 0.19, 1.0);
uniform vec4 moss_col : source_color = vec4(0.20, 0.34, 0.13, 1.0);
uniform vec4 dirt_col : source_color = vec4(0.15, 0.13, 0.10, 1.0);
uniform float moss_band = 1.35;

varying vec3 wp;
varying vec3 wn;

float hash13(vec3 p) {
	p = fract(p * 0.3183099 + vec3(0.71, 0.113, 0.419));
	p *= 17.0;
	return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

float vnoise(vec3 x) {
	vec3 i = floor(x);
	vec3 f = fract(x);
	f = f * f * (3.0 - 2.0 * f);
	float a = mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x);
	float b = mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x);
	float c = mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x);
	float d = mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x);
	return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}

void vertex() {
	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	wn = normalize((MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz);
}

void fragment() {
	float n = vnoise(wp * 2.6);
	float n2 = vnoise(wp * 11.0);
	float grains = vnoise(wp * 34.0);
	vec3 base = mix(rock_b.rgb, rock_a.rgb, smoothstep(0.28, 0.78, n * 0.75 + n2 * 0.35));
	base *= 0.82 + 0.36 * grains;
	float up = clamp(wn.y, 0.0, 1.0);
	float moss = smoothstep(moss_band, 0.35, wp.y) * smoothstep(0.15, 0.75, up);
	float moss_n = smoothstep(0.35, 0.75, vnoise(wp * 5.0 + vec3(7.0)));
	moss *= 0.55 + 0.75 * moss_n;
	base = mix(base, moss_col.rgb * (0.75 + 0.6 * n2), clamp(moss, 0.0, 1.0));
	float dirt = smoothstep(0.45, 0.05, wp.y);
	base = mix(base, dirt_col.rgb, dirt * 0.55);
	ALBEDO = base;
	ROUGHNESS = 0.95 - 0.12 * moss;
	SPECULAR = 0.14;
}
```

