render_mode diffuse_burley, specular_schlick_ggx, cull_back;

uniform vec4 leaf_dark : source_color = vec4(0.06, 0.17, 0.07, 1.0);
uniform vec4 leaf_mid : source_color = vec4(0.16, 0.34, 0.12, 1.0);
uniform vec4 leaf_lit : source_color = vec4(0.38, 0.58, 0.20, 1.0);
