{"command":"$p = (Resolve-Path 'scripts\net\NetModels.gd'); $t = [System.IO.File]::ReadAllText($p)
$nl = "`n"
$t = $t.Replace("const WALL_GLB := `"res://model/wall/wall.glb`"", "const DecorMesh = preload(`"res://scripts/entities/DecorMesh.gd`")
const WALL_GLB := `"res://model/wall/wall.glb`"")
$oldWall = "static func wall() -> Node3D:" + $nl + "`t# 与 Wall.gd 一致：y 1.3 拉伸 + 绕 y 转 90°（墙体长轴落到容器前向）" + $nl + "`tvar inst = _spawn(WALL_GLB, Vector3(1.0, 1.3, 1.0))" + $nl + "`tif inst != null:" + $nl + "`t`tinst.rotation.y = deg_to_rad(90.0)" + $nl + "`treturn inst"
$newWall = "static func wall() -> Node3D:" + $nl + "`t# 与主机 Wall.gd 完全同源：程序化石墙（不再加载 wall.glb）" + $nl + "`treturn DecorMesh.wall_visual(randi() % 4096)"
if ($t.Contains($oldWall)) { $t = $t.Replace($oldWall, $newWall); 'wall fn ok' } else { 'wall fn MISS' }
$oldBush = "static func bush() -> Node3D:" + $nl + "`treturn _spawn(BUSH_GLB, Vector3.ONE * 6.0)"
$newBush = "static func bush() -> Node3D:" + $nl + "`t# 与主机 Bush.gd 完全同源：程序化灌木（不再加载 grass-large.glb）" + $nl + "`treturn DecorMesh.bush_visual(randi() % 4096)"
if ($t.Contains($oldBush)) { $t = $t.Replace($oldBush, $newBush); 'bush fn ok' } else { 'bush fn MISS' }
[System.IO.File]::WriteAllText($p, $t)
Select-String -Path scripts\net\NetModels.gd -Pattern 'DecorMesh|func wall|func bush' | ForEach-Object { "N L$($_.LineNumber): $($_.Line.Trim())" }","description":"Point client models at procedural decor"}

