Now the fountain. Rewrite `_add_fountain` in BattleManager + add shader material helpers. Need `const DecorMesh` preload in BattleManager.

Plan: replace lines from `# 泉水视觉：圆盘+边界光环（半径3，半透明）` + `func _add_fountain(...)` until before `func _create_player_hero`. Use index-based replacement between anchors.

New code:

```gdscript
# 泉水视觉：石砌池沿 + 波纹水面 + 中央喷泉柱 + 溅水粒子 + 旋转符文环 + 顶光
func _add_fountain(center: Vector3, color: Color) -> void:
	var root := Node3D.new()
	root.name = "Fountain"
	root.position = Vector3(center.x, 0.0, center.z)
	add_child(root)
	var stone := DecorMesh.rock_material()
	# 石质池底（外圈略大，形成厚重基座）
	var basin := MeshInstance3D.new()
	var bcyl := CylinderMesh.new()
	bcyl.top_radius = 4.95
	bcyl.bottom_radius = 5.25
	bcyl.height = 0.55
	bcyl.radial_segments = 40
	basin.mesh = bcyl
	basin.position = Vector3(0, 0.25, 0)
	basin.material_override = stone
	root.add_child(basin)
	# 池沿（石环）
	var rim := MeshInstance3D.new()
	var torus := TorusMesh.new()
	torus.inner_radius = 4.30
	torus.outer_radius = 5.05
	torus.rings = 48
	torus.ring_segments = 10
	rim.mesh = torus
	rim.position = Vector3(0, 0.55, 0)
	rim.material_override = stone
	root.add_child(rim)
	# 水面（波纹 shader）
	var water := MeshInstance3D.new()
	var wcyl := CylinderMesh.new()
	wcyl.top_radius = 4.42
	wcyl.bottom_radius = 4.42
	wcyl.height = 0.06
	wcyl.radial_segments = 48
	water.mesh = wcyl
	water.position = Vector3(0, 0.53, 0)
	water.material_override = _fountain_water_material(color)
	root.add_child(water)
	# 中央石座
	var ped := MeshInstance3D.new()
	var pcyl := CylinderMesh.new()
	pcyl.top_radius = 0.52
	pcyl.bottom_radius = 0.86
	pcyl.height = 1.15
	pcyl.radial_segments = 16
	ped.mesh = pcyl
	ped.position = Vector3(0, 1.1, 0)
	ped.material_override = stone
	root.add_child(ped)
	# 水柱
	var jet := MeshInstance3D.new()
	var jcyl := CylinderMesh.new()
	jcyl.top_radius = 0.26
	jcyl.bottom_radius = 0.40
	jcyl.height = 2.5
	jcyl.radial_segments = 14
	jet.mesh = jcyl
	jet.position = Vector3(0, 2.9, 0)
	jet.material_override = _fountain_jet_material(color)
	root.add_child(jet)
	# 溅水粒子
	var splash := CPUParticles3D.new()
	splash.amount = 48
	splash.lifetime = 1.15
	var drop := SphereMesh.new()
	drop.radius = 0.075
	drop.height = 0.15
	drop.radial_segments = 6
	drop.rings = 3
	splash.mesh = drop
	splash.emission_shape = CPUParticles3D.EMISSION_SHAPE_SPHERE
	splash.emission_sphere_radius = 0.5
	splash.position = Vector3(0, 4.0, 0)
	splash.direction = Vector3.UP
	splash.spread = 42.0
	splash.initial_velocity_min = 0.6
	splash.initial_velocity_max = 1.9
	splash.gravity = Vector3(0, -5.2, 0)
	splash.scale_amount_min = 0.7
	splash.scale_amount_max = 1.6
	splash.color = Color(color.r * 0.6 + 0.5, color.g * 0.6 + 0.5, 1.0, 0.75)
	var splash_mat := StandardMaterial3D.new()
	splash_mat.albedo_color = Color(0.80, 0.92, 1.0, 1.0)
	splash_mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	splash_mat.vertex_color_use_as_albedo = true
	splash_mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	splash.material_override = splash_mat
	root.add_child(splash)
	# 旋转符文环
	var rune := Node3D.new()
	rune.name = "RuneRing"
	root.add_child(rune)
	var rune_mesh := BoxMesh.new()
	rune_mesh.size = Vector3(0.16, 0.04, 0.46)
	var rune_mat := StandardMaterial3D.new()
	rune_mat.albedo_color = color
	rune_mat.emission_enabled = true
	rune_mat.emission = Color(color.r, color.g, color.b)
	rune_mat.emission_energy_multiplier = 2.4
	rune_mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	rune_mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	for i in range(12):
		var a: float = TAU * float(i) / 12.0
		var rmi := MeshInstance3D.new()
		rmi.mesh = rune_mesh
		rmi.material_override = rune_mat
		rmi.position = Vector3(cos(a) * 5.55, 0.10, sin(a) * 5.55)
		rmi.rotation.y = -a
		rune.add_child(rmi)
	# 地面光晕（队伍色，半透明）
	var glow := MeshInstance3D.new()
	var gcyl := CylinderMesh.new()
	gcyl.top_radius = 5.3
	gcyl.bottom_radius = 5.3
	gcyl.height = 0.02
	gcyl.radial_segments = 40
	glow.mesh = gcyl
	glow.position = Vector3(0, 0.06, 0)
	glow.material_override = _fountain_glow_material(color)
	root.add_child(glow)
	# 顶光
	var lt := OmniLight3D.new()
	lt.light_color = color
	lt.light_energy = 2.2
	lt.omni_range = 14.0
	lt.position = Vector3(0, 3.2, 0)
	root.add_child(lt)
	# 符文环缓慢旋转（纯视觉）
	var tw := create_tween().set_loops()
	tw.tween_property(rune, "rotation:y", TAU, 16.0).from(0.0)

func _fountain_water_material(color: Color) -> ShaderMaterial:
	var sh := Shader.new()
	sh.code = """
shader_type spatial;
render_mode blend_mix, depth_draw_never, cull_back, diffuse_burley;

uniform sampler2D noise_tex : filter_linear, repeat_enable;
uniform vec4 tint : source_color = vec4(0.25, 0.55, 1.0, 1.0);
uniform vec4 glow : source_color = vec4(0.4, 0.8, 1.0, 1.0);

void fragment() {
	vec2 uv = UV * 2.0 - 1.0;
	float r = length(uv);
	float t = TIME;
	float w = sin(r * 26.0 - t * 3.0) * 0.5 + 0.5;
	float w2 = sin(r * 10.0 + t * 1.5) * 0.5 + 0.5;
	float rings = smoothstep(0.45, 0.95, w * 0.55 + w2 * 0.55);
	vec3 base = tint.rgb * (0.70 + 0.40 * rings);
	ALBEDO = base;
	EMISSION = glow.rgb * (0.18 + 0.95 * rings * (1.0 - r * 0.55));
	ALPHA = clamp(0.55 + 0.42 * rings * (1.0 - r), 0.0, 1.0);
	ROUGHNESS = 0.10;
	SPECULAR = 0.85;
	METALLIC = 0.0;
}
"""
	var mat := ShaderMaterial.new()
	mat.shader = sh
	mat.set_shader_parameter("tint", color)
	mat.set_shader_parameter("glow", Color(color.r * 0.5 + 0.5, color.g * 0.5 + 0.6, 1.0))
	return mat
```
