		print("W bushes=", bushes.size())
		if bushes.size() > 0:
			var b = bushes[0]
			print("W bush_children=", b.get_child_count())
			var mi: MeshInstance3D = b.get_child(0) as MeshInstance3D
			if mi and mi.mesh:
				print("W bush_surfaces=", mi.mesh.get_surface_count(), " aabb=", mi.mesh.get_aabb())
