Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

const DM = preload("res://scripts/entities/DecorMesh.gd")

var t := 0
var bm: BattleManager = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 300:
		var gm: ArrayMesh = DM.grass_mesh()
		var wm: ArrayMesh = DM.wall_mesh()
		print("W grass_surfaces=", gm.get_surface_count(), " aabb=", gm.get_aabb().size)
		print("W wall_surfaces=", wm.get_surface_count(), " aabb=", wm.get_aabb().size)
		var f := bm.get_node_or_null("Fountain") if bm != null else null
		print("W fountain=", f != null, " children=", f.get_child_count() if f != null else -1)
		var bushes := get_tree().get_nodes_in_group("bush")
		print("W bushes=", bushes.size())
		if bushes.size() > 0:
			var b: Node3D = bushes[0]
			print("W bush_children=", b.get_child_count())
			var mi := b.get_child(0) as MeshInstance3D
			if mi != null and mi.mesh != null:
				print("W bush_aabb=", mi.mesh.get_aabb().size, " mat=", mi.material_override != null)
		var walls := get_tree().get_nodes_in_group("walls")
		print("W walls=", walls.size())
		if walls.size() > 0:
			var w: Node3D = walls[0]
			var wmi := w.get_child(0) as MeshInstance3D
			if wmi != null and wmi.mesh != null:
				print("W wall_aabb=", wmi.mesh.get_aabb().size, " mat=", wmi.material_override != null)
	elif t == 340:
		get_tree().quit()
