content.arguments:
{"command":"New-Item -ItemType Directory -Force -Path .cache, devfx4 | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

var t := 0
var bm: BattleManager = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _nearest_wall_dist(p: Vector3, walls: Array) -> float:
	var best := 999.0
	for w in walls:
		var n3: Node3D = w
		var d: float = Vector2(n3.position.x - p.x, n3.position.z - p.z).length()
		if d < best:
			best = d
	return best

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		var walls: Array = get_tree().get_nodes_in_group("walls")
		print("X walls_total=", walls.size())
		# 外周覆盖：|t|>37 的四条边（跳过两个基地角）
		var worst := 0.0
		var worst_p := Vector3.ZERO
		for t2 in range(-62, 63, 2):
			if absf(float(t2)) <= 37.0:
				continue
			for p in [Vector3(-63, 0, float(t2)), Vector3(63, 0, float(t2)), Vector3(float(t2), 0, -63), Vector3(float(t2), 0, 63)]:
				var d := _nearest_wall_dist(p, walls)
				if d > worst:
					worst = d
					worst_p = p
		print("X outer_max_gap=", "%.2f" % worst, " at ", worst_p)
		# 龙坑围墙角度分布
		for pit in [Vector3(24, 0, 26), Vector3(-24, 0, -26)]:
			var angs: Array = []
			for w in walls:
				var n3: Node3D = w
				var dv := Vector3(n3.position.x - pit.x, 0, n3.position.z - pit.z)
				if dv.length() > 4.0 and dv.length() < 10.0:
					angs.append(rad_to_deg(atan2(dv.z, dv.x)))
			print("X pit=", pit, " walls=", angs.size())
		# 出生点净空
		print("X spawn_clear_blue=", "%.2f" % _nearest_wall_dist(Vector3(-58, 0, 58), walls), " red=", "%.2f" % _nearest_wall_dist(Vector3(58, 0, -58), walls))
		var w0: Node3D = walls[0]
		var mi := w0.get_child(0) as MeshInstance3D
		print("X wall_mesh=", mi.mesh != null, " tri=", mi.mesh.get_faces().size() / 3 if mi.mesh != null else -1)
	elif t == 360:
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx4\probe.gd
@'
[gd_scene load_steps=2 format=3]

[ext_resource type="Script" path="res://devfx4/probe.gd" id="1"]

[node name="P" type="Node"]
script = ExtResource("1")
'@ | Set-Content -Encoding UTF8 devfx4\probe.tscn
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx4/probe.tscn','--audio-driver','Dummy','--position','2000,2000','--quit-after','900' -PassThru -RedirectStandardOutput 'devfx4\p.out' -RedirectStandardError 'devfx4\p.err'
$d = $a.WaitForExit(300000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx4\p.out -ErrorAction SilentlyContinue | Select-String -Pattern '^X ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
