content.arguments:
{"command":"@'
# 地图外周城墙：沿 |x|=63 / |z|=63 整圈围合（已有分路外墙的中段不重复放），
# 野区两个外角圆弧倒角；泉水半径内让开，避免城墙插进喷泉池
func _generate_outer_walls() -> void:
	var edge: float = 63.0
	var step: float = 2.0
	var t: float = -edge
	while t <= edge:
		# 分路外墙已覆盖 |t| ≤ 37 的中段，这里只补缺
		if absf(t) > 37.0:
			_add_outer_wall(Vector3(-edge, 0.0, t), Vector3(1, 0, 0))
			_add_outer_wall(Vector3(edge, 0.0, t), Vector3(-1, 0, 0))
			_add_outer_wall(Vector3(t, 0.0, -edge), Vector3(0, 0, 1))
			_add_outer_wall(Vector3(t, 0.0, edge), Vector3(0, 0, -1))
		t += step
	# 野区两个外角 ((-63,-63) / (63,63)) 圆弧倒角：半径 8.5，与两条边线相切
	for corner in [Vector2(-1, -1), Vector2(1, 1)]:
		var cx: float = float(corner.x) * (edge - 8.5)
		var cz: float = float(corner.y) * (edge - 8.5)
		var base_ang: float = 180.0 if corner.x < 0.0 else 0.0
		for i in range(10):
			var a: float = deg_to_rad(base_ang + 10.0 * float(i))
			_add_outer_wall(Vector3(cx + cos(a) * 8.5, 0.0, cz + sin(a) * 8.5), Vector3(cos(a), 0.0, sin(a)))

## 外周城墙落点：避开泉水（半径 5.25 的池子 + 边缘），其余按 force 放置
func _add_outer_wall(pos: Vector3, facing: Vector3) -> void:
	var blue := Vector2(-58.0, 58.0)
	var red := Vector2(58.0, -58.0)
	var p := Vector2(pos.x, pos.z)
	if p.distance_to(blue) < 7.0 or p.distance_to(red) < 7.0:
		return
	_add_wall(pos, facing, true)

'@ | Set-Content -Encoding UTF8 devtmp_outer2.gd
$newLines = [System.IO.File]::ReadAllLines((Resolve-Path 'devtmp_outer2.gd'))
$p = (Resolve-Path 'scripts\core\BattleManager.gd')
$lines = [System.IO.File]::ReadAllLines($p)
$start = -1; $end = -1
for ($i = 0; $i -lt $lines.Count; $i++) {
	if ($start -lt 0 -and $lines[$i].Trim().StartsWith("func _generate_outer_walls")) { $start = $i }
	if ($start -ge 0 -and $i -gt $start -and $lines[$i].Trim().StartsWith("func _generate_high_ground_walls")) { $end = $i; break }
}
"start=$start end=$end"
$out = New-Object System.Collections.Generic.List[string]
for ($i = 0; $i -lt $start; $i++) { $out.Add($lines[$i]) }
foreach ($l in $newLines) { $out.Add($l) }
for ($i = $end; $i -lt $lines.Count; $i++) { $out.Add($lines[$i]) }
[System.IO.File]::WriteAllLines($p, $out)
Remove-Item devtmp_outer2.gd -Force
"total=" + $out.Count
Select-String -Path scripts\core\BattleManager.gd -Pattern 'func _generate_outer_walls|func _add_outer_wall|func _generate_high_ground_walls' | ForEach-Object { "B L$($_.LineNumber): $($_.Line.Trim())" }","description":"Rewrite outer walls with fountain clearance"}

