extends Node

var t := 0
var bm: BattleManager = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		var walls: Array = get_tree().get_nodes_in_group("walls")
		print("Z walls=", walls.size())
		var crystal := Vector3(-53, 0, 53)
		var f := bm.get_node_or_null("Fountain") as Node3D
		var fc := Vector3(-62, 0, 62)
		if f != null:
			fc = f.position
			print("Z fountain_pos=", fc, " children=", f.get_child_count())
		print("Z fountain_to_crystal=", "%.2f" % fc.distance_to(crystal), " (crystal_range 8.90)")
		var ring_n := 0
		var ring_min := 999.0
		for w in walls:
			var n3: Node3D = w
			var d: float = Vector2(n3.position.x - fc.x, n3.position.z - fc.z).length()
			if d > 3.0 and d < 6.0:
				ring_n += 1
			if d < ring_min:
				ring_min = d
		print("Z fountain_ring_walls=", ring_n, " nearest_wall_dist=", "%.2f" % ring_min)
		# 外周覆盖：四条边全部（|t|>37 段 + 基地角）
		var worst := 0.0
		var worst_p := Vector3.ZERO
		for tv in range(-62, 63, 2):
			if absf(float(tv)) <= 37.0:
				continue
			for p in [Vector3(-63, 0, float(tv)), Vector3(63, 0, float(tv)), Vector3(float(tv), 0, -63), Vector3(float(tv), 0, 63)]:
				var best := 999.0
				for w in walls:
					var n3: Node3D = w
					var d: float = Vector2(n3.position.x - p.x, n3.position.z - p.z).length()
					if d < best:
						best = d
				if best > worst:
					worst = best
					worst_p = p
		print("Z perimeter_max_gap=", "%.2f" % worst, " at ", worst_p)
		if bm.hero != null:
			var hp: Vector3 = bm.hero.global_position
			print("Z hero_spawn=", hp, " to_spring=", "%.2f" % hp.distance_to(fc), " spring_r=3.60")
		var lane_y := -1.0
		if bm.lane_plane_nodes.size() > 0:
			var arr: Array = bm.lane_plane_nodes.values()[0]
			lane_y = (arr[0] as Node3D).position.y
		print("Z lane_plane_y=", lane_y, " river_max_y=", "%.3f" % (0.02 + 0.04))
	elif t == 360:
		get_tree().quit()
