```gdscript
static var _hq_variants: Array = []

## 高地外周墙：更高规格的石墙（基座+8层错缝方石+檐口压顶+壁柱），面数约为普通墙 2 倍
static func wall_visual_hq(seed_val: int = 0) -> Node3D:
	var root := Node3D.new()
	root.name = "WallVisualHQ"
	var slot: int = absi(seed_val) % 4
	while _hq_variants.size() <= slot:
		var rng := RandomNumberGenerator.new()
		rng.seed = 31337 + _hq_variants.size() * 2654435761
		_hq_variants.append(_build_wall_mesh_hq(rng))
	var mi := MeshInstance3D.new()
	mi.mesh = _hq_variants[slot]
	mi.material_override = rock_material()
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	root.add_child(mi)
	return root

static func _build_wall_mesh_hq(rng: RandomNumberGenerator) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var box := BoxMesh.new()
	box.size = Vector3.ONE
	# 基座两皮（更宽）
	_append(st, box, Vector3(0, 0.16, 0), Vector3(1.42, 0.32, 1.05), Vector3(0, rng.randf_range(-0.06, 0.06), 0))
	_append(st, box, Vector3(0, 0.46, 0), Vector3(1.28, 0.28, 0.95), Vector3(0, rng.randf_range(-0.05, 0.05), 0))
	# 8 层错缝方石（每层 2~3 块，横向错开）
	var y := 0.62
	for course in range(8):
		var n: int = 3 if course % 2 == 0 else 2
		var h: float = 0.26
		for i in range(n):
			var w: float = 1.10 / float(n) * rng.randf_range(0.92, 1.04)
			var xoff: float = (float(i) - float(n - 1) * 0.5) * (1.10 / float(n))
			_append(st, box, Vector3(xoff + rng.randf_range(-0.02, 0.02), y + h * 0.5, rng.randf_range(-0.02, 0.02)),
				Vector3(w, h * rng.randf_range(0.94, 1.03), 0.86 + rng.randf_range(-0.05, 0.05)),
				Vector3(0, rng.randf_range(-0.03, 0.03), 0))
		y += h
	# 檐口压顶（略外挑）
	_append(st, box, Vector3(0, y + 0.10, 0), Vector3(1.34, 0.20, 1.02), Vector3.ZERO)
	_append(st, box, Vector3(0, y + 0.26, 0), Vector3(1.16, 0.12, 0.90), Vector3.ZERO)
	# 转角壁柱（前后面各一根）
	for sx in [-1.0, 1.0]:
		_append(st, box, Vector3(sx * 0.52, y * 0.5 + 0.35, 0.0), Vector3(0.22, y * 0.94, 0.98), Vector3(0, 0, 0))
	# 基底碎石 + 苔藓盘
	var rock := _rock_sphere()
	for i in range(4):
		var a: float = rng.randf_range(0.0, TAU)
		var d: float = rng.randf_range(0.46, 0.74)
		var rr: float = rng.randf_range(0.09, 0.16)
		_append(st, rock, Vector3(cos(a) * d, rr * 0.5, sin(a) * d), Vector3(rr, rr * 0.7, rr),
			Vector3(rng.randf_range(0.0, TAU), rng.randf_range(0.0, TAU), 0.0))
	st.append_from(_disc(0.92, 0.06, 12), 0, Transform3D(Basis(), Vector3(0.0, 0.03, 0.0)))
	return st.commit()
