{"command":"$p = (Resolve-Path 'scripts\net\NetClientBattle.gd'); $t = [System.IO.File]::ReadAllText($p)
$new = "`t`t# 与主机同源：高地外周（距基地 33~37.5m）用高规格墙体`n`t`tvar hq: bool = false`n`t`tfor bc in [Vector2(-60, 60), Vector2(60, -60)]:`n`t`t`tvar dd: float = Vector2(root.position.x - bc.x, root.position.z - bc.y).length()`n`t`t`tif dd > 33.0 and dd < 37.5:`n`t`t`t`thq = true`n`t`tvar wall_model := NetModels.wall(hq)`n"
$t = [regex]::Replace($t, '\t\tvar wall_model := NetModels\.wall\(\)\r?\n', $new)
[System.IO.File]::WriteAllText($p, $t)
"client_hq=" + $t.Contains("NetModels.wall(hq)")
@'
extends Node

const DM = preload("res://scripts/entities/DecorMesh.gd")

var t := 0
var bm: BattleManager = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _mesh_of(n: Node) -> MeshInstance3D:
	if n is MeshInstance3D:
		return n as MeshInstance3D
	for c in n.get_children():
		var m := _mesh_of(c)
		if m != null:
			return m
	return null

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		var walls: Array = get_tree().get_nodes_in_group("walls")
		var hq_n := 0
		for w in walls:
			if w.get("hq") == true:
				hq_n += 1
		print("W walls=", walls.size(), " hq_walls=", hq_n)
		# 塔附近最近墙
		for tr in bm.turrets:
			var n3: Node3D = tr
			if str(tr.tower_type) != "outer" and str(tr.tower_type) != "inner":
				continue
			if absf(absf(n3.position.x) - absf(n3.position.z)) < 8.0:
				continue
			var best := 999.0
			for w in walls:
				var w3: Node3D = w
				var d: float = Vector2(w3.position.x - n3.position.x, w3.position.z - n3.position.z).length()
				if d < best:
					best = d
			print("W tower ", n3.position, " nearest_wall=", "%.2f" % best)
		# 高地墙网格面数
		var hq_vis := DM.wall_visual_hq(5)
		var hq_mesh := _mesh_of(hq_vis)
		print("W hq_tris=", hq_mesh.mesh.get_faces().size() / 3, " aabb_h=", hq_mesh.mesh.get_aabb().size.y)
		hq_vis.queue_free()
