extends SceneTree

func _init() -> void:
	var ps: PackedScene = load("res://model/turret/Turret.glb")
	var n: Node3D = ps.instantiate()
	var box := AABB()
	var first := true
	var meshes: Array = []
	_collect(n, meshes)
	for mi in meshes:
		var mb: AABB = mi.mesh.get_aabb()
		var wb: AABB = mi.global_transform * mb
		box = wb if first else box.merge(wb)
		first = false
	print("GLB aabb size=", box.size, " pos=", box.position, " meshes=", meshes.size())
	var tri := 0
	for mi in meshes:
		tri += mi.mesh.get_faces().size() / 3
	print("GLB tris=", tri)
	n.free()
	quit()

func _collect(n: Node, out: Array) -> void:
	if n is MeshInstance3D and n.mesh != null:
		out.append(n)
	for c in n.get_children():
		_collect(c, out)
