@'
extends Node

const TM = preload("res://scripts/entities/TurretMesh.gd")

var t := 0
var bm: BattleManager = null

func _mesh_of(n: Node) -> MeshInstance3D:
	if n is MeshInstance3D:
		return n as MeshInstance3D
	for c in n.get_children():
		var m := _mesh_of(c)
		if m != null:
			return m
	return null

func _bounds(n: Node) -> Array:
	var box := AABB()
	var first := true
	var tri := 0
	var meshes: Array = []
	_collect(n, meshes)
	for mi in meshes:
		var mb: AABB = mi.mesh.get_aabb()
		var wb: AABB = mi.transform * mb
		box = wb if first else box.merge(wb)
		first = false
		tri += mi.mesh.get_faces().size() / 3
	return [box.size, tri, meshes.size()]

func _collect(n: Node, out: Array) -> void:
	if n is MeshInstance3D and n.mesh != null:
		out.append(n)
	for c in n.get_children():
		_collect(c, out)

func _ready() -> void:
	for tier in ["outer", "inner", "high", "crystal"]:
		for team in [0, 1]:
			var v := TM.visual(tier, team)
			var r := _bounds(v)
			print("V ", tier, " team=", team, " size=", r[0], " tris=", r[1], " meshes=", r[2], " tint_meta=", v.has_meta("_fx_team_tint"))
			v.free()
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 300:
		var n := 0
		for tr in bm.turrets:
			var vis: Node3D = tr.get_node_or_null("TurretVisual")
			n += 1 if vis != null else 0
		print("V turrets_with_visual=", n, "/", bm.turrets.size())
		var cv: Node3D = bm.turrets[9].get_node_or_null("TurretVisual")
		print("V crystal_pivot=", cv.get_node_or_null("CrystalPivot") != null if cv != null else false)
	elif t == 340:
		get_tree().quit()
