```
Simpler: use two-tone based on world y and value noise; reuse DecorMesh's `_NOISE_GLSL`? It's private const in DecorMesh; accessible as `DecorMesh._NOISE_GLSL`? Constants are accessible via class instance? In GDScript, `DecorMesh._NOISE_GLSL` works for const in a script referenced by preload? Yes: `const X = preload(...)` gives script object; static const access works (`DecorMesh._NOISE_GLSL`) — I think accessing a const on a preloaded script resource works via `.get()`? For simplicity, write own small noise inline.

Time is a factor; use a simple shader:

```
shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx;
uniform vec3 body_color : source_color = vec3(0.4,0.33,0.28);
uniform vec3 belly_color : source_color = vec3(0.55,0.48,0.4);
uniform vec3 accent_glow : source_color = vec3(0.0);
uniform float glow_amount = 0.0;
varying vec3 wp; varying vec3 wl;
void vertex(){ wp = (MODEL_MATRIX*vec4(VERTEX,1.0)).xyz; wl = VERTEX; }
float hash31(vec3 p){ p=fract(p*0.3183099+vec3(0.1,0.2,0.3)); p*=17.0; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float vnoise(vec3 x){ vec3 i=floor(x); vec3 f=fract(x); f=f*f*(3.0-2.0*f);
  return mix(mix(mix(hash31(i+vec3(0,0,0)),hash31(i+vec3(1,0,0)),f.x),
                 mix(hash31(i+vec3(0,1,0)),hash31(i+vec3(1,1,0)),f.x),f.y),
             mix(mix(hash31(i+vec3(0,0,1)),hash31(i+vec3(1,0,1)),f.x),
                 mix(hash31(i+vec3(0,1,1)),hash31(i+vec3(1,1,1)),f.x),f.y),f.z); }
void fragment(){
  float n = vnoise(wl*6.0)*0.6 + vnoise(wl*18.0)*0.4;
  vec3 c = mix(body_color, belly_color, smoothstep(-0.6, 0.5, wl.y*3.0));
  c *= 0.80 + 0.40*n;
  // 脊背纹路
  float stripes = smoothstep(0.55, 0.75, vnoise(vec3(wl.x*3.0, wl.y*8.0, wl.z*3.0)));
  c = mix(c, c*0.62, stripes*0.5);
  ALBEDO = c;
  ROUGHNESS = 0.85;
  EMISSION = accent_glow * glow_amount;
}
```
Cached by rounded color key.

Glow material: StandardMaterial3D emissive.

Builders with SurfaceTool. Helper `_put(st, mesh, pos, scale, rot_y)`:
```gdscript
static func _put(st: SurfaceTool, mesh: Mesh, pos: Vector3, scl: Vector3 = Vector3.ONE, yaw: float = 0.0, pitch: float = 0.0) -> void:
	var b := Basis(Vector3.UP, yaw) * Basis(Vector3.RIGHT, pitch)
	b = b.scaled(scl)
	st.append_from(mesh, 0, Transform3D(b, pos))
```
Note Basis.scaled scales columns (per-axis) ✓ works for non-uniform.

