render_mode diffuse_burley, specular_schlick_ggx;
uniform vec3 body_color : source_color = vec3(0.4,0.33,0.28);
uniform vec3 belly_color : source_color = vec3(0.55,0.48,0.4);
uniform vec3 accent_glow : source_color = vec3(0.0);
uniform float glow_amount = 0.0;
varying vec3 wp; varying vec3 wl;
void vertex(){ wp = (MODEL_MATRIX*vec4(VERTEX,1.0)).xyz; wl = VERTEX; }
float hash31(vec3 p){ p=fract(p*0.3183099+vec3(0.1,0.2,0.3)); p*=17.0; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float vnoise(vec3 x){ vec3 i=floor(x); vec3 f=fract(x); f=f*f*(3.0-2.0*f);
  return mix(mix(mix(hash31(i+vec3(0,0,0)),hash31(i+vec3(1,0,0)),f.x),
                 mix(hash31(i+vec3(0,1,0)),hash31(i+vec3(1,1,0)),f.x),f.y),
             mix(mix(hash31(i+vec3(0,0,1)),hash31(i+vec3(1,0,1)),f.x),
                 mix(hash31(i+vec3(0,1,1)),hash31(i+vec3(1,1,1)),f.x),f.y),f.z); }
void fragment(){
  float n = vnoise(wl*6.0)*0.6 + vnoise(wl*18.0)*0.4;
  vec3 c = mix(body_color, belly_color, smoothstep(-0.6, 0.5, wl.y*3.0));
  c *= 0.80 + 0.40*n;
  // 脊背纹路
  float stripes = smoothstep(0.55, 0.75, vnoise(vec3(wl.x*3.0, wl.y*8.0, wl.z*3.0)));
  c = mix(c, c*0.62, stripes*0.5);
  ALBEDO = c;
  ROUGHNESS = 0.85;
  EMISSION = accent_glow * glow_amount;
}
```
