	for i: int in range(4):
		var a2: float = TAU * float(i) / 4.0 + 0.5
		_put(st, _sph(), Vector3(cos(a2) * 0.34 * s, 0.62 * s, sin(a2) * 0.34 * s), Vector3(0.09 * s, 0.07 * s, 0.09 * s))

