extends Node

const MM = preload("res://scripts/entities/MonsterMesh.gd")

var t := 0
var bm: BattleManager = null

func _collect(n: Node, out: Array) -> void:
	if n is MeshInstance3D and n.mesh != null:
		out.append(n)
	for c in n.get_children():
		_collect(c, out)

func _bounds(n: Node) -> Array:
	var box := AABB()
	var first := true
	var tri := 0
	var meshes: Array = []
	_collect(n, meshes)
	for mi in meshes:
		var mb: AABB = mi.mesh.get_aabb()
		var wb: AABB = (mi.transform if mi.get_parent() == n else mi.get_parent().transform * mi.transform) * mb
		box = wb if first else box.merge(wb)
		first = false
		tri += mi.mesh.get_faces().size() / 3
	return [box.size, tri, meshes.size()]

func _ready() -> void:
	for nm in ["pig", "wolf", "lizard", "monkey", "bird", "worm", "red_buff", "blue_buff", "spatial_spirit", "river_spirit", "tyrant", "shadow_dragon", "storm_dragon"]:
		var v := MM.visual(nm)
		var r := _bounds(v)
		print("M ", nm, " size=", r[0], " tris=", r[1], " meshes=", r[2])
		v.free()
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		var ms: Array = get_tree().get_nodes_in_group("jungle_monsters")
		var with_vis := 0
		for m in ms:
			if m.get_node_or_null("MonsterVisual") != null:
				with_vis += 1
		print("M monsters=", ms.size(), " with_visual=", with_vis)
		# 高地砖块材质检查
		var csg_n := 0
		for c in bm.get_children():
			if c is CSGPolygon3D:
				csg_n += 1
				var mo = (c as CSGPolygon3D).material_override
				print("M highground_mat=", mo.get_class() if mo != null else "null", " shader_ok=", (mo is ShaderMaterial))
		print("M highground_csg=", csg_n)
	elif t == 360:
		get_tree().quit()
