{"command":"$p = (Resolve-Path 'scripts\entities\JungleMonster.gd'); $t = [System.IO.File]::ReadAllText($p)
$pairs = @(
	@('(?m)^\tis_dead = true\r?\n\tvisible = false\r?\n\tcollision_layer = 0', "`tis_dead = true`n`tcollision_layer = 0`n`t# 程序化死亡动画：倒地/塌陷 0.85s 后由 _update_anim 收尾隐藏`n`t_set_anim_clip(`"die`")"),
