content.arguments:
{"command":"$p = (Resolve-Path 'scripts\net\NetClientBattle.gd'); $t = [System.IO.File]::ReadAllText($p)
$t = $t.Replace("var _views := {}          # net_id -> {node, type, team, name, hp, maxhp, bar_off, target, set}", "var _views := {}          # net_id -> {node, type, team, name, hp, maxhp, bar_off, target, set}`nvar _tower_locks := {}      # 防御塔锁定光束：key(塔位) -> {mesh, from, to, cur, t}")
$t = $t.Replace("`tNetSession.net_tower_laser.connect(_on_tower_laser)", "`tNetSession.net_tower_laser.connect(_on_tower_laser)`n`tNetSession.net_tower_lock.connect(_on_tower_lock)")
$t = $t.Replace("`t_mouse_screen = get_viewport().get_mouse_position()", "`t_update_tower_locks(delta)`n`t_mouse_screen = get_viewport().get_mouse_position()")
$anchor = @'
func _on_tower_laser(from: Vector3, to: Vector3, team: int, dur: float) -> void:
	var c: Color = Vfx.team_color(team)
	Vfx.beam(from, to, c, 0.055, dur)
	await get_tree().create_timer(dur).timeout
	if is_inside_tree():
		Vfx.hit_spark(to, c, (from - to).normalized(), 0.8)
'@
$add = $anchor + @'


# 防御塔锁定光束：host 每 0.15s 刷新一次目标点，客户端逐帧把光束末端插值过去 → 视觉上一直锁定
func _on_tower_lock(from: Vector3, to: Vector3, team: int, active: bool) -> void:
	var key: String = "%d_%d" % [int(from.x * 10.0), int(from.z * 10.0)]
	if not active:
		var old: Dictionary = _tower_locks.get(key, {})
		if old.has("mesh"):
			var om = old["mesh"]
			if is_instance_valid(om):
				om.queue_free()
		_tower_locks.erase(key)
		return
	var rec: Dictionary = _tower_locks.get(key, {})
	if not rec.has("mesh") or not is_instance_valid(rec["mesh"]):
		var mi: MeshInstance3D = Vfx.make_beam_mesh()
		var col: Color = Vfx.team_color(team)
		mi.material_override.albedo_color = Color(col.r, col.g, col.b, 0.6)
		_static_root.add_child(mi)
		rec = {"mesh": mi, "from": from, "to": to, "cur": to}
		_tower_locks[key] = rec
	rec["from"] = from
	rec["to"] = to
	rec["t"] = Time.get_ticks_msec()


func _update_tower_locks(delta: float) -> void:
	if _tower_locks.is_empty():
		return
	var now := Time.get_ticks_msec()
	for key in _tower_locks.keys():
		var rec: Dictionary = _tower_locks[key]
		var mi = rec.get("mesh")
		if mi == null or not is_instance_valid(mi):
			_tower_locks.erase(key)
			continue
		# 1.2s 没刷新 → 视为锁定结束（漏包/塔被拆）
		if now - int(rec.get("t", now)) > 1200:
			mi.queue_free()
			_tower_locks.erase(key)
			continue
		var cur: Vector3 = rec.get("cur", rec["to"])
		cur = cur.lerp(rec["to"], clampf(delta * 16.0, 0.0, 1.0))
		rec["cur"] = cur
		Vfx.aim_beam(mi, rec["from"], cur, 0.035)
'@
if ($t.Contains($anchor)) { $t = $t.Replace($anchor, $add); "client ok" } else { "CLIENT MISS" }
[System.IO.File]::WriteAllText($p, $t)
"client_has=" + $t.Contains("func _update_tower_locks")
# 修掉前面插入的空格笔误
$p2 = (Resolve-Path 'scripts\entities\JungleMonster.gd'); $t2 = [System.IO.File]::ReadAllText($p2)
$t2 = $t2.Replace('_play_anim("idle" )', '_play_anim("idle")')
[System.IO.File]::WriteAllText($p2, $t2)
"idle_fix=" + (-not $t2.Contains('"idle" )'))","description":"Add client lock beam handling"}

