$p = (Resolve-Path 'scripts\net\NetClientBattle.gd'); $t = [System.IO.File]::ReadAllText($p)
$t = $t.Replace("var _views := {}          # net_id -> {node, type, team, name, hp, maxhp, bar_off, target, set}", "var _views := {}          # net_id -> {node, type, team, name, hp, maxhp, bar_off, target, set}`nvar _tower_locks := {}      # 防御塔锁定光束：key(塔位) -> {mesh, from, to, cur, t}")
$t = $t.Replace("`tNetSession.net_tower_laser.connect(_on_tower_laser)", "`tNetSession.net_tower_laser.connect(_on_tower_laser)`n`tNetSession.net_tower_lock.connect(_on_tower_lock)")
