{"command":"@'
extends Node

var t := 0
var bm: BattleManager = null
var tur: Turret = null
var mn: Minion = null
var mm: JungleMonster = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		print("B turrets=", bm.turrets.size())
		if bm.turrets.size() > 0:
			tur = bm.turrets[0] as Turret
			mn = Minion.new()
			mn.setup({"name": "melee", "team": 1, "max_health": 500, "attack": 10})
			mn.position = tur.position + Vector3(5.0, 0.0, 0.0)
			add_child(mn)
			tur.current_target = mn
	elif t == 350:
		var beam = tur.get("_lock_beam")
		var ok: bool = beam != null and is_instance_valid(beam) and (beam as Node3D).visible
		print("B beam_visible=", ok)
		if ok:
			var dist: float = (beam as MeshInstance3D).global_transform.origin.distance_to(tur.global_position + Vector3(0, 2.0, 0))
			print("B beam_center_to_tower=", "%.2f" % dist, " len=", "%.2f" % (beam as MeshInstance3D).scale.y)
		if mn != null:
			mn.queue_free()
			mn = null
	elif t == 380:
		var beam2 = tur.get("_lock_beam")
		print("B beam_after_target_gone=", (beam2 != null and is_instance_valid(beam2) and (beam2 as Node3D).visible))
		mm = JungleMonster.new()
		mm.setup({"name": "wolf", "team": 2, "max_health": 1000, "attack": 5})
		mm.position = Vector3(-30.0, 0.0, 30.0)
		add_child(mm)
	elif t == 400:
		print("A anim_root=", mm.get("_anim_root") != null, " state=", mm.get("_anim_state"))
		mm._play_anim("attack-melee-left")
		print("A state_attack=", mm.get("_anim_state"))
	elif t == 415:
		print("A state_after_lunge=", mm.get("_anim_state"))
		mm.die(null)
		print("A state_die=", mm.get("_anim_state"), " visible_on_death=", mm.visible)
	elif t == 480:
		print("A after_death visible=", mm.visible)
		mm._respawn()
		print("A respawn visible=", mm.visible, " state=", mm.get("_anim_state"))
	elif t == 495:
		var n := 0
		for c in mm.get_children():
			if str(c.name).begins_with("MonsterVisual"):
				n += 1
		print("A respawn_visuals=", n, " anim_root=", mm.get("_anim_root") != null)
		get_tree().quit()
