$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx10/probe.tscn','--quit-after','3000' -PassThru -RedirectStandardOutput 'devfx10\p.out' -RedirectStandardError 'devfx10\p.err'
$d = $a.WaitForExit(300000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx10\p.out -ErrorAction SilentlyContinue | Select-String -Pattern '^(P|B|A) ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx10\p.err, devfx10\p.out -ErrorAction SilentlyContinue | Select-String -Pattern 'SCRIPT ERROR|Parse Error|SHADER ERROR' -Context 0,2 | Select-Object -First 8 | ForEach-Object { $_.Line.Trim() }","description":"Rerun verification with corrected timing","timeoutMs":400000}

