{"command":"@'
extends Node

var t := 0
var bm: BattleManager = null
var mm: JungleMonster = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _count(n: Node, nm: String, depth: int = 0) -> int:
	var c := 0
	if str(n.name) == nm:
		c += 1
	for ch in n.get_children():
		c += _count(ch, nm, depth + 1)
	return c

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		mm = JungleMonster.new()
		mm.setup({"name": "wolf", "team": 2, "max_health": 1000, "attack": 5})
		mm.position = Vector3(-30.0, 0.0, 30.0)
		add_child(mm)
	elif t == 340:
		print("A walkfeel=", _count(mm, "WalkFeel"), " visual=", _count(mm, "MonsterVisual"))
		mm._play_anim("walk")
		print("A move_state=", mm.get("_anim_state"))
	elif t == 350:
		var ar = mm.get("_anim_root")
		print("A move_bob=", "%.3f" % (ar as Node3D).position.y)
		mm._play_anim("attack-melee-left")
	elif t == 356:
		var ar2 = mm.get("_anim_root")
		print("A attack_state=", mm.get("_anim_state"), " lunge=", "%.2f" % (ar2 as Node3D).position.z)
	elif t == 380:
		mm.die(null)
		print("A die_visible=", mm.visible, " state=", mm.get("_anim_state"))
	elif t == 450:
		print("A death_hidden=", (not mm.visible))
		mm._respawn()
	elif t == 470:
		print("A respawn vis=", mm.visible, " state=", mm.get("_anim_state"), " walkfeel=", _count(mm, "WalkFeel"), " visual=", _count(mm, "MonsterVisual"), " anim=", mm.get("_anim_root") != null)
		mm._play_anim("attack-melee-left")
	elif t == 476:
		var ar3 = mm.get("_anim_root")
		print("A respawn_attack_state=", mm.get("_anim_state"), " lunge=", "%.2f" % (ar3 as Node3D).position.z)
		get_tree().quit()
