@'
extends Node

var t := 0
var bm: BattleManager = null
var tur: Turret = null
var dummy: Minion = null
var cam: Camera3D = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		print("P team_color0=", Vfx.team_color(0))
		tur = bm.turrets[0] as Turret
		dummy = Minion.new()
		dummy.setup({"name": "melee", "team": 1, "max_health": 9999999, "attack": 1})
		dummy.position = tur.position + Vector3(4.0, 0.0, 0.0)
		dummy.can_move = false
		add_child(dummy)
		tur.current_target = dummy
	elif t == 335:
		cam = Camera3D.new()
		cam.fov = 60.0
		add_child(cam)
		cam.global_position = tur.global_position + Vector3(0.0, 7.0, 11.0)
		cam.look_at(tur.global_position + Vector3(2.0, 3.0, 0.0), Vector3.UP)
		cam.make_current()
	elif t == 365:
		var beam = tur.get("_lock_beam")
		print("P beam_valid=", beam != null and is_instance_valid(beam), " visible=", (beam as Node3D).visible if beam != null else false)
		var from: Vector3 = tur.global_position + Vector3(0, 2, 0)
		var to: Vector3 = dummy.global_position + Vector3(0, 1, 0)
		var a2: Vector2 = cam.unproject_position(from)
		var b2: Vector2 = cam.unproject_position(to)
		print("P screen_a=", a2, " screen_b=", b2)
		var img := get_viewport().get_texture().get_image()
		print("P img=", img.get_width(), "x", img.get_height())
		var hit := 0
		var tot := 0
		for i in range(0, 81):
			var p: Vector2 = a2.lerp(b2, i / 80.0)
			if p.x < 2 or p.y < 2 or p.x > img.get_width() - 3 or p.y > img.get_height() - 3:
				continue
			tot += 1
			var best := 0.0
			for dx in [-1, 0, 1]:
				for dy in [-1, 0, 1]:
					var c: Color = img.get_pixel(int(p.x) + dx, int(p.y) + dy)
					best = maxf(best, (c.r + c.g + c.b) / 3.0)
			if best > 0.45:
				hit += 1
		print("P beam_pixels=", hit, "/", tot)
		var midp: Vector2 = (a2 + b2) * 0.5
		var ctrl := 0
		var ctot := 0
		for i in range(-25, 26):
			var p2: Vector2 = midp + Vector2(0, i * 2)
			if p2.y < 1 or p2.y > img.get_height() - 2 or p2.x < 1 or p2.x > img.get_width() - 2:
				continue
			ctot += 1
			var c2: Color = img.get_pixel(int(p2.x), int(p2.y))
			if (c2.r + c2.g + c2.b) / 3.0 > 0.45:
				ctrl += 1
		print("P ctrl_pixels=", ctrl, "/", ctot)
		img.save_png("res://devfx11/shot.png")
		get_tree().quit()
