{"command":"New-Item -ItemType Directory -Force -Path .cache, devfx12 | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

var t := 0
var bm: BattleManager = null
var painter: Control = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

class P extends Control:
	func _draw() -> void:
		MinimapDraw.draw_hero(self, Vector2(200, 300), Vector2(0, -1), Color(0.0, 0.886, 1.0), 0.8, true, false, 0.0, "亚瑟")
		MinimapDraw.draw_hero(self, Vector2(400, 300), Vector2(1, 0), Color(1.0, 0.33, 0.26), 0.5, false, false, 0.0, "安琪拉")
		MinimapDraw.draw_hero(self, Vector2(300, 450), Vector2(0, 1), Color(1.0, 0.33, 0.26), 0.3, false, false, 0.0, "后羿")
		MinimapDraw.draw_hero(self, Vector2(500, 450), Vector2(0, 1), Color(1.0, 0.33, 0.26), 0.3, false, true, 7.0, "妲己")

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager") as BattleManager
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 260:
		print("M heroes=", bm.heroes.size())
		var cl := CanvasLayer.new()
		cl.layer = 100
		add_child(cl)
		painter = P.new()
		painter.set_anchors_preset(Control.PRESET_FULL_RECT)
		cl.add_child(painter)
	elif t == 280:
		painter.queue_redraw()
	elif t == 290:
		var img := get_viewport().get_texture().get_image()
		var diff := 0
		var tot := 0
		var lit1 := 0
		var lit2 := 0
		for dy in range(-30, 31, 2):
			for dx in range(-30, 31, 2):
