{"command":"New-Item -ItemType Directory -Force -Path .cache, devfx14 | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

var t := 0
var ui = null
var done := false

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _collect(node: Node, out: Array) -> void:
	for ch in node.get_children():
		if (ch is Label or ch is Button or ch is RichTextLabel) and ch.is_visible_in_tree():
			var txt := ""
			if ch is Label or ch is Button:
				txt = str(ch.text)
			out.append({"r": ch.get_global_rect(), "n": str(ch.name), "t": txt.substr(0, 16), "c": ch.get_class()})
		_collect(ch, out)

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		var bm = get_tree().get_first_node_in_group("battle_manager")
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		ui = get_tree().get_first_node_in_group("ui_manager")
		if ui == null:
			for c in get_tree().root.get_children():
				if c is CanvasLayer or c is Node:
					pass
			ui = get_node_or_null("/root/UiManager")
		print("S ui=", ui)
		if ui != null:
			ui._open_shop()
			done = true
	elif t == 350 and done:
		var shop = ui.shop_ui
		print("S shop_visible=", shop != null and shop.visible)
		var out: Array = []
		_collect(shop, out)
		print("S nodes=", out.size())
		var reported := 0
		for i in range(out.size()):
			for j in range(i + 1, out.size()):
				var a = out[i]
				var b = out[j]
				var ra: Rect2 = a["r"]
				var rb: Rect2 = b["r"]
				if ra.size.x <= 1.0 or rb.size.x <= 1.0 or ra.size.y <= 1.0 or rb.size.y <= 1.0:
					continue
				var inter: Rect2 = ra.intersection(rb)
				var ia: float = inter.size.x * inter.size.y
				if ia <= 0.0:
					continue
				var mina: float = minf(ra.size.x * ra.size.y, rb.size.x * rb.size.y)
				if mina <= 0.0:
					continue
				if ia / mina > 0.30:
					print("S OVERLAP ", a["c"], "[", a["t"], "] ", ra, " <-> ", b["c"], "[", b["t"], "] ", rb, " frac=", "%.2f" % (ia / mina))
					reported += 1
					if reported >= 18:
						break
			if reported >= 18:
				break
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx14\probe.gd
@'
