{"command":"@'
extends Node

var t := 0
var ui = null
var collected: Array = []

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _collect(node: Node, out: Array) -> void:
	for ch in node.get_children():
		if (ch is Label or ch is Button or ch is RichTextLabel) and ch.is_visible_in_tree():
			var txt := ""
			if ch is Label or ch is Button:
				txt = str(ch.text)
			out.append({"node": ch, "r": ch.get_global_rect(), "t": txt.substr(0, 16), "c": ch.get_class()})
		_collect(ch, out)

func _is_nested(a: Node, b: Node) -> bool:
	if a == null or b == null:
		return true
	if a.is_ancestor_of(b) or b.is_ancestor_of(a):
		return true
	return false

func _report(tag: String) -> void:
	var out: Array = []
	_collect(ui.shop_ui, out)
	print("S ", tag, " nodes=", out.size())
	var reported := 0
	for i in range(out.size()):
		for j in range(i + 1, out.size()):
			var a = out[i]
			var b = out[j]
			var na: Node = a["node"]
			var nb: Node = b["node"]
			if _is_nested(na, nb):
				continue
			var ra: Rect2 = a["r"]
			var rb: Rect2 = b["r"]
			if ra.size.x <= 1.0 or rb.size.x <= 1.0 or ra.size.y <= 1.0 or rb.size.y <= 1.0:
				continue
			var inter: Rect2 = ra.intersection(rb)
			var ia: float = inter.size.x * inter.size.y
			if ia <= 0.0:
				continue
			var mina: float = minf(ra.size.x * ra.size.y, rb.size.x * rb.size.y)
			if mina <= 0.0:
				continue
			if ia / mina > 0.25:
				print("S ", tag, " OVERLAP ", a["c"], "[", a["t"], "] ", ra, " <-> ", b["c"], "[", b["t"], "] ", rb)
				reported += 1
				if reported >= 8:
					return

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		var bm = get_tree().get_first_node_in_group("battle_manager")
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		ui = get_node_or_null("/root/UiManager")
		ui._open_shop()
	elif t == 350:
		_report("grid")
	elif t == 360:
		ui._on_shop_item_selected(str(ui.shop_grid_ids[0]))
	elif t == 380:
		_report("detail")
	elif t == 390:
		ui._on_category_selected("防御")
	elif t == 410:
		_report("defense")
	elif t == 420:
		get_tree().quit()
