{"command":"@'
extends Node

var t := 0
var ui = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _sibling_overlaps(root: Node, tag: String) -> int:
	var bad := 0
	for parent in _all(root):
		var kids: Array = []
		for ch in parent.get_children():
			if (ch is Control) and ch.is_visible_in_tree():
				var r: Rect2 = ch.get_global_rect()
				if r.size.x > 1.0 and r.size.y > 1.0:
					kids.append({"n": ch, "r": r})
		for i in range(kids.size()):
			for j in range(i + 1, kids.size()):
				var ra: Rect2 = kids[i]["r"]
				var rb: Rect2 = kids[j]["r"]
				var inter: Rect2 = ra.intersection(rb)
				var ia: float = inter.size.x * inter.size.y
				if ia <= 2.0:
					continue
				var mina: float = minf(ra.size.x * ra.size.y, rb.size.x * rb.size.y)
				if mina <= 0.0:
					continue
				if ia / mina > 0.25:
					var ta := ""
					if kids[i]["n"] is Label or kids[i]["n"] is Button:
						ta = str(kids[i]["n"].text).substr(0, 12)
					print("X ", tag, " ", parent.get_class(), "<", str(parent.name), "> ", kids[i]["n"].get_class(), "[", ta, "] ", ra, " <-> ", kids[j]["n"].get_class(), " ", rb)
					bad += 1
					if bad > 10:
						return bad
	return bad

func _all(n: Node) -> Array:
	var out: Array = [n]
	for ch in n.get_children():
		out.append_array(_all(ch))
	return out

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		var bm = get_tree().get_first_node_in_group("battle_manager")
		if bm != null:
			bm._start_game("亚瑟")
	elif t == 320:
		ui = get_node_or_null("/root/UiManager")
		ui._open_shop()
	elif t == 360:
		var grid = ui.shop_item_grid
		print("X grid_cards=", grid.get_child_count(), " first_card_size=", (grid.get_child(0) as Control).size, " col=", ui.shop_card_w)
		print("X grid_bad=", _sibling_overlaps(grid, "grid"))
		print("X detail_bad=", _sibling_overlaps(ui.shop_detail_panel, "detail"))
		print("X owned_bad=", _sibling_overlaps(ui.shop_owned_container, "owned"))
	elif t == 380:
		ui._on_shop_item_selected(str(ui.shop_grid_ids[0]))
	elif t == 400:
		print("X detail2_bad=", _sibling_overlaps(ui.shop_detail_panel, "detail2"))
		get_tree().quit()
