@'
extends Node

var t := 0
var layer: CanvasLayer = null
var p: Control = null

const TAB = preload("res://scripts/mobile/TouchActionButton.gd")
const STB = preload("res://scripts/mobile/SkillTouchButton.gd")

class P extends Control:
	const MD = preload("res://scripts/ui/MinimapDraw.gd")
	func _draw() -> void:
		draw_rect(Rect2(Vector2.ZERO, size), Color(0.03, 0.04, 0.06, 1.0), true)
		MD.draw_hero(self, Vector2(160, 700), Vector2(0, -1), Color(0.0, 0.886, 1.0), 0.8, true, false, 0.0, "亚瑟")
		MD.draw_hero(self, Vector2(320, 700), Vector2(0, -1), Color(1.0, 0.33, 0.26), 0.8, false, false, 0.0, "亚瑟")

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 40:
		layer = CanvasLayer.new()
		layer.layer = 120
		add_child(layer)
		p = P.new()
		p.set_anchors_preset(Control.PRESET_FULL_RECT)
		layer.add_child(p)
		var b1 = TAB.new()
		b1.name_text = "回城"
		b1.icon_kind = "recall"
		b1.color = Color(0.20, 0.28, 0.42, 0.94)
		b1.position = Vector2(240, 300)
		b1.size = Vector2(220, 220)
		layer.add_child(b1)
		var b2 = STB.new()
		b2.display_name = "恢复"
		b2.name_below = true
		b2.icon_kind = "recover"
		b2.color = Color(0.22, 0.38, 0.26, 0.94)
		b2.position = Vector2(520, 300)
		b2.size = Vector2(220, 220)
		layer.add_child(b2)
	elif t == 70:
		p.queue_redraw()
		var img := get_viewport().get_texture().get_image()
		for spec in [[Vector2(240, 300), "回城"], [Vector2(520, 300), "恢复"]]:
			var org: Vector2 = spec[0]
			var ymin := 9999
			var ymax := -1
			for y in range(int(org.y) + 100, int(org.y) + 220):
				var lit := 0
				for x in range(int(org.x) + 20, int(org.x) + 210):
					var c: Color = img.get_pixel(x, y)
					if c.r > 0.80 and c.g > 0.80 and c.b > 0.80:
						lit += 1
				if lit >= 5:
					ymin = mini(ymin, y)
					ymax = maxi(ymax, y)
			print("P ", spec[1], " text_rows=", ymin, "..", ymax, " mid=", "%.1f" % ((ymin + ymax) * 0.5))
		for spec2 in [[Vector2(160, 700), "self"], [Vector2(320, 700), "enemy"]]:
			var c0: Vector2 = spec2[0]
			var maxr := 0.0
			var green := 0
			var green_maxr := 0.0
			for dy in range(-30, 31):
				for dx in range(-30, 31):
					var cc: Color = img.get_pixel(int(c0.x) + dx, int(c0.y) + dy)
					var lum := (cc.r + cc.g + cc.b) / 3.0
					var dd := sqrt(float(dx * dx + dy * dy))
					if lum > 0.10:
						maxr = maxf(maxr, dd)
					if cc.g > 0.70 and cc.r < 0.50 and cc.b < 0.60:
						green += 1
						green_maxr = maxf(green_maxr, dd)
			print("P ", spec2[1], " extent_r=", "%.1f" % maxr, " green_px=", green, " green_r=", "%.1f" % green_maxr)
		get_tree().quit()
