content.arguments:
{"command":"$p = (Resolve-Path 'scripts\core\BattleManager.gd')
$lines = New-Object System.Collections.Generic.List[string]
[System.IO.File]::ReadAllLines($p) | ForEach-Object { $lines.Add($_) }
function Idx([string]$needle, [int]$from = 0) {
	for ($i = $from; $i -lt $script:lines.Count; $i++) { if ($script:lines[$i].Contains($needle)) { return $i } }
	return -1
}
function Splice([int]$at, [int]$count, [string[]]$new) {
	for ($k = 0; $k -lt $count; $k++) { $script:lines.RemoveAt($at) }
	for ($k = $new.Count - 1; $k -ge 0; $k--) { $script:lines.Insert($at, $new[$k]) }
}
$fail = @()
# 3) 立绘/覆盖层引用 + 底部右栏引用 + 底部居中占位
$i = Idx 'center.add_child(preview_box)'
if ($i -ge 0) { Splice ($i + 1) 0 @('	sel_preview_box = preview_box') } else { $fail += 'preview_box' }
$i = Idx 'center.add_child(overlay)'
if ($i -ge 0) { Splice ($i + 1) 0 @('	sel_overlay = overlay') } else { $fail += 'overlay' }
$i = Idx 'bottom.add_child(right)'
if ($i -ge 0) {
	Splice ($i + 1) 0 @('	var sp_l := Control.new()',
		'	sp_l.size_flags_horizontal = Control.SIZE_EXPAND_FILL',
		'	bottom.add_child(sp_l)',
		'	bottom.move_child(sp_l, 0)',
		'	var sp_r := Control.new()',
		'	sp_r.size_flags_horizontal = Control.SIZE_EXPAND_FILL',
		'	bottom.add_child(sp_r)',
		'	sel_bottom_row = bottom')
} else { $fail += 'bottom' }
$i = Idx 'right.add_child(right_tabs)'
if ($i -ge 0) { Splice ($i + 1) 0 @('	sel_right_tabs = right_tabs') } else { $fail += 'right_tabs' }
$i = Idx 'right.add_child(right_body)'
if ($i -ge 0) { Splice ($i + 1) 0 @('	sel_right_body = right_body') } else { $fail += 'right_body' }
# 4) 换英雄按钮
$i = Idx 'btn_row.add_child(leave)'
if ($i -ge 0) {
	Splice $i 0 @('	sel_back_btn = _sel_btn("换英雄", UiKit.C_PANEL_EDGE, false, Vector2(180, 92))',
		'	sel_back_btn.name = "SelectBackToPick"',
		'	sel_back_btn.size_flags_vertical = Control.SIZE_SHRINK_CENTER',
		'	sel_back_btn.add_theme_font_size_override("font_size", _sel_fs(UiKit.FS_MD))',
		'	sel_back_btn.pressed.connect(_on_back_to_pick)',
		'	btn_row.add_child(sel_back_btn)')
} else { $fail += 'leave' }
# 5) 技能悬浮详情浮层 + 阶段初始化
$i = Idx '# 先入树让 HeroPreview 建好 SubViewport'
if ($i -ge 0) {
	Splice $i 0 @('	# 技能悬浮详情浮层（悬停技能 chip 时弹出）',
		'	sel_skill_tip = PanelContainer.new()',
		'	sel_skill_tip.name = "SelectSkillTip"',
		'	sel_skill_tip.visible = false',
		'	sel_skill_tip.mouse_filter = Control.MOUSE_FILTER_IGNORE',
		'	sel_skill_tip.custom_minimum_size = Vector2(380, 0)',
		'	sel_skill_tip.add_theme_stylebox_override("panel", UiKit.skin_card(UiKit.C_TEAM0, false, 0.96))',
		'	var tip_v := VBoxContainer.new()',
		'	tip_v.add_theme_constant_override("separation", 4)',
		'	sel_skill_tip.add_child(tip_v)',
		'	sel_skill_tip_title = _sel_label("", _sel_fs(UiKit.FS_MD), SEL_GOLD, false)',
		'	tip_v.add_child(sel_skill_tip_title)',
		'	sel_skill_tip_body = _sel_label("", _sel_fs(UiKit.FS_XS), SEL_TEXT, false)',
		'	sel_skill_tip_body.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART',
		'	sel_skill_tip_body.custom_minimum_size = Vector2(340, 0)',
		'	tip_v.add_child(sel_skill_tip_body)',
		'	root.add_child(sel_skill_tip)')
} else { $fail += 'tooltip' }
$i = Idx '_start_sel_draft()'
if ($i -ge 0) {
	Splice ($i + 1) 0 @('	sel_pick_hint.text = "分路：%s · 只能选择%s英雄" % [sel_lane_name, sel_lane_role]',
		'	_set_sel_stage(true)')
} else { $fail += 'draft' }
[System.IO.File]::WriteAllLines($p, $lines)
"step2 FAIL=" + ($fail -join ',')","description":"Wire refs, tooltip, back button"}

