		if sk.applies_slow > 0.0: lines.append("减速 %d%% · %.1f 秒" % [int(round(sk.applies_slow * 100.0)), sk.slow_duration])
		if sk.is_channeling: lines.append("引导施法")
	sel_skill_tip_body.text = "\n".join(lines) if not lines.is_empty() else "（无详细数据）"
	sel_skill_tip.visible = true
	sel_skill_tip.reset_size()
	var mp: Vector2 = get_viewport().get_mouse_position()
	var vs: Vector2 = get_viewport().get_visible_rect().size
	var sz: Vector2 = sel_skill_tip.size
	var pos := mp + Vector2(20, -sz.y - 16)
	pos.x = clampf(pos.x, 8.0, maxf(8.0, vs.x - sz.x - 8.0))
	pos.y = clampf(pos.y, 8.0, maxf(8.0, vs.y - sz.y - 8.0))
	sel_skill_tip.position = pos

func _tip_dist(v: float) -> String:
	return "%.1f" % (v * 0.01) if v > 20.0 else "%.1f" % v

func _hide_skill_tip() -> void:
	if sel_skill_tip != null and is_instance_valid(sel_skill_tip):
		sel_skill_tip.visible = false
```

Then:
- chip hover connect after `chip.add_child(row)` in `_refresh_sel_preview`.
- `_on_hero_selected`: after `_apply_default_summoner(type)` insert `_refresh_sel_preview(type)` + `_set_sel_stage(false)`.
- `_lock_player_pick`: after `sel_player_picked = true` insert `_set_sel_stage(false)` + `if sel_back_btn: sel_back_btn.visible = false`.

Do it.

