{"command":"@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._show_hero_select_ui()
	elif t == 60:
		var br: Rect2 = bm.sel_bottom_row.get_global_rect()
		var cr: Rect2 = bm.select_confirm_btn.get_global_rect()
		print("A bottom_h=", "%.1f" % br.size.y, " confirm_y=", "%.1f" % cr.position.y, " vp_h=", get_viewport().get_visible_rect().size.y)
		var first = bm.sel_hero_strip.get_child(0)
		var hname: String = str(first.name).replace("HeroCard_", "")
		bm._on_hero_selected(hname, first, Color.WHITE)
	elif t == 80:
		var br2: Rect2 = bm.sel_bottom_row.get_global_rect()
		print("B bottom_h=", "%.1f" % br2.size.y, " rightbody_visible=", bm.sel_right_body.visible)
		# 模拟鼠标悬停到第 1 个技能 chip 上
		var box = bm.sel_prev_skill_box
		var chip = box.get_child(0)
		var c: Vector2 = chip.get_global_rect().get_center()
		get_viewport().warp_mouse(c)
		print("B chip_center=", c)
	elif t == 85:
		print("B hover_tip_visible=", bm.sel_skill_tip.visible, " tip_rect=", bm.sel_skill_tip.get_global_rect())
		get_viewport().warp_mouse(Vector2(4, 4))
	elif t == 90:
		print("B tip_after_leave=", bm.sel_skill_tip.visible)
		get_tree().quit()
