{"command":"$p = (Resolve-Path 'scripts\core\BattleManager.gd'); $t = [System.IO.File]::ReadAllText($p)
$old = "	_bush_positions = bushes"
$new = @'
	# 塔射程内 / 高地内不放草丛（塔下、高地内部不应有隐身草）
	var _bush_kept: Array = []
	for _bp in bushes:
		if _bush_forbidden(_bp):
			continue
		_bush_kept.append(_bp)
	bushes = _bush_kept
	_bush_positions = bushes
'@
if ($t.Contains($old)) {
	$t = $t.Replace($old, $new.Replace("`r`n","`n"))
	"bush filter ok"
} else { "MISS bush anchor" }
# 追加两个辅助函数到 _is_inside_high_ground 之后（该函数以 '\treturn false' 结束）
$anchor = "	if pos.distance_squared_to(red_center) < hg_radius * hg_radius:`n		return true`n	return false"
$add = @'
	if pos.distance_squared_to(red_center) < hg_radius * hg_radius:
		return true
	return false

# 草丛禁区：高地内部，或落在任一防御塔射程（8.9m + 塔体 0.5 + 草丛半宽 1.0）内
func _bush_forbidden(bp: Vector3) -> bool:
	if _is_inside_high_ground(bp):
		return true
	var p := Vector2(bp.x, bp.z)
	for tp in _turret_ground_positions():
		if p.distance_to(tp) <= 10.4:
			return true
	return false

# 全部防御塔地面坐标（与 _create_turrets 的 20 座塔一致）
func _turret_ground_positions() -> Array:
	return [
		Vector2(28, 58), Vector2(-15, 56), Vector2(-35, 55),
		Vector2(-14, 14), Vector2(-27, 27), Vector2(-40, 40),
		Vector2(-58, -28), Vector2(-56, 15), Vector2(-55, 35), Vector2(-53, 53),
		Vector2(-28, -58), Vector2(15, -56), Vector2(35, -55),
		Vector2(14, -14), Vector2(27, -27), Vector2(40, -40),
		Vector2(58, 28), Vector2(56, -15), Vector2(55, -35), Vector2(53, -53),
	]
'@
if ($t.Contains($anchor)) { $t = $t.Replace($anchor, $add.Replace("`r`n","`n")); "helpers ok" } else { "MISS helper anchor" }
[System.IO.File]::WriteAllText($p, $t)","description":"Filter bushes out of turret range and high ground"}

