{"command":"New-Item -ItemType Directory -Force .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
New-Item -ItemType Directory -Force devfx16 | Out-Null
@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 70:
		var bushes: Array = bm._bush_positions
		var bad_hg := 0
		var bad_tower := 0
		var min_d := 999.0
		for bp in bushes:
			var p := Vector2(bp.x, bp.z)
			if bm._is_inside_high_ground(bp):
				bad_hg += 1
			for tp in bm._turret_ground_positions():
				var d: float = p.distance_to(tp)
				min_d = minf(min_d, d)
				if d <= 10.4:
					bad_tower += 1
		var nodes := 0
		for c in bm.get_children():
			if c is Bush:
				nodes += 1
		print("BUSHEX kept=", bushes.size(), " nodes=", nodes, " bad_hg=", bad_hg, " bad_tower=", bad_tower, " min_tower_dist=", "%.1f" % min_d)
		print("BUSHEX turrets=", bm.turrets.size())
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx16\probe.gd
@'
