$d = $a.WaitForExit(300000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx16\p.out -ErrorAction SilentlyContinue | Select-String -Pattern '^BUSHEX' | ForEach-Object { $_.Line.Trim() }
