content.arguments:
{"command":"$u = Get-Content scripts\core\BattleManager.gd
$start = ($u | Select-String -Pattern 'var bushes = \[' | Select-Object -First 1).LineNumber
$end = ($u | Select-String -Pattern '_bush_positions = bushes' | Select-Object -First 1).LineNumber
$pts = @()
for ($i = $start; $i -lt $end - 1; $i++) {
	if ($u[$i] -match 'Vector3\(\s*(-?[\d.]+)\s*,\s*0\s*,\s*(-?[\d.]+)\s*\)') { $pts += ,@([double]$matches[1], [double]$matches[2]) }
}
$turrets = @(@(28,58),@(-15,56),@(-35,55),@(-14,14),@(-27,27),@(-40,40),@(-58,-28),@(-56,15),@(-55,35),@(-53,53),@(-28,-58),@(15,-56),@(35,-55),@(14,-14),@(27,-27),@(40,-40),@(58,28),@(56,-15),@(55,-35),@(53,-53))
$removed = @()
foreach ($p in $pts) {
	$bad = $false
	if ([math]::Sqrt([math]::Pow($p[0]+60,2)+[math]::Pow($p[1]-60,2)) -lt 33) { $bad = $true }
	if ([math]::Sqrt([math]::Pow($p[0]-60,2)+[math]::Pow($p[1]+60,2)) -lt 33) { $bad = $true }
	foreach ($t in $turrets) { if ([math]::Sqrt([math]::Pow($p[0]-$t[0],2)+[math]::Pow($p[1]-$t[1],2)) -le 10.4) { $bad = $true } }
	if ($bad) { $removed += "($($p[0]),$($p[1]))" }
}
"total=$($pts.Count) removed=$($removed.Count) kept=$($pts.Count - $removed.Count)"
"removed: " + ($removed -join ' ')","description":"Count removed bushes"}

