{"command":"$p = (Resolve-Path 'scripts\core\WalkFeel.gd'); $t = [System.IO.File]::ReadAllText($p)
$r1o = '	var _primed := false'
$r1n = '	var _primed := false' + "`n" + '	# 腿部枢轴（可选）：迈步时前后摆动，消除“贴地滑行”感' + "`n" + '	var legs: Array = []' + "`n" + '	var leg_swing := 0.55' + "`n" + '	var leg_base: Array = []'
if ($t.Contains($r1o)) { $t = $t.Replace($r1o, $r1n); 'r1 ok' } else { 'MISS r1' }
$r2o = '		dust_size = float(o.get("dust_size", 0.22))'
$r2n = $r2o + "`n" + '		legs = o.get("legs", [])' + "`n" + '		leg_swing = float(o.get("leg_swing", 0.55))' + "`n" + '		for l in legs:' + "`n" + '			leg_base.append((l as Node3D).rotation.x)'
if ($t.Contains($r2o)) { $t = $t.Replace($r2o, $r2n); 'r2 ok' } else { 'MISS r2' }
$r3o = '			model.rotation.z = lerpf(model.rotation.z, base_rot.z, k)'
$r3n = $r3o + "`n" + '			for i in legs.size():' + "`n" + '				var l0: Node3D = legs[i]' + "`n" + '				if is_instance_valid(l0):' + "`n" + '					l0.rotation.x = lerpf(l0.rotation.x, float(leg_base[i]), k)'
if ($t.Contains($r3o)) { $t = $t.Replace($r3o, $r3n); 'r3 ok' } else { 'MISS r3' }
$r4o = '		model.rotation.x = base_rot.x + lean_amp * f'
$r4n = $r4o + "`n" + '		# 双腿交替前后摆（步频驱动，幅度随速度）' + "`n" + '		for i in legs.size():' + "`n" + '			var lg: Node3D = legs[i]' + "`n" + '			if not is_instance_valid(lg):' + "`n" + '				continue' + "`n" + '			var sgn := 1.0 if i == 0 else -1.0' + "`n" + '			lg.rotation.x = float(leg_base[i]) + sin(phase) * leg_swing * f * sgn'
if ($t.Contains($r4o)) { $t = $t.Replace($r4o, $r4n); 'r4 ok' } else { 'MISS r4' }
[System.IO.File]::WriteAllText($p, $t)","description":"Add leg swing support to WalkFeel"}

