{"command":"@'
extends Node

var t := 0
var mn = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		var bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		mn = load("res://scripts/entities/Minion.gd").new()
		mn.display_name = "melee"
		mn.team = 0
		add_child(mn)
		mn.global_position = Vector3(0, 0, 0)
	elif t > 60 and t <= 120:
		mn.global_position.x += 0.055   # 约 3.3 m/s
	elif t == 122:
		var w = mn.get_node("WalkFeel")
		var l: Node3D = mn.visual.get_node("ModelPivot/LegL")
		var r: Node3D = mn.visual.get_node("ModelPivot/LegR")
		print("SWING legL=", "%.3f" % l.rotation.x, " legR=", "%.3f" % r.rotation.x,
			" opposite=", signf(l.rotation.x) != signf(r.rotation.x), " y=", "%.4f" % mn.visual.position.y,
			" spd=", "%.2f" % w.spd)
