@'
extends Node

var t := 0
var bm = null
var hud = null
var acc := 0
var n := 0

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 150:
		hud = get_tree().get_first_node_in_group("hud")
		if hud == null:
			for c in get_tree().root.get_children():
				if c is CanvasLayer and c.has_method("_update_health_bars"):
					hud = c
		print("M hud=", hud != null)
		if hud == null:
			get_tree().quit()
	elif t > 150 and t < 330:
		var t0 := Time.get_ticks_usec()
		hud._update_health_bars()
		acc += Time.get_ticks_usec() - t0
		n += 1
	elif t == 330:
		var ents := get_tree().get_nodes_in_group("entities")
		var bars: Dictionary = hud.unit_bars
		var infos: Dictionary = hud.hero_info_controls
		var labels := 0
		for k in bars.keys():
			if bars[k].has("label"): labels += 1
		var children := hud.get_child_count()
		print("M entities=", ents.size(), " unit_bars=", bars.size(), " labels=", labels,
			" hero_infos=", infos.size(), " hud_children=", children)
		print("M frame_cost_ms=", "%.3f" % (float(acc) / float(n) / 1000.0), " samples=", n)
		# 统计当前屏内可见实体数
		var cam = get_viewport().get_camera_3d()
		var onscreen := 0
		for e in ents:
			if not is_instance_valid(e): continue
			var wp: Vector3 = e.global_position + Vector3.UP * 1.6
			var sp: Vector2 = cam.unproject_position(wp)
			var vp: Vector2 = get_viewport().get_visible_rect().size
			if sp.x >= 0 and sp.y >= 0 and sp.x <= vp.x and sp.y <= vp.y:
				onscreen += 1
		print("M onscreen=", onscreen, " vp=", get_viewport().get_visible_rect().size)
		get_tree().quit()
