{"command":"@'
extends Node

var t := 0
var bm = null
var hud = null

func _find_hud(n: Node) -> Node:
	if n is CanvasLayer and n.has_method("_update_health_bars"):
		return n
	for c in n.get_children():
		var r: Node = _find_hud(c)
		if r != null:
			return r
	return null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 150:
		hud = _find_hud(get_tree().root)
	elif t == 152:
		# 制造中后期兵线规模：140 个额外小兵
		for i in 140:
			var m = load("res://scripts/entities/Minion.gd").new()
			m.display_name = "melee" if i % 3 != 0 else "ranged"
			m.team = i % 2
			m.max_health = 320.0
			m.health = 320.0
			bm.add_child(m)
			m.global_position = Vector3(-40.0 + float(i % 20) * 3.0, 0.0, -40.0 + float(i / 20) * 6.0)
	elif t == 170:
		var ents := get_tree().get_nodes_in_group("entities")
		print("S entities=", ents.size(), " unit_bars=", hud.unit_bars.size(), " hud_children=", hud.get_child_count())
		var t0 := Time.get_ticks_usec()
		for k in 120:
			hud._update_health_bars()
		print("S cost_ms_per_frame=", "%.3f" % (float(Time.get_ticks_usec() - t0) / 120.0 / 1000.0))
		# 屏内可见
		var cam = get_viewport().get_camera_3d()
		var vp: Vector2 = get_viewport().get_visible_rect().size
		var onscreen: int = 0
		for e in ents:
			if not is_instance_valid(e): continue
			var sp: Vector2 = cam.unproject_position(e.global_position + Vector3.UP * 1.6)
			if sp.x >= 0 and sp.y >= 0 and sp.x <= vp.x and sp.y <= vp.y:
				onscreen += 1
		print("S onscreen=", onscreen)
		get_tree().quit()
