{"file_path":"scripts/ui/WorldBarPainter.gd","content":"class_name WorldBarPainter
extends Control
## 世界血条合批绘制：由 HUD 每帧填 rows（屏幕坐标/数值已算好），本节点一次性画完。
## 目的：替代原来「每个单位一个 Control + 一个 Label」的做法（170 单位 = 345 节点、数百 draw 项）。

var rows: Array = []          # 本帧可见行（HUD 直接复用 row 字典，不新建）
var _font: Font = null
var _t := 0.0

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	_font = UiKit.font()
	set_process(true)

func _process(delta: float) -> void:
	_t += delta
	if not rows.is_empty():
		queue_redraw()

func _draw() -> void:
	for r in rows:
		if bool(r.get("epic", false)):
			_draw_epic(r)
		else:
			_draw_unit(r)

# ============================ 普通单位 ============================
func _draw_unit(r: Dictionary) -> void:
	var w: float = float(r["w"])
	var h: float = float(r["h"])
	if w <= 0.0 or h <= 0.0:
		return
	var p: Vector2 = r["pos"]
	var hp: float = float(r["hp"])
	var mx: float = maxf(1.0, float(r["max_hp"]))
	var shield: float = float(r.get("shield", 0.0))
	var tc: Color = r["team_color"]
	var top := Rect2(p, Vector2(w, h))

	# 干扰条（塔被干扰时，血条上方灰条）
	var iv: float = float(r.get("interfere", 0.0))
	if iv > 0.0:
		draw_rect(Rect2(p + Vector2(0, -7), Vector2(w, 4)), Color(0, 0, 0, 0.4))
		draw_rect(Rect2(p + Vector2(0, -7), Vector2(w * clampf(iv, 0.0, 1.0), 4)), Color(0.62, 0.62, 0.66))

	# 底色 + 空槽
	draw_rect(top, Color(0, 0, 0, 0.45))

	var hw: float = clampf(hp / mx, 0.0, 1.0) * w
	var sw: float = clampf(shield / mx, 0.0, 1.0) * w
	sw = minf(sw, w - hw)

	# 残血拖尾（白色半透明，滞后追平）
	var lag: float = clampf(float(r.get("lag", hp)) / mx, 0.0, 1.0) * w
	if lag > hw + 0.5:
		draw_rect(Rect2(p + Vector2(hw, 0), Vector2(lag - hw, h)), Color(1.0, 0.93, 0.82, 0.42))

	# 血量（上下分层队伍色）
	draw_rect(Rect2(p, Vector2(hw, h * 0.5)), tc.lightened(0.22))
	draw_rect(Rect2(p + Vector2(0, h * 0.5), Vector2(hw, h * 0.5)), tc.darkened(0.22))

	# 护盾（右侧白段）
	if sw > 0.0:
		draw_rect(Rect2(p + Vector2(hw, 0), Vector2(sw, h)), Color(0.86, 0.88, 0.94, 0.95))

	# 塔：每 2000 血一格刻度
	if bool(r.get("ticks", false)):
		var step := 2000.0 / mx * w
		if step > 4.0:
			var x := step
			while x < w - 0.5:
				draw_line(Vector2(p.x + x, p.y), Vector2(p.x + x, p.y + h), Color(0, 0, 0, 0.55), 1.0)
				x += step

	# 受伤闪橙（贴血量右边界，0.5s 衰减）
	var ft: float = float(r.get("flash_t", 0.0))
	if ft > 0.0:
		var fw: float = minf(float(r.get("flash_amt", 0.0)) / mx * w * (ft / 0.5), w - hw)
		if fw > 0.5:
			draw_rect(Rect2(p + Vector2(hw, 0), Vector2(fw, h)), Color(1.0, 0.62, 0.12, 0.9))

	# 回血深色叠加
	var ht: float = float(r.get("heal_t", 0.0))
	if ht > 0.0:
		var hwd: float = float(r.get("heal_amt", 0.0)) / mx * w
		if hwd > 0.5:
			var hc := Color(tc.r * 0.55, tc.g * 0.55, tc.b * 0.55, ht / 0.5 * 0.9)
			draw_rect(Rect2(p + Vector2(maxf(hw - hwd, 0.0), 0), Vector2(hwd, h)), hc)

	# 李元芳暗印预判：即将被引爆的血量段染黄
	var doom: float = float(r.get("doom", 0.0))
	if doom > 0.0:
		var dw: float = minf(doom / mx * w, hw)
		if dw > 0.5:
			draw_rect(Rect2(p + Vector2(hw - dw, 0), Vector2(dw, h)), Color(1.0, 0.88, 0.18, 0.88))

	# 低血脉冲：血量 <30% 时红边呼吸
	var ratio := hp / mx
	if ratio < 0.3 and hp > 0.0:
		var pulse: float = 0.28 + 0.30 * absf(sin(_t * 6.0))
		draw_rect(top, Color(1.0, 0.25, 0.2, pulse * 0.35))
		draw_rect(top, Color(1.0, 0.42, 0.32, pulse), false, 1.6)

	# 描边（深色 + 队伍色细边）
	draw_rect(top, Color(0.05, 0.06, 0.09, 0.85), false, 1.0)
	draw_rect(top.grow(1.0), Color(tc.r, tc.g, tc.b, 0.35), false, 1.0)

	# 盾形图标（原初羁绊 / 塔无兵线保护）
	if bool(r.get("shield_icon", false)):
		var s: float = minf(h * 0.72, 19.0)
		_draw_shield_icon(p + Vector2(-(s + 9.0), h * 0.5), s, tc)

	# 文本：名称（上） + 血量（贴血条上沿）
	if _font == null:
		return
	if bool(r.get("show_numbers", false)):
		var hp_txt: String = r.get("num_text", "")
		if hp_txt != "":
			var ns := 18
			var tw: float = _font.get_string_size(hp_txt, HORIZONTAL_ALIGNMENT_LEFT, -1, ns).x
			draw_string_outline(_font, p + Vector2((w - tw) * 0.5, -8.0), hp_txt,
				HORIZONTAL_ALIGNMENT_LEFT, -1, ns, 4, Color(0, 0, 0, 0.9))
			draw_string(_font, p + Vector2((w - tw) * 0.5, -8.0), hp_txt,
				HORIZONTAL_ALIGNMENT_LEFT, -1, ns, Color(1, 1, 1, 0.96))
	if bool(r.get("show_name", false)):
		var nm: String = r.get("name_text", "")
		if nm != "":
			var fs := 20
			var tw2: float = _font.get_string_size(nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
			var np := p + Vector2((w - tw2) * 0.5, -30.0)
			draw_string_outline(_font, np, nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, 4, Color(0, 0, 0, 0.9))
			draw_string(_font, np, nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(1, 1, 1, 0.98))
	var mk: String = r.get("markers", "")
	if mk != "":
		var tw3: float = _font.get_string_size(mk, HORIZONTAL_ALIGNMENT_LEFT, -1, 20).x
		draw_string_outline(_font, p + Vector2((w - tw3) * 0.5, h + 22.0), mk,
			HORIZONTAL_ALIGNMENT_LEFT, -1, 20, 4, Color(0, 0, 0, 0.9))
		draw_string(_font, p + Vector2((w - tw3) * 0.5, h + 22.0), mk,
			HORIZONTAL_ALIGNMENT_LEFT, -1, 20, Color.YELLOW)

# ============================ 史诗怪（紫色分格） ============================
func _draw_epic(r: Dictionary) -> void:
	var w: float = float(r["w"])
	var h: float = float(r["h"])
	var p: Vector2 = r["pos"]
	var hp: float = float(r["hp"])
	var mx: float = maxf(1.0, float(r["max_hp"]))
	var shield: float = float(r.get("shield", 0.0))
	var cell := 1000.0
	var seg_count := maxi(1, int(ceil(mx / cell)))
	var seg_total := float(seg_count) * cell
	var seg_w := w / float(seg_count)
	var to_w := w / seg_total
	var fill_w: float = clampf(hp, 0.0, mx) * to_w
	var sh_w: float = clampf(shield, 0.0, seg_total - hp) * to_w

	var margin := 1.5
	var inset_y := 2.5
	var avail_h: float = h - inset_y * 2.0
	var cell_color := Color(0.13, 0.05, 0.24, 0.95)
	var top_col := Color(0.8, 0.45, 1.0)
	var bot_col := Color(0.46, 0.16, 0.82)

	for i in seg_count:
		var x0: float = float(i) * seg_w
		var x1: float = minf(float(i + 1) * seg_w, w)
		if x1 - x0 <= margin * 2.0:
			continue
		var rc := Rect2(p + Vector2(x0 + margin, inset_y), Vector2(x1 - x0 - margin * 2.0, avail_h))
		draw_rect(rc, cell_color)
		var filled: float = clampf(fill_w - (x0 + margin), 0.0, rc.size.x)
		if filled > 0.0:
			draw_rect(Rect2(rc.position, Vector2(filled, avail_h * 0.5)), top_col)
			draw_rect(Rect2(rc.position + Vector2(0, avail_h * 0.5), Vector2(filled, avail_h * 0.5)), bot_col)

	# 残血拖尾（紫条也跟一下）
	var lag: float = clampf(float(r.get("lag", hp)), 0.0, mx) * to_w
	if lag > fill_w + 0.5:
		draw_rect(Rect2(p + Vector2(fill_w, inset_y), Vector2(lag - fill_w, avail_h)),
			Color(1.0, 0.9, 1.0, 0.28))

	if sh_w > 0.0:
		var sh_x: float = clampf(fill_w, 0.0, w)
		var sh_use: float = clampf(sh_w, 0.0, w - sh_x)
		if sh_use > 0.0:
			draw_rect(Rect2(p + Vector2(sh_x, inset_y), Vector2(sh_use, avail_h)), Color(0.9, 0.9, 0.95, 0.95))

	var ft: float = float(r.get("flash_t", 0.0))
	if ft > 0.0:
		var fw: float = float(r.get("flash_amt", 0.0)) * to_w * (ft / 0.5)
		if fw > 0.5:
			draw_rect(Rect2(p + Vector2(fill_w, inset_y), Vector2(minf(fw, w - fill_w), avail_h)),
				Color(1.0, 0.55, 0.1, 0.9))

	var ht: float = float(r.get("heal_t", 0.0))
	if ht > 0.0:
		var hw2: float = float(r.get("heal_amt", 0.0)) * to_w
		if hw2 > 0.5:
			var hcol := Color(top_col.r * 0.55, top_col.g * 0.55, top_col.b * 0.55, ht / 0.5 * 0.6)
			draw_rect(Rect2(p + Vector2(maxf(fill_w - hw2, 0.0), inset_y), Vector2(hw2, avail_h)), hcol)

	var doom: float = float(r.get("doom", 0.0))
	if doom > 0.0:
		var dw: float = doom * to_w
		if dw > 0.5:
			draw_rect(Rect2(p + Vector2(maxf(fill_w - dw, 0.0), inset_y), Vector2(dw, avail_h)),
				Color(1.0, 0.88, 0.18, 0.7))

	draw_rect(Rect2(p, Vector2(w, h)), Color(1.0, 0.9, 1.0, 0.5), false, 1.5)

	if _font != null:
		var nm: String = r.get("name_text", "")
		if bool(r.get("show_name", false)) and nm != "":
			var tw: float = _font.get_string_size(nm, HORIZONTAL_ALIGNMENT_LEFT, -1, 24).x
			var np := p + Vector2((w - tw) * 0.5, -12.0)
			draw_string_outline(_font, np, nm, HORIZONTAL_ALIGNMENT_LEFT, -1, 24, 5, Color(0, 0, 0, 0.9))
			draw_string(_font, np, nm, HORIZONTAL_ALIGNMENT_LEFT, -1, 24, Color(0.93, 0.78, 1.0))
		if bool(r.get("show_numbers", false)):
			var txt: String = r.get("num_text", "")
			if txt != "":
				var tw2: float = _font.get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 20).x
				var np2 := p + Vector2((w - tw2) * 0.5, h + 24.0)
