				draw_string(_font, np2, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 20, Color(1, 1, 1, 0.95))

# ============================ 盾形图标 ============================
func _draw_shield_icon(c: Vector2, s: float, col: Color) -> void:
	var pts := PackedVector2Array([
		c + Vector2(-0.55 * s, -0.85 * s), c + Vector2(0.55 * s, -0.85 * s),
		c + Vector2(0.62 * s, 0.0), c + Vector2(0.3 * s, 0.68 * s),
		c + Vector2(0.0, 1.0 * s), c + Vector2(-0.3 * s, 0.68 * s),
		c + Vector2(-0.62 * s, 0.0),
	])
	draw_colored_polygon(pts, col)
	var outline := pts.duplicate()
	outline.append(pts[0])
	draw_polyline(outline, Color(0.12, 0.03, 0.05, 0.85), 1.5)
	draw_line(c + Vector2(-0.5 * s, -0.05 * s), c + Vector2(0.5 * s, -0.05 * s),
		Color(1, 1, 1, 0.55), maxf(s * 0.16, 1.0))
