func _update_health_bars():
	var entities = get_tree().get_nodes_in_group("entities")
	var cam = get_viewport().get_camera_3d()
	if not cam: return
	var cam_forward: Vector3 = -cam.global_transform.basis.z  # 相机朝向，用于判断锚点是否在相机后方

	var to_remove = []
	for e in unit_bars.keys():
		if not is_instance_valid(e) or e.health <= 0:
			to_remove.append(e)
	for e in to_remove:
		if unit_bars.has(e):
			unit_bars[e].bar.queue_free()
			unit_bars[e].label.queue_free()
			unit_bars.erase(e)

	# 清理英雄信息控件
	to_remove.clear()
	for hero in hero_info_controls.keys():
		if not is_instance_valid(hero) or hero.health <= 0:
			hero_info_controls[hero].queue_free()

for hero in to_remove:
	hero_info_controls.erase(hero)

for entity in entities:
	if not is_instance_valid(entity) or (entity.health <= 0 and ((entity is Hero and not entity.is_reviving )or entity is JungleMonster) ): continue
	if not entity.visible:
		if entity in unit_bars:
			unit_bars[entity].visible = false
		if entity in hero_info_controls:
			hero_info_controls[entity].visible = false
		continue

	if entity is Hero:
		# 英雄：使用 HeroInfoControl
		if entity not in hero_info_controls:
			var info = HeroInfoControl.new()
			info.hero = entity
			info.visible = true
			add_child(info)
			hero_info_controls[entity] = info
		var info = hero_info_controls[entity]
		# 英雄血条被顶部中央战况带遮挡：锚点再整体下移一点（+1.8 → +1.2），避开 band
		var world_pos = entity.global_position + Vector3.UP * (entity.body_radius * 2.0 + 1.2)
		# 锚点在相机后方（含第一人称自身：锚点位于相机正上方，深度≈0）时隐藏，避免 unproject 投影错乱
		if cam_forward.dot(world_pos - cam.global_position) <= 0.3:
			info.visible = false
			continue
		info.visible = true
		var screen_pos = cam.unproject_position(world_pos)
		info.position = screen_pos - info.custom_minimum_size / 2
		# 英雄的血条始终显示（或满血时只显示等级圆环）
		info.queue_redraw()
	else:

