				bar.interfere_value = clampf(turret.interfere_timer / turret.interfere_max, 0.0, 1.0)
			else:
				bar.interfere_value = 0.0
			# 塔下无敌方小兵 → 英雄伤害×0.45（无兵线保护），血条旁点亮盾图标
			bar.show_shield_icon = turret.shield_protected_no_minion
			bar.update_bar(turret.health, turret.max_health, turret.team, turret.tower_shield, false, false)
		else:
			bar.interfere_value = 0.0
			bar.show_shield_icon = false
			if is_epic:
				# 原初羁绊：击杀另一条龙的本方（玩家一队）对这条龙减伤并蓄怒 → 血条前点亮盾图标
				var battle := get_tree().get_first_node_in_group("battle_manager") as BattleManager
				if battle and battle.hero and is_instance_valid(battle.hero):
					bar.show_shield_icon = (battle.get_bonded_team(entity) == battle.hero.team)
