{"content":"extends Node

var t := 0
var bm = null
var hud = null
var m0 = null

func _find_hud(n: Node) -> Node:
	if n is CanvasLayer and n.has_method("_update_health_bars"):
		return n
	for c in n.get_children():
		var r: Node = _find_hud(c)
		if r != null:
			return r
	return null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 150:
		hud = _find_hud(get_tree().root)
	elif t == 152:
		var cam = get_viewport().get_camera_3d()
		var fwd: Vector3 = -cam.global_transform.basis.z
		var right: Vector3 = cam.global_transform.basis.x
		var base: Vector3 = cam.global_position + fwd * 14.0
		for i in 140:
			var m = load("res://scripts/entities/Minion.gd").new()
			m.display_name = "melee" if i % 3 != 0 else "ranged"
			m.team = i % 2
			m.body_radius = 0.5
			m.max_health = 320.0
			m.health = 320.0 if i % 4 != 0 else 120.0
			bm.add_child(m)
			m.add_to_group("entities", true)
			m.add_to_group("minions", true)
			m.global_position = base + right * (float(i % 20) - 10.0) * 1.2 + fwd * float(i / 20) * 1.6
			if i == 0:
				m0 = m
	elif t == 170:
		var ents := get_tree().get_nodes_in_group("entities")
		print("B entities=", ents.size(), " rows=", hud.bars.rows.size(), " bar_nodes=", hud.bars.get_child_count(),
			" hud_children=", hud.get_child_count(), " hero_ctrl=", hud.hero_info_controls.size(),
			" rowcache=", hud._bar_rows.size())
		var t0 := Time.get_ticks_usec()
		for k in 120:
			hud._update_health_bars()
		print("B cost_ms=", "%.3f" % (float(Time.get_ticks_usec() - t0) / 120.0 / 1000.0))
		var small: int = 0
		var with_num: int = 0
		var with_name: int = 0
		var tower_rows: int = 0
		for r in hud.bars.rows:
			var rr: Dictionary = r
			if float(rr["w"]) < 80.0:
				small += 1
			if bool(rr.get("show_numbers", false)):
				with_num += 1
			if bool(rr.get("show_name", false)):
				with_name += 1
			if bool(rr.get("ticks", false)):
				tower_rows += 1
		print("B small=", small, " with_num=", with_num, " with_name=", with_name, " towers=", tower_rows)
		# 低血脉冲 / 拖尾
		hud._update_health_bars()
		var r0: Dictionary = hud._bar_rows.get(m0, {})
		print("B flash_t=", "%.2f" % float(r0.get("flash_t", -1.0)), " flash_amt=", "%.1f" % float(r0.get("flash_amt", -1.0)),
			" lag=", "%.1f" % float(r0.get("lag", -1.0)), " hp=", "%.1f" % float(r0.get("hp", -1.0)),
			" num=", r0.get("num_text", ""), " show_num=", r0.get("show_numbers", false))
		get_tree().quit()
