{"content":"extends Control
## 世界血条合批绘制：由 HUD 每帧填 rows（屏幕坐标/数值已算好），本节点一次性画完。
## 质感：渐变填充 + 顶部高光 + 底部暗边 + 中缝 + 1px 边框/队伍色外框 + 投影 + 残血拖尾 + 低血脉冲；
## 文字：合成粗体 + 阴影 + 描边；名称在上、数值在下，居中。

var rows: Array = []          # 本帧可见行（HUD 直接复用 row 字典，不新建）
var _font: Font = null
var _font_bold: FontVariation = null
var _t := 0.0

# —— 缓存纹理/材质（首次用到才建）——
var _fill_cache: Dictionary = {}    # team key -> GradientTexture2D（血条渐变）
var _lag_tex: ImageTexture = null
var _gloss_tex: ImageTexture = null

const OUTLINE := Color(0, 0, 0, 0.92)
const SHADOW := Color(0, 0, 0, 0.55)
const BAR_BG_TOP := Color(0.11, 0.12, 0.16, 0.96)
const BAR_BG_BOT := Color(0.06, 0.07, 0.10, 0.96)

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	_font = UiKit.font()
	set_process(true)

func _process(delta: float) -> void:
	_t += delta
	if not rows.is_empty():
		queue_redraw()

func _draw() -> void:
	for r in rows:
		if bool(r.get("epic", false)):
			_draw_epic(r)
		else:
			_draw_unit(r)

# ============================ 资源缓存 ============================
func _bold() -> Font:
	if _font_bold == null:
		var fv := FontVariation.new()
		fv.base_font = _font
		fv.variation_embolden = 0.45
		_font_bold = fv
	return _font_bold if _font_bold != null else _font

func _grad(team: int, tc: Color) -> GradientTexture2D:
	if _fill_cache.has(team):
		return _fill_cache[team]
	var g := Gradient.new()
	g.offsets = PackedFloat32Array([0.0, 0.34, 0.62, 1.0])
	g.colors = PackedColorArray([
		tc.lightened(0.45), tc.lightened(0.12), tc.darkened(0.18), tc.darkened(0.42),
	])
	var t := GradientTexture2D.new()
	t.gradient = g
	t.width = 6
	t.height = 32
	t.fill_from = Vector2(0, 0)
	t.fill_to = Vector2(0, 1)
	_fill_cache[team] = t
	return t

func _lag_texture() -> ImageTexture:
	if _lag_tex != null:
		return _lag_tex
	var img := Image.create(4, 32, false, Image.FORMAT_RGBA8)
	for y in 32:
		var q := float(y) / 31.0
		img.set_pixel(0, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
		img.set_pixel(1, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
		img.set_pixel(2, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
		img.set_pixel(3, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
	_lag_tex = ImageTexture.create_from_image(img)
	return _lag_tex

# ============================ 普通单位 ============================
func _draw_unit(r: Dictionary) -> void:
	var w: float = float(r["w"])
	var h: float = float(r["h"])
	if w <= 0.0 or h <= 0.0:
		return
	var p: Vector2 = r["pos"]
	var hp: float = float(r["hp"])
	var mx: float = maxf(1.0, float(r["max_hp"]))
	var shield: float = float(r.get("shield", 0.0))
	var tc: Color = r["team_color"]
	var team: int = int(r.get("team", 0))
	var top := Rect2(p, Vector2(w, h))
	var hw: float = clampf(hp / mx, 0.0, 1.0) * w

	# 投影（两层，软化）
	draw_rect(Rect2(p + Vector2(1.5, 2.5), Vector2(w, h)), Color(0, 0, 0, 0.18))
