		draw_rect(Rect2(ir.position, Vector2(w * clampf(iv, 0.0, 1.0), 2)), Color(1, 1, 1, 0.35))
		draw_rect(ir, Color(0.02, 0.03, 0.05, 0.9), false, 1.0)

