# ============================ 资源缓存 ============================
func _bold() -> Font:
	if _font_bold == null:
		var fv := FontVariation.new()
		fv.base_font = _font
		fv.variation_embolden = 0.45
		_font_bold = fv
	return _font_bold if _font_bold != null else _font

func _grad(team: int, tc: Color) -> GradientTexture2D:
	if _fill_cache.has(team):
		return _fill_cache[team]
	var g := Gradient.new()
	g.offsets = PackedFloat32Array([0.0, 0.34, 0.62, 1.0])
	g.colors = PackedColorArray([
		tc.lightened(0.45), tc.lightened(0.12), tc.darkened(0.18), tc.darkened(0.42),
	])
	var t := GradientTexture2D.new()
	t.gradient = g
	t.width = 6
	t.height = 32
	t.fill_from = Vector2(0, 0)
	t.fill_to = Vector2(0, 1)
	_fill_cache[team] = t
	return t

func _lag_texture() -> ImageTexture:
	if _lag_tex != null:
		return _lag_tex
	var img := Image.create(4, 32, false, Image.FORMAT_RGBA8)
	for y in 32:
		var q := float(y) / 31.0
		img.set_pixel(0, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
		img.set_pixel(1, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
		img.set_pixel(2, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
		img.set_pixel(3, y, Color(1, 1, 1, 0.55 * (1.0 - q) + 0.10))
	_lag_tex = ImageTexture.create_from_image(img)
	return _lag_tex

# ============================ 普通单位 ============================
func _draw_unit(r: Dictionary) -> void:
	var w: float = float(r["w"])

diffs.oldText:
	var mx: float = maxf(1.0, float(r["max_hp"]))
	var shield: float = float(r.get("shield", 0.0))
	var tc: Color = r["team_color"]
	var top := Rect2(p, Vector2(w, h))

	# 干扰条（塔被干扰时，血条上方灰条）
	var iv: float = float(r.get("interfere", 0.0))
	if iv > 0.0:
		draw_rect(Rect2(p + Vector2(0, -7), Vector2(w, 4)), Color(0, 0, 0, 0.4))
		draw_rect(Rect2(p + Vector2(0, -7), Vector2(w * clampf(iv, 0.0, 1.0), 4)), Color(0.62, 0.62, 0.66))

	# 底色 + 空槽
	draw_rect(top, Color(0, 0, 0, 0.45))

	var hw: float = clampf(hp / mx, 0.0, 1.0) * w
	var sw: float = clampf(shield / mx, 0.0, 1.0) * w
	sw = minf(sw, w - hw)

	# 残血拖尾（白色半透明，滞后追平）
	var lag: float = clampf(float(r.get("lag", hp)) / mx, 0.0, 1.0) * w
	if lag > hw + 0.5:
		draw_rect(Rect2(p + Vector2(hw, 0), Vector2(lag - hw, h)), Color(1.0, 0.93, 0.82, 0.42))

	# 血量（上下分层队伍色）
	draw_rect(Rect2(p, Vector2(hw, h * 0.5)), tc.lightened(0.22))
	draw_rect(Rect2(p + Vector2(0, h * 0.5), Vector2(hw, h * 0.5)), tc.darkened(0.22))

	# 护盾（右侧白段）
	if sw > 0.0:
		draw_rect(Rect2(p + Vector2(hw, 0), Vector2(sw, h)), Color(0.86, 0.88, 0.94, 0.95))

	# 塔：每 2000 血一格刻度
	if bool(r.get("ticks", false)):
		var step := 2000.0 / mx * w
		if step > 4.0:
			var x := step
			while x < w - 0.5:
				draw_line(Vector2(p.x + x, p.y), Vector2(p.x + x, p.y + h), Color(0, 0, 0, 0.55), 1.0)
				x += step

	# 受伤闪橙（贴血量右边界，0.5s 衰减）
	var ft: float = float(r.get("flash_t", 0.0))
	if ft > 0.0:
		var fw: float = minf(float(r.get("flash_amt", 0.0)) / mx * w * (ft / 0.5), w - hw)
		if fw > 0.5:
			draw_rect(Rect2(p + Vector2(hw, 0), Vector2(fw, h)), Color(1.0, 0.62, 0.12, 0.9))

	# 回血深色叠加
	var ht: float = float(r.get("heal_t", 0.0))
	if ht > 0.0:
		var hwd: float = float(r.get("heal_amt", 0.0)) / mx * w
		if hwd > 0.5:
			var hc := Color(tc.r * 0.55, tc.g * 0.55, tc.b * 0.55, ht / 0.5 * 0.9)
			draw_rect(Rect2(p + Vector2(maxf(hw - hwd, 0.0), 0), Vector2(hwd, h)), hc)

	# 李元芳暗印预判：即将被引爆的血量段染黄
	var doom: float = float(r.get("doom", 0.0))
	if doom > 0.0:
		var dw: float = minf(doom / mx * w, hw)
		if dw > 0.5:
			draw_rect(Rect2(p + Vector2(hw - dw, 0), Vector2(dw, h)), Color(1.0, 0.88, 0.18, 0.88))

	# 低血脉冲：血量 <30% 时红边呼吸
	var ratio := hp / mx
	if ratio < 0.3 and hp > 0.0:
		var pulse: float = 0.28 + 0.30 * absf(sin(_t * 6.0))
		draw_rect(top, Color(1.0, 0.25, 0.2, pulse * 0.35))
		draw_rect(top, Color(1.0, 0.42, 0.32, pulse), false, 1.6)

	# 描边（深色 + 队伍色细边）
	draw_rect(top, Color(0.05, 0.06, 0.09, 0.85), false, 1.0)
	draw_rect(top.grow(1.0), Color(tc.r, tc.g, tc.b, 0.35), false, 1.0)

	# 盾形图标（原初羁绊 / 塔无兵线保护）
	if bool(r.get("shield_icon", false)):
		var s: float = minf(h * 0.72, 19.0)
		_draw_shield_icon(p + Vector2(-(s + 9.0), h * 0.5), s, tc)

	# 文本：名称（上） + 血量（贴血条上沿）
	if _font == null:
		return
	if bool(r.get("show_numbers", false)):
		var hp_txt: String = r.get("num_text", "")
		if hp_txt != "":
			var ns := 18
			var tw: float = _font.get_string_size(hp_txt, HORIZONTAL_ALIGNMENT_LEFT, -1, ns).x
			draw_string_outline(_font, p + Vector2((w - tw) * 0.5, -8.0), hp_txt,
				HORIZONTAL_ALIGNMENT_LEFT, -1, ns, 4, Color(0, 0, 0, 0.9))
			draw_string(_font, p + Vector2((w - tw) * 0.5, -8.0), hp_txt,
				HORIZONTAL_ALIGNMENT_LEFT, -1, ns, Color(1, 1, 1, 0.96))
	if bool(r.get("show_name", false)):
		var nm: String = r.get("name_text", "")
		if nm != "":
			var fs := 20
			var tw2: float = _font.get_string_size(nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
			var np := p + Vector2((w - tw2) * 0.5, -30.0)
			draw_string_outline(_font, np, nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, 4, Color(0, 0, 0, 0.9))
			draw_string(_font, np, nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs, Color(1, 1, 1, 0.98))
	var mk: String = r.get("markers", "")
	if mk != "":
		var tw3: float = _font.get_string_size(mk, HORIZONTAL_ALIGNMENT_LEFT, -1, 20).x
		draw_string_outline(_font, p + Vector2((w - tw3) * 0.5, h + 22.0), mk,
			HORIZONTAL_ALIGNMENT_LEFT, -1, 20, 4, Color(0, 0, 0, 0.9))
		draw_string(_font, p + Vector2((w - tw3) * 0.5, h + 22.0), mk,
			HORIZONTAL_ALIGNMENT_LEFT, -1, 20, Color.YELLOW)

