@'
extends Node

var t := 0
var bm = null
var hud = null

func _find_hud(n: Node) -> Node:
	if n is CanvasLayer and n.has_method("_update_health_bars"):
		return n
	for c in n.get_children():
		var r: Node = _find_hud(c)
		if r != null:
			return r
	return null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 150:
		hud = _find_hud(get_tree().root)
		print("Q hud=", hud != null)
	elif t == 152:
		var cam = get_viewport().get_camera_3d()
		var fwd: Vector3 = -cam.global_transform.basis.z
		var right: Vector3 = cam.global_transform.basis.x
		var base: Vector3 = cam.global_position + fwd * 14.0
		for i in 90:
			var m = load("res://scripts/entities/Minion.gd").new()
			m.display_name = "melee" if i % 3 != 0 else "ranged"
			m.team = i % 2
			m.body_radius = 0.5
			m.max_health = 320.0
			m.health = 320.0 if i % 5 != 0 else 90.0
			bm.add_child(m)
			m.add_to_group("entities", true)
			m.add_to_group("minions", true)
			m.global_position = base + right * (float(i % 10) - 4.5) * 1.6 + fwd * float(i / 10) * 2.2
	elif t == 170:
		print("Q rows=", hud.bars.rows.size(), " children=", hud.get_child_count(), " hero_ctrl=", hud.hero_info_controls.size())
		var t0 := Time.get_ticks_usec()
		for k in 120:
			hud._update_health_bars()
		print("Q cost_ms=", "%.3f" % (float(Time.get_ticks_usec() - t0) / 120.0 / 1000.0))
		await get_tree().process_frame
		await get_tree().process_frame
		var img: Image = get_viewport().get_texture().get_image()
		var cyan: int = 0
		var white: int = 0
		var orange: int = 0
		var red: int = 0
		if img != null:
			for y in range(0, img.get_height(), 3):
				for x in range(0, img.get_width(), 3):
					var c: Color = img.get_pixel(x, y)
					if c.b > 0.65 and c.g > 0.5 and c.r < 0.4:
						cyan += 1
					elif c.r > 0.85 and c.g > 0.85 and c.b > 0.85:
						white += 1
					elif c.r > 0.8 and c.g > 0.45 and c.g < 0.75 and c.b < 0.35:
						orange += 1
					elif c.r > 0.7 and c.g < 0.45 and c.b < 0.45:
						red += 1
		print("Q draw_calls=", int(Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME)),
			" cyan=", cyan, " white=", white, " orange=", orange, " red=", red)
		get_tree().quit()
