content.arguments:
{"command":"$p = (Resolve-Path 'scripts\ui\UI_Manager.gd')
$lines = [System.IO.File]::ReadAllLines($p)
$marker = 'z 分带：常驻 HUD 永远在功能面板之下'
$out = New-Object System.Collections.Generic.List[string]
$i = 0; $legitSeen = $false; $fixedBogus = 0; $fixedLegit = 0
while ($i -lt $lines.Count) {
	$ln = $lines[$i]
	$idx = $ln.IndexOf($marker)
	if ($idx -ge 0) {
		$indent = $ln.Substring(0, $idx)
		$blockLen = 13
		$after = $lines[$i + $blockLen]
		if ($after -eq 'func _ready():') {
			if (-not $legitSeen) {
				$legitSeen = $true
				for ($k = 0; $k -lt $blockLen; $k++) { $out.Add($lines[$i + $k]) }
				$out.Add($indent + 'func _ready():')
				$fixedLegit++
				$i += $blockLen + 1
				continue
			}
			$out.Add($indent + 'func _ready():')
			$fixedBogus++
			$i += $blockLen + 1
			continue
		}
	}
	$out.Add($ln)
	$i++
}
[System.IO.File]::WriteAllLines($p, $out)
"legit=$fixedLegit bogus_removed=$fixedBogus lines=$($out.Count)"
Select-String -Path scripts\ui\UI_Manager.gd -Pattern 'func _apply_layer_bands|func _ready\(\):' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Repair band insertions with correct block length"}

