{"command":"New-Item -ItemType Directory -Force devfx21 | Out-Null
@'
extends Node

var t := 0

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 30:
		for c in get_tree().root.get_children():
			if c is CanvasLayer:
				print("L root: ", c.name, " layer=", int(c.layer))
		for n in ["UiManager", "PostFX", "LoadingScreen"]:
			var x = get_tree().root.get_node_or_null(n)
			if x != null and x is CanvasLayer:
				print("L autoload: ", n, " layer=", int(x.layer))
	elif t == 40:
		var ui = get_tree().root.get_node_or_null("UiManager")
		if ui == null:
			print("L no uimanager")
			get_tree().quit()
			return
		print("L UiManager layer=", int(ui.layer), " children=", ui.get_child_count())
		print("L z dim=", ui.death_overlay.z_index if ui.death_overlay else -999,
			" hero_dim=", ui.hero_detail_dim.z_index if ui.hero_detail_dim else -999,
			" panel=", ui.hero_detail_panel.z_index if ui.hero_detail_panel else -999,
			" attr=", ui.attribute_panel.z_index if ui.attribute_panel else -999,
			" decide=", ui.team_decision_panel.z_index if ui.team_decision_panel else -999,
			" recap=", ui.death_recap_panel.z_index if ui.death_recap_panel else -999,
			" bufftip=", ui.buff_info_panel.z_index if ui.buff_info_panel else -999,
			" target=", ui.target_detail_panel.z_index if ui.target_detail_panel else -999)
		var bad: int = 0
		for k in ui.buff_icon_nodes.keys():
			var n = ui.buff_icon_nodes[k]
			if is_instance_valid(n) and int(n.z_index) > int(ui.death_recap_panel.z_index):
				bad += 1
		print("L buff_nodes=", ui.buff_icon_nodes.size(), " buff_above_recap=", bad)
		get_tree().quit()
