{"command":"@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		var ui = get_tree().root.get_node_or_null("UiManager")
		ui._apply_buff_cfg({"key": "probe_buff", "glyph": "测", "tint": Color(1, 0.6, 0.2),
			"name": "测试", "desc": "测试", "remaining": 3.0, "total": 3.0, "steady": false, "sub": ""}, {})
		get_tree().process_frame.connect(func(): pass, CONNECT_ONE_SHOT)
	elif t == 62:
		var ui = get_tree().root.get_node_or_null("UiManager")
		var bn = ui.buff_icon_nodes.get("probe_buff")
		ui.show_damage_number(Vector3.ZERO, 123.0, false, false)
		ui.show_kill_feed("A", 0, "击杀", "B", 1)
		print("L buff_z=", int(bn.z_index) if bn != null else -999,
			" recap_z=", int(ui.death_recap_panel.z_index),
			" hud_layer=", int(ui.layer))
		var popup_ok: int = 0
		for c in ui.get_children():
			if c is Label and c.text == "123":
				popup_ok = 1
				print("L popup_z=", int(c.z_index), " popup_visible=", c.visible)
		print("L popup_found=", popup_ok)
		var hud = get_tree().root.find_child("UI", true, false)
		print("L world_hud_layer=", int(hud.layer) if hud is CanvasLayer else -1)
		# 死亡回放：真显示一次，确认在 buff 图标之上
		var hero = bm.hero
		if hero:
			ui.show_death_recap(hero, bm)
			print("L recap_visible=", ui.death_recap_panel.visible, " recap_z=", int(ui.death_recap_panel.z_index))
		elif true:
			ui.death_recap_panel.visible = true
			print("L recap_visible(forced)=", ui.death_recap_panel.visible)
		get_tree().quit()
