@'
extends Node

var t := 0
var bm = null
var hud = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _find_hud(n: Node):
	for c in n.get_children():
		if c is CanvasLayer and c.has_method("_update_health_bars"):
			return c
		var r = _find_hud(c)
		if r != null:
			return r
	return null

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		hud = _find_hud(get_tree().root)
		var rows: int = hud._bar_rows.size()
		var num_on: int = 0
		for k in hud._bar_rows.keys():
			if bool(hud._bar_rows[k].get("show_numbers", false)):
				num_on += 1
		print("L rows=", rows, " show_numbers_true=", num_on)
	elif t == 62:
		var ctrl = null
		for c in hud.get_children():
			if c is Control and c.get_script() != null and "HeroInfoControl" in str(c.get_script().resource_path):
				ctrl = c
				break
		if ctrl == null:
			print("L no hero ctrl")
			get_tree().quit()
			return
		var gp: Vector2 = ctrl.global_position
		var img: Image = get_viewport().get_texture().get_image()
		var cx: int = int(gp.x + ctrl.size.x * 0.5)
		var seen: Array = []
		for y in range(int(gp.y), int(gp.y + 340)):
			if y < 0 or y >= img.get_height() or cx < 0 or cx >= img.get_width():
				continue
			var c2: Color = img.get_pixel(cx, y)
			var mx: float = maxf(c2.r, maxf(c2.g, c2.b))
			var mn: float = minf(c2.r, minf(c2.g, c2.b))
			if mx > 0.12 and (mx - mn) > 0.16:
				seen.append([y, c2])
		if seen.size() >= 6:
			var y0: int = seen[0][0]
			var y1: int = seen[seen.size() - 1][0]
			print("L hbar span=", y1 - y0, " top=", seen[0][1], " mid=", seen[seen.size() / 2][1], " bot=", seen[seen.size() - 1][1])
		else:
			print("L hbar pixels=", seen.size())
		get_tree().quit()
