$old = @'
	# ---- 状态文字（显示在最上方） ----
	var marker_texts = []
	var sources = hero.get_marker_sources()
	for source in sources:
		marker_texts.append("%s\n%d层" % [source.display_name, hero.count_markers(source)])
	# 李元芳暗印层数（同马可波罗的层数样式）
	for lm in hero.lyf_mark_summary():
		var lsrc = lm["source"]
		var _suff := ("%d层" % int(lm["stacks"])) if int(lm["stacks"]) > 0 else ""
		marker_texts.append("%s\n暗印%s" % [lsrc.display_name, _suff])
	var marker_str = " ".join(marker_texts)
	if marker_str != "":
		var marker_size = 22
		var text_width = len(marker_str) * 16  # 近似宽度
		_draw_text_shadow(_bold(), Vector2(center_x - text_width/2, y_offset), marker_str,
					HORIZONTAL_ALIGNMENT_LEFT, -1, marker_size, Color.YELLOW, 4)
		y_offset += 16
'@
$new = @'
	# ---- 标记图标（血条上方：每种标记一个专属图标，右上角数字=层数） ----
	var mk_entries: Array = []
	for source in hero.get_marker_sources():
		mk_entries.append({"name": str(source.display_name), "count": hero.count_markers(source), "type": ""})
	for lm in hero.lyf_mark_summary():
		var lsrc = lm["source"]
		if lsrc == null or not is_instance_valid(lsrc):
			continue
		mk_entries.append({"name": str(lsrc.display_name), "count": int(lm["stacks"]), "type": "lyf"})
	if not mk_entries.is_empty():
		y_offset = MarkerIconScript.draw_row(self, center_x, y_offset, mk_entries, 18.0)
'@
$o = $old.Replace("`r`n","`n"); $n = $new.Replace("`r`n","`n")
if ($t.Contains($o)) { $t = $t.Replace($o, $n); 'hero markers replaced' } else { 'MISS hero markers' }
[System.IO.File]::WriteAllText($p, $t)","description":"Switch hero marker labels to icons"}

