{"command":"$p = (Resolve-Path 'scripts\ui\HeroInfoControl.gd')
$lines = New-Object System.Collections.Generic.List[string]
[System.IO.File]::ReadAllLines($p) | ForEach-Object { $lines.Add($_) }
$idx = -1
for ($i = 1; $i -lt $lines.Count; $i++) {
	if ($lines[$i] -like '*MarkerIconScript = preload*' -and $lines[$i - 1] -like '*MarkerIconScript = preload*') { $idx = $i; break }
}
if ($idx -ge 0) { $lines.RemoveAt($idx); 'dup removed' }
[System.IO.File]::WriteAllLines($p, $lines)
Select-String -Path scripts\ui\HeroInfoControl.gd -Pattern 'MarkerIconScript = preload' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }
"=== patch painter ==="
$q = (Resolve-Path 'scripts\ui\WorldBarPainter.gd'); $t = [System.IO.File]::ReadAllText($q)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$t = $t.Replace('const OUTLINE := Color(0, 0, 0, 0.92)', 'const MarkerIconScript = preload("res://scripts/ui/MarkerIcon.gd")' + $eol + 'const OUTLINE := Color(0, 0, 0, 0.92)')
$old = '	var mk: String = str(r.get("markers", ""))' + $eol + '	if mk != "":' + $eol + '		_text_center(mk, p + Vector2(0, h + 40.0), w, 19, Color(1.0, 0.88, 0.25))'
$new = '	# 标记图标（血条上方一行，专属图标 + 右上角层数）' + $eol + '	var mlist: Array = r.get("marker_list", [])' + $eol + '	if not mlist.is_empty():' + $eol + '		MarkerIconScript.draw_row(self, p.x + w * 0.5, p.y - 34.0, mlist, 11.0)'
if ($t.Contains($old)) { $t = $t.Replace($old, $new); 'painter ok' } else { 'painter MISS' }
[System.IO.File]::WriteAllText($q, $t)
Select-String -Path scripts\ui\WorldBarPainter.gd -Pattern 'MarkerIconScript|marker_list' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Dedupe const and patch painter marker icons"}

