@'
extends Node

var t := 0
var bm = null
var hud = null
var hero = null

func _find_hud(n: Node):
	for c in n.get_children():
		if c is CanvasLayer and c.has_method("_update_health_bars"):
			return c
		var r = _find_hud(c)
		if r != null:
			return r
	return null

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("甄姬", "flash")
	elif t == 50:
		hero = bm.hero
		var enemy = null
		var monster = null
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Hero and e.team != hero.team and enemy == null:
				enemy = e
			if e is JungleMonster and monster == null:
				monster = e
		if enemy:
			for i in 3:
				enemy.markers.append({"timer": 5.0, "source": hero})
			enemy.lyf_marks[hero] = {"stacks": 2, "timer": 4.0}
			print("L enemy markers=", enemy.markers.size(), " lyf=", enemy.lyf_mark_summary().size())
		if monster:
			for i in 4:
				monster.markers.append({"timer": 5.0, "source": hero})
			monster.markers.append({"timer": 3.0, "source": enemy, "type": "sunshangxiang_w"})
			print("L monster markers=", monster.markers.size())
	elif t == 58:
		hud = _find_hud(get_tree().root)
		var shown: int = 0
		var sample = null
		for k in hud._bar_rows.keys():
			var row = hud._bar_rows[k]
			if row["marker_list"].size() > 0:
				shown += 1
				if sample == null:
					sample = row
		print("L rows_with_icons=", shown)
		if sample != null:
			print("L sample entries=", sample["marker_list"], " pos=", sample["pos"], " wh=", sample["w"], "/", sample["h"])
			var img: Image = get_viewport().get_texture().get_image()
			var cx: int = int(sample["pos"].x + sample["w"] * 0.5)
			var y0: int = int(sample["pos"].y - 34.0)
			var lit: int = 0
			for y in range(y0, y0 + 26):
				for x in range(cx - 40, cx + 40):
					if x < 0 or y < 0 or x >= img.get_width() or y >= img.get_height():
						continue
					var c2: Color = img.get_pixel(x, y)
					var mx: float = maxf(c2.r, maxf(c2.g, c2.b))
					var mn: float = minf(c2.r, minf(c2.g, c2.b))
					if mx > 0.18 and (mx - mn) > 0.10:
						lit += 1
			print("L icon_region_lit_px=", lit)
		get_tree().quit()
