{"command":"@'
extends Node

var t := 0
var bm = null
var hud = null
var hero = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _find_hud(n: Node):
	for c in n.get_children():
		if c is CanvasLayer and c.has_method("_update_health_bars"):
			return c
		var r = _find_hud(c)
		if r != null:
			return r
	return null

func _lit(img: Image, x0: int, y0: int, x1: int, y1: int) -> int:
	var n: int = 0
	for y in range(maxi(0, y0), mini(y1, img.get_height())):
		for x in range(maxi(0, x0), mini(x1, img.get_width())):
			var c: Color = img.get_pixel(x, y)
			var mx: float = maxf(c.r, maxf(c.g, c.b))
			var mn: float = minf(c.r, minf(c.g, c.b))
			if mx > 0.22 and (mx - mn) > 0.22:
				n += 1
	return n

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("甄姬", "flash")
	elif t == 50:
		hero = bm.hero
		var enemy = null
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Hero and e.team != hero.team:
				enemy = e
				break
		for i in 3:
			enemy.markers.append({"timer": 9.0, "source": hero})
		enemy.lyf_marks[hero] = {"stacks": 2, "timer": 8.0}
		var mon = bm.jungle_monsters[0] if bm.jungle_monsters.size() > 0 else null
		if mon != null:
			for i in 4:
				mon.markers.append({"timer": 9.0, "source": hero})
			mon.markers.append({"timer": 9.0, "source": enemy, "type": "sunshangxiang_w"})
			mon.global_position = hero.global_position + Vector3(0, 0, -6)
			print("L monster markers=", mon.markers.size())
		print("L enemy markers=", enemy.markers.size(), " lyf=", enemy.lyf_mark_summary().size())
	elif t == 58:
		hud = _find_hud(get_tree().root)
		var shown: int = 0
		var sample = null
		for k in hud._bar_rows.keys():
			var row = hud._bar_rows[k]
			if row["marker_list"].size() > 0:
				shown += 1
				if sample == null:
					sample = row
		print("L rows_with_icons=", shown)
		var img: Image = get_viewport().get_texture().get_image()
		if sample != null:
			print("L sample=", sample["marker_list"])
			var cx: int = int(sample["pos"].x + sample["w"] * 0.5)
			var y0: int = int(sample["pos"].y - 36.0)
			print("L unit_icon_lit=", _lit(img, cx - 46, y0, cx + 46, y0 + 26))
		# 英雄：对比有标记/无标记两个英雄控件顶部的饱和像素
		var lit_marked: int = 0
		var lit_plain: int = 0
		for c in hud.get_children():
			if c is Control and c.get_script() != null and "HeroInfoControl" in str(c.get_script().resource_path):
				var gp: Vector2 = c.global_position
				var sw: int = int(c.size.x)
				var cnt: int = _lit(img, int(gp.x), int(gp.y), int(gp.x + sw), int(gp.y + 60))
				if c.hero != null and c.hero.markers.size() > 0:
					lit_marked = cnt
				elif c.hero != null and c.hero.markers.size() == 0:
					lit_plain = cnt
		print("L hero_icon_area marked=", lit_marked, " plain=", lit_plain)
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx22\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx22/probe.tscn','--audio-driver','Dummy','--position','2000,2000','--quit-after','600' -PassThru -RedirectStandardOutput 'devfx22\p.out' -RedirectStandardError 'devfx22\p.err'
$d = $a.WaitForExit(300000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx22\p.out -ErrorAction SilentlyContinue | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx22\p.err -ErrorAction SilentlyContinue | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 8 | ForEach-Object { $_.Line.Trim() }","description":"Verify unit and hero marker icons","timeoutMs":400000}

