{"command":"New-Item -ItemType Directory -Force devfx23, .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

const MI = preload("res://scripts/ui/MarkerIcon.gd")
var t := 0

class TestDraw extends Control:
	const MI = preload("res://scripts/ui/MarkerIcon.gd")
	var entries: Array = []

	func _draw() -> void:
		MI.draw_row(self, 300.0, 40.0, entries, 18.0)

func _ready() -> void:
	var cl := CanvasLayer.new()
	cl.layer = 200
	add_child(cl)
	var d := TestDraw.new()
	d.position = Vector2.ZERO
	d.size = Vector2(600, 140)
	d.entries = [
		{"name": "甄姬", "count": 2, "type": ""},
		{"name": "马可波罗", "count": 3, "type": ""},
		{"name": "孙尚香", "count": 4, "type": ""},
		{"name": "李元芳", "count": 1, "type": "lyf"},
		{"name": "吕布", "count": 2, "type": ""},
		{"name": "杨玉环", "count": 5, "type": ""},
	]
	d.queue_redraw()
	cl.add_child(d)

func _process(_d: float) -> void:
	t += 1
	if t == 6:
		var img: Image = get_viewport().get_texture().get_image()
		# 6 个图标：步长 43（r=18 → 2r+GAP=43），中心 x=300 起始
		var out := []
		for i in range(6):
			var cx: int = int(300.0 - (6 * 43.0 - 7.0) * 0.5 + 18.0 + float(i) * 43.0)
			var lit: int = 0
			var quads := [0, 0, 0, 0]
			for y in range(40, 40 + 42):
				for x in range(cx - 21, cx + 21):
					if x < 0 or y < 0 or x >= img.get_width() or y >= img.get_height():
						continue
					var c: Color = img.get_pixel(x, y)
					var mx: float = maxf(c.r, maxf(c.g, c.b))
					var mn: float = minf(c.r, minf(c.g, c.b))
					if mx > 0.20 and (mx - mn) > 0.16:
						lit += 1
						var qi: int = (0 if x < cx else 1) + (0 if y < 61 else 2)
						quads[qi] += 1
			out.append([lit, quads])
		print("L shapes=", out)
		print("L distinct=", out[0][1] != out[1][1] and out[1][1] != out[2][1] and out[2][1] != out[3][1])
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx23\probe.gd
@'
[gd_scene load_steps=2 format=3]
[ext_resource type="Script" path="res://devfx23/probe.gd" id="1"]
[node name="Probe" type="Node"]
script = ExtResource("1")
'@ | Set-Content -Encoding UTF8 devfx23\probe.tscn
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx23/probe.tscn','--audio-driver','Dummy','--position','2000,2000','--quit-after','300' -PassThru -RedirectStandardOutput 'devfx23\p.out' -RedirectStandardError 'devfx23\p.err'
$d = $a.WaitForExit(180000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx23\p.out -ErrorAction SilentlyContinue | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx23\p.err -ErrorAction SilentlyContinue | Select-String -Pattern 'SCRIPT ERROR|Parse Error' -Context 0,2 | Select-Object -First 10 | ForEach-Object { $_.Line.Trim() }","description":"Verify distinct icon shapes render","timeoutMs":300000}

