{"command":"New-Item -ItemType Directory -Force devfx24, .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _find(n: Node, nm: String):
	if n.name == nm:
		return n
	for c in n.get_children():
		var r = _find(c, nm)
		if r != null:
			return r
	return null

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		var done := 0
		for e in get_tree().get_nodes_in_group("entities"):
			if not (e is Hero) or done > 2:
				continue
			var mdl = _find(e, "HeroModel")
			if mdl == null:
				continue
			done += 1
			var skel = _find(mdl, "Skeleton3D")
			var bones := []
			if skel != null:
				for i in range(min(40, skel.get_bone_count())):
					var bn: String = skel.get_bone_name(i)
					if "hand" in bn.to_lower() or "arm" in bn.to_lower() or "weapon" in bn.to_lower() and bones.size() < 8:
						bones.append(bn)
			print("L ", e.display_name, " skel=", skel != null, " bones=", skel.get_bone_count() if skel else 0, " hand_bones=", bones)
		get_tree().quit()
