content.arguments:
{"command":"$p = (Resolve-Path 'scripts\core\HeroWeapons.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = @'
	var holder := Node3D.new()
	holder.name = "Weapon"
	var node := _build(str(rp["t"]), rp["a"], rp["b"], s * float(rp["l"]))
	holder.add_child(node)
	parent.add_child(holder)
	# 握持位置：右手、腰胸之间；不同武器朝向略作区分
	holder.position = Vector3(aabb.size.x * 0.34, aabb.position.y + h * 0.58, aabb.size.z * 0.10)
	holder.rotation_degrees = _hold_rot(str(rp["t"]))
'@
$new = @'
	var holder := Node3D.new()
	holder.name = "Weapon"
	var node := _build(str(rp["t"]), rp["a"], rp["b"], s * float(rp["l"]))
	holder.add_child(node)
	# 握持位置：右手侧、腰胸之间（相对英雄根节点；不同武器朝向略作区分）
	var grip := Vector3(aabb.size.x * 0.34, aabb.position.y + h * 0.58, aabb.size.z * 0.10)
	var hp: Node3D = parent
	if hp == instance:
		# 模型还没挂进场景（联机端先造模型后归位）：挂在模型下并抵消模型放大
		var inv: float = 1.0 / maxf(maxf(instance.scale.x, instance.scale.y), 0.001)
		holder.scale = Vector3.ONE * inv
		hp.add_child(holder)
		holder.position = grip * inv
	else:
		hp.add_child(holder)
		holder.position = grip
	holder.rotation_degrees = _hold_rot(str(rp["t"]))
'@
$o = $old.Replace("`r`n","`n"); $n = $new.Replace("`r`n","`n")
if ($t.Contains($o)) { $t = $t.Replace($o, $n); 'attach patched' } else { 'attach MISS' }
[System.IO.File]::WriteAllText($p, $t)
# 挂到主机 Hero 模型
$h = (Resolve-Path 'scripts\entities\Hero.gd'); $ht = [System.IO.File]::ReadAllText($h)
$he = if ($ht.Contains("`r`n")) { "`r`n" } else { "`n" }
$anchor = '	root.add_child(instance)' + $he + '	# 查找动画播放器'
$rep = '	root.add_child(instance)' + $he + '	# 专属武器（程序化建模，按英雄名区分造型）' + $he + '	HeroWeapons.attach(instance, display_name)' + $he + '	# 查找动画播放器'
if ($ht.Contains($anchor)) { $ht = $ht.Replace($anchor, $rep); [System.IO.File]::WriteAllText($h, $ht); 'hero hooked' } else { 'hero MISS' }
# 挂到联机客户端模型
$n2 = (Resolve-Path 'scripts\net\NetModels.gd'); $nt = [System.IO.File]::ReadAllText($n2)
$ne = if ($nt.Contains("`r`n")) { "`r`n" } else { "`n" }
$anchor2 = '	var inst = _spawn(path, Vector3.ONE * HERO_SCALE)' + $ne + '	return inst'
$rep2 = '	var inst = _spawn(path, Vector3.ONE * HERO_SCALE)' + $ne + '	# 与主机同源：英雄专属武器' + $ne + '	HeroWeapons.attach(inst, name)' + $ne + '	return inst'
if ($nt.Contains($anchor2)) { $nt = $nt.Replace($anchor2, $rep2); [System.IO.File]::WriteAllText($n2, $nt); 'net hooked' } else { 'net MISS' }","description":"Hook weapons into host and net hero models"}

