L352: func _start_game_body(hero_type: String, summoner_id: String = "flash"):
=== probe tail ===
func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 70:
		var names := []
		for e in get_tree().get_nodes_in_group("entities"):
			if not (e is Hero):
				continue
			var w = _find(e, "Weapon")
			if w == null:
				names.append([e.display_name, "NO_WEAPON"])
				continue
			var box: AABB = _mesh_aabb(w)
			var c: Vector3 = box.get_center()
			var rel: Vector3 = c - e.global_position
			var meshes: int = 0
			for n in w.find_children("*", "MeshInstance3D", true, false):
				meshes += 1
			names.append([e.display_name, meshes, "dy=%.2f dxz=%.2f size=%.2f" % [rel.y, Vector2(rel.x, rel.z).length(), maxf(box.size.x, maxf(box.size.y, box.size.z))]])
		print("L heroes=", names.size())
		for row in names:
			print("L W ", row)
		get_tree().quit()

