{"command":"$p = (Resolve-Path 'scripts\core\HeroWeapons.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = @'
static func _world_aabb(root: Node3D) -> AABB:
	var out := AABB()
	var has := false
	var stack: Array = [root]
	while stack.size() > 0:
		var n: Node3D = stack.pop_back()
		if n is MeshInstance3D and n.mesh != null:
			var box: AABB = n.global_transform * n.get_aabb()
			out = box if not has else out.merge(box)
			has = true
		for c in n.get_children():
			if c is Node3D:
				stack.append(c)
	if not has:
		return AABB(Vector3(-0.4, 0.0, -0.4), Vector3(0.8, 1.8, 0.8))
	return AABB(out.position - root.global_position, out.size)
'@
$new = @'
static func _world_aabb(root: Node3D) -> AABB:
	# 逐级累乘相对变换（模型构建时可能还没进场景树，不能用 global_transform）
	var out := AABB()
	var has := false
	var stack: Array = [[root, Transform3D.IDENTITY]]
	while stack.size() > 0:
		var pair: Array = stack.pop_back()
		var n: Node3D = pair[0]
		var xf: Transform3D = pair[1]
		if n is MeshInstance3D and n.mesh != null:
			var box: AABB = xf * n.get_aabb()
			out = box if not has else out.merge(box)
			has = true
		for c in n.get_children():
			if c is Node3D:
				stack.append([c, xf * (c as Node3D).transform])
	if not has:
		return AABB(Vector3(-0.4, 0.0, -0.4), Vector3(0.8, 1.8, 0.8))
	return out
'@
$o = $old.Replace("`r`n","`n"); $n = $new.Replace("`r`n","`n")
if ($t.Contains($o)) { $t = $t.Replace($o, $n); 'aabb patched' } else { 'aabb MISS' }
[System.IO.File]::WriteAllText($p, $t)
