content.arguments:
{"command":"$p = (Resolve-Path 'scripts\entities\Hero.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = '	_move_lock_until = now_s + 0.5' + $eol + '	_aa_anim_until = now_s + 0.5'
$new = '	_move_lock_until = now_s + 0.5' + $eol + '	_aa_anim_until = now_s + 0.5' + $eol + '	HeroWeapons.play(visual_mesh, "attack")   # 武器普攻动作'
if ($t.Contains($old)) { $t = $t.Replace($old, $new); 'attack hook ok' } else { 'attack hook MISS' }
$old2 = '	if not casting_skill: return' + $eol + '	casting_skill = false'
$new2 = '	if not casting_skill: return' + $eol + '	casting_skill = false' + $eol + '	HeroWeapons.play(visual_mesh, "cast")   # 武器施法动作'
if ($t.Contains($old2)) { $t = $t.Replace($old2, $new2); 'cast hook ok' } else { 'cast hook MISS' }
[System.IO.File]::WriteAllText($p, $t)
Select-String -Path scripts\entities\Hero.gd -Pattern 'HeroWeapons.play' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Hook weapon actions into attack and cast"}

