{"command":"New-Item -ItemType Directory -Force devfx26, .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

var t := 0
var bm = null
var hero = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _find(n: Node, nm: String):
	if n.name == nm:
		return n
	for c in n.get_children():
		var r = _find(c, nm)
		if r != null:
			return r
	return null

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Hero and e.team == 0:
				hero = e
				break
		var skel = _find(hero, "Skeleton3D")
		var rel := hero.global_position
		for i in range(skel.get_bone_count()):
			var bn: String = skel.get_bone_name(i)
			var gp: Vector3 = skel.get_bone_global_pose(i).origin
			var wp: Vector3 = skel.global_transform * gp
