content.arguments:
{"command":"$p = (Resolve-Path 'scripts\core\WeaponRig.gd'); $t = [System.IO.File]::ReadAllText($p)
$t = $t.Replace('func setup(style: String) -> void:', @'
func _ready() -> void:
	if get_parent() is BoneAttachment3D:
		call_deferred("_snap_to_hand")

## 把武器对准手臂骨末端（手掌位置）：按模型半宽与手臂骨长度推算，抵消模型 3 倍放大
func _snap_to_hand() -> void:
	if not _base_set:
		_base_set = false
	var ba := get_parent() as BoneAttachment3D
	if ba == null:
		return
	var skel := ba.get_parent() as Skeleton3D
	if skel == null:
		return
	var visual: Node3D = skel
	for i in range(6):
		if visual.get_parent() is Node3D:
			visual = visual.get_parent()
		if visual.name == "HeroModel":
			break
	var bi: int = ba.bone_idx
	if bi < 0:
		return
	var pose := skel.get_bone_global_pose(bi)
	var origin: Vector3 = skel.global_transform * pose.origin
	var axis_x: Vector3 = (skel.global_transform.basis * pose.basis.x).normalized()
	var out_x: float = 1.0 if (origin.x - visual.global_position.x) >= 0.0 else -1.0
	var half: float = _half_width(visual)
	var arm_len: float = clampf((half - absf(origin.x - visual.global_position.x)) / maxf(absf(axis_x.x), 0.2), 0.26, 1.1)
	var hand: Vector3 = origin + axis_x * (arm_len * out_x)
	var model_scale: float = maxf(skel.global_transform.basis.get_scale().x, 0.001)
	var bs := visual.global_transform.basis.orthonormalized() * Basis.from_euler(_base_rot)
	global_transform = Transform3D(bs.scaled(Vector3.ONE / model_scale), hand)
	_base_pos = position
	_base_rot = rotation
	_base_set = true

## 模型半宽（排除武器自身网格）
func _half_width(visual: Node3D) -> float:
	var lo := 0.0
	var hi := 0.0
	var first := true
	for n in visual.find_children("*", "MeshInstance3D", true, false):
		if n.is_ancestor_of(self):
			continue
		var mi := n as MeshInstance3D
		if mi.mesh == null:
			continue
		var b: AABB = mi.global_transform * mi.get_aabb()
		if first:
			lo = b.position.x
			hi = b.end.x
			first = false
		else:
			lo = minf(lo, b.position.x)
			hi = maxf(hi, b.end.x)
	if first:
		return 0.9
	return maxf((hi - lo) * 0.5, 0.3)

func setup(style: String) -> void:
'@.Replace("`r`n","`n"))
[System.IO.File]::WriteAllText($p, $t)
