{"command":"$p = (Resolve-Path 'scripts\core\HeroWeapons.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = @'
	# 握持位置：右手侧、腰胸之间（相对英雄根节点；不同武器朝向略作区分）
	var grip := Vector3(h * 0.14, h * 0.55, h * 0.05)
	var hp: Node3D = parent
	if hp == instance:
'@
$new = @'
	# 优先绑到手臂骨（握在手中，随手臂动画摆动）
	var skel := _find_skeleton(instance)
	var bone: int = -1
	if skel != null:
		bone = skel.find_bone("arm-right")
		if bone < 0:
			bone = skel.find_bone("arm-left")
	if skel != null and bone >= 0:
		var ba := BoneAttachment3D.new()
		ba.name = "WeaponHand"
		ba.bone_idx = bone
		skel.add_child(ba)
		ba.add_child(holder)
		holder.scale = Vector3.ONE / maxf(instance.scale.x, 0.001)
		holder.rotation_degrees = _hold_rot(str(rp["t"]))
		holder.setup(_style_of(str(rp["t"])))
		parent.set_meta("weapon_rig", holder)
		return
	# 兜底：无骨骼模型按固定握持点挂（右手侧、腰胸之间）
	var grip := Vector3(h * 0.14, h * 0.55, h * 0.05)
	var hp: Node3D = parent
	if hp == instance:
'@
$o = $old.Replace("`r`n","`n"); $n = $new.Replace("`r`n","`n")
if ($t.Contains($o)) { $t = $t.Replace($o, $n); 'bone bind ok' } else { 'bone bind MISS' }
# 加 _find_skeleton 辅助
$anchor = 'static func _world_aabb(root: Node3D) -> AABB:'
$helper = @'
static func _find_skeleton(root: Node) -> Skeleton3D:
	var stack: Array = [root]
	while stack.size() > 0:
		var n: Node = stack.pop_back()
		if n is Skeleton3D:
			return n
		for c in n.get_children():
			stack.append(c)
	return null

static func _world_aabb(root: Node3D) -> AABB:
'@.Replace("`r`n","`n")
if ($t.Contains($anchor)) { $t = $t.Replace($anchor, $helper.Replace("`n",$eol)); 'helper ok' } else { 'helper MISS' }
[System.IO.File]::WriteAllText($p, $t)
