$rt = $rt.Replace('	if not _base_set:' + "`n" + '		_base_set = false' + "`n", '')
$rt = $rt.Replace('	if not _base_set:' + "`r`n" + '		_base_set = false' + "`r`n", '')
[System.IO.File]::WriteAllText($r, $rt)
