{"command":"@'
extends Node

var t := 0
var bm = null
var hero = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _find(n: Node, nm: String):
	if n.name == nm:
		return n
	for c in n.get_children():
		var r = _find(c, nm)
		if r != null:
			return r
	return null

func _mesh_aabb(root: Node3D) -> AABB:
	var out := AABB()
	var has := false
	var stack: Array = [root]
	while stack.size() > 0:
		var n: Node3D = stack.pop_back()
		if n is MeshInstance3D and n.mesh != null:
			var box: AABB = n.global_transform * n.get_aabb()
			out = box if not has else out.merge(box)
			has = true
		for c in n.get_children():
			if c is Node3D:
				stack.append(c)
	return out

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 70:
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Hero and e.team == 0:
				hero = e
				break
		var w = _find(hero, "Weapon")
		var rel: Vector3 = w.global_position - hero.global_position
		var box: AABB = _mesh_aabb(w)
		print("L parent=", w.get_parent().name, " rel=", rel, " scale=", w.global_transform.basis.get_scale())
		print("L wbox=", box.size, " center_rel=", box.get_center() - hero.global_position)
		var skel = _find(hero, "Skeleton3D")
		for i in range(skel.get_bone_count()):
			if str(skel.get_bone_name(i)).begins_with("arm"):
				var wp: Vector3 = skel.global_transform * skel.get_bone_global_pose(i).origin
				print("L bone ", skel.get_bone_name(i), " rel=", wp - hero.global_position)
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx26\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx26/probe.tscn','--quit-after','200' -PassThru -RedirectStandardOutput 'devfx26\p.out' -RedirectStandardError 'devfx26\p.err'
$d = $a.WaitForExit(150000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx26\p.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx26\p.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 6 | ForEach-Object { $_.Line.Trim() }","description":"Verify weapon hand binding position","timeoutMs":250000}

