$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = @'
	var pose := skel.get_bone_global_pose(bi)
	var origin: Vector3 = skel.global_transform * pose.origin
	var axis_x: Vector3 = (skel.global_transform.basis * pose.basis.x).normalized()
	var out_x: float = 1.0 if (origin.x - visual.global_position.x) >= 0.0 else -1.0
	var half: float = _half_width(visual)
	var arm_len: float = clampf((half - absf(origin.x - visual.global_position.x)) / maxf(absf(axis_x.x), 0.2), 0.26, 1.1)
	var hand: Vector3 = origin + axis_x * (arm_len * out_x)
'@.Replace("`r`n","`n").Replace("`n",$eol)
$new = @'
	var pose := skel.get_bone_global_pose(bi)
	var origin: Vector3 = skel.global_transform * pose.origin
	# 手臂朝向：取骨骼三条轴中「水平分量最大」的一条（兼容不同模型朝向/镜像），再朝身体外侧
	var gb := skel.global_transform.basis * pose.basis
	var arm_dir := Vector3.ZERO
	var arm_score := -1.0
	for v in [gb.x, gb.y, gb.z]:
		var hv := Vector3(v.x, 0.0, v.z)
		if hv.length() > arm_score:
			arm_score = hv.length()
			arm_dir = hv.normalized()
	var rel_h := Vector3(origin.x - visual.global_position.x, 0.0, origin.z - visual.global_position.z)
	if arm_dir.dot(rel_h) < 0.0:
		arm_dir = -arm_dir
	var half := _half_width(visual)
	var arm_len := clampf(half - rel_h.length(), 0.26, 1.1)
	var hand: Vector3 = origin + arm_dir * arm_len
'@.Replace("`r`n","`n").Replace("`n",$eol)
