content.arguments:
{"command":"$r = (Resolve-Path 'scripts\core\WeaponRig.gd'); $t = [System.IO.File]::ReadAllText($r)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
# 1) 用网格顶点求手掌位置替换骨骼轴推算
$block = (@'
var pose := skel.get_bone_global_pose(bi)
	var origin: Vector3 = skel.global_transform * pose.origin
	# 手掌位置优先用模型顶点反推（最外侧、手臂高度范围内的顶点；兼容各模型骨骼朝向差异）
	var half := _half_width(visual)
	var side := 1.0 if (origin.x - visual.global_position.x) >= 0.0 else -1.0
	var hand := _hand_from_meshes(visual, side)
	if hand == Vector3.INF:
		# 兜底：按骨骼轴水平分量推算
		var gb := skel.global_transform.basis * pose.basis
		var arm_dir := Vector3.ZERO
		var arm_score := -1.0
		for v in [gb.x, gb.y, gb.z]:
			var hv := Vector3(v.x, 0.0, v.z)
			if hv.length() > arm_score:
				arm_score = hv.length()
				arm_dir = hv.normalized()
		var rel_h := Vector3(origin.x - visual.global_position.x, 0.0, origin.z - visual.global_position.z)
		if arm_dir.dot(rel_h) < 0.0:
			arm_dir = -arm_dir
		var arm_len := clampf(half - rel_h.length(), 0.26, 1.1)
		hand = origin + arm_dir * arm_len
'@).Replace("`n", $eol)
$n = [regex]::Replace($t, '(?s)var pose := skel\.get_bone_global_pose\(bi\).*?var hand: Vector3 = origin \+ arm_dir \* arm_len', $block.Replace('$','$$'))
# 2) 加手掌顶点提取 + 模型 AABB 辅助
$helper = (@'

## 从模型顶点反推手掌：模型最外侧、且高度在手臂范围内的顶点（同侧）
func _hand_from_meshes(visual: Node3D, side: float) -> Vector3:
	var box := _model_aabb(visual)
	var h: float = maxf(box.size.y, 0.2)
	var lo_y: float = visual.global_position.y + h * 0.18
	var hi_y: float = visual.global_position.y + h * 0.80
	var best := Vector3.INF
	var best_d := -1.0
	for n in visual.find_children("*", "MeshInstance3D", true, false):
		if self.is_ancestor_of(n):
			continue
		var mi := n as MeshInstance3D
		if mi.mesh == null or mi.mesh.get_surface_count() == 0:
			continue
		var arr := mi.mesh.surface_get_arrays(0)
		if arr == null or arr.size() <= Mesh.ARRAY_VERTEX:
			continue
		var verts: PackedVector3Array = arr[Mesh.ARRAY_VERTEX]
		var xf := mi.global_transform
		for v in verts:
			var wp: Vector3 = xf * v
			if wp.y < lo_y or wp.y > hi_y:
				continue
			var dx: float = wp.x - visual.global_position.x
			if dx * side <= 0.0:
				continue
			var d: float = absf(dx)
			if d > best_d:
				best_d = d
				best = wp
	return best

func _model_aabb(visual: Node3D) -> AABB:
	var out := AABB()
	var has := false
	for n in visual.find_children("*", "MeshInstance3D", true, false):
		if self.is_ancestor_of(n):
			continue
		var mi := n as MeshInstance3D
		if mi.mesh == null:
			continue
		var b: AABB = mi.global_transform * mi.get_aabb()
		out = b if not has else out.merge(b)
		has = true
	return out
'@).Replace("`n", $eol)
$n = $n.Replace('## 模型半宽（排除武器自身网格）', $helper.TrimStart() + $eol + '## 模型半宽（排除武器自身网格）')
[System.IO.File]::WriteAllText($r, $n)
Select-String -Path scripts\core\WeaponRig.gd -Pattern 'func _hand_from_meshes|func _model_aabb|_hand_from_meshes\(' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Derive hand from mesh vertices"}

