{"command":"$p = (Resolve-Path 'scripts\core\BattleManager.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = ('		sel_build_scheme_row.add_child(btn)' + $eol) + $eol + ('func _current_build_scheme_name() -> String:')
$new = ('		sel_build_scheme_row.add_child(btn)' + $eol + '	# 恢复推荐（并入方案网格末尾，省掉底部一行）' + $eol + '	var reset_btn := _sel_btn("恢复推荐", UiKit.C_GOLD, false, Vector2(112, 40))' + $eol + '	reset_btn.name = "SelectBuildRestore"' + $eol + '	reset_btn.add_theme_font_size_override("font_size", _sel_fs(UiKit.FS_SM))' + $eol + '	reset_btn.pressed.connect(_on_build_restore)' + $eol + '	sel_build_scheme_row.add_child(reset_btn)' + $eol) + $eol + ('func _current_build_scheme_name() -> String:')
if ($t.Contains($old)) { $t = $t.Replace($old, $new); 'restore moved' } else { 'restore MISS' }
[System.IO.File]::WriteAllText($p, $t)
"=== probe ==="
@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 15:
		bm = get_tree().get_first_node_in_group("battle_manager")
		var root = bm.select_ui.get_node_or_null("SelectRoot")
		var sl = root.find_child("SelectSideLeft", true, false)
		var sr = root.find_child("SelectSideRight", true, false)
		var right = root.find_child("SelectRight", true, false)
		print("L side_left=", sl != null, " kids=", sl.get_child_count() if sl else -1, " side_right=", sr != null, " kids=", sr.get_child_count() if sr else -1)
		print("L right_kids=", right.get_child_count() if right else -1, " has_btn_row=", right.find_child("SelectBackToPick", true, false) != null)
		bm._on_right_tab_pressed("出装")
	elif t == 60:
		var root = bm.select_ui.get_node_or_null("SelectRoot")
		var panel = root.find_child("SelectBuildPanel", true, false)
		var rows = root.find_child("SelectBuildRows", true, false)
		var schemes = root.find_child("SelectBuildSchemeRow", true, false)
		var body = root.find_child("SelectRightBody", true, false)
		print("L build_panel_min=", panel.get_combined_minimum_size(), " body=", body.size, " rows_min=", rows.get_combined_minimum_size(), " schemes_kids=", schemes.get_child_count(), " restore_btn=", schemes.find_child("SelectBuildRestore", true, false) != null)
		var sl = root.find_child("SelectSideLeft", true, false)
		for c in sl.get_children():
			print("L Lbtn ", c.name, " ", c.size)
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx27\probe2.gd
@'
