```
Add const TURRET_BLOCK_RADIUS: float = 3.6

Add func:
```
func _mark_solid_radius(wx: float, wz: float, radius: float) -> void:
	var cx := int(floor(wx / CELL_SIZE))
	var cz := int(floor(wz / CELL_SIZE))
	var rc := int(ceil(radius))
	for dx in range(-rc, rc + 1):
		for dz in range(-rc, rc + 1):
			if dx * dx + dz * dz > radius * radius:
				continue
			var cell := Vector2i(cx + dx, cz + dz)
			if _is_in_bounds(cell):
				astar.set_point_solid(cell, true)
				_turret_solid_cells.append(cell)

func clear_turret_base(pos: Vector3, radius: float = TURRET_BLOCK_RADIUS) -> void:
	if not initialized:
		return
	var cx := int(floor(pos.x / CELL_SIZE))
	var cz := int(floor(pos.z / CELL_SIZE))
	var rc := int(ceil(radius))
	for dx in range(-rc, rc + 1):
		for dz in range(-rc, rc + 1):
			if dx * dx + dz * dz > radius * radius:
				continue
			var cell := Vector2i(cx + dx, cz + dz)
			if not _is_in_bounds(cell):
				continue
			# 墙体不做放行，只放开塔底座
			if cell in _turret_solid_cells:
				astar.set_point_solid(cell, false)
```
Note: `cell in _turret_solid_cells` each cell loop OK.

But danger zone weight: after clearing, stale weight scale? weight only set on non-solid cells; when solid set, weight unused; after clear weight default 1 ✓.

