extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		var turrets = get_tree().get_nodes_in_group("turrets")
		print("L turrets=", turrets.size())
		var mid = null
		for x in turrets:
			if x.global_position.distance_to(Vector3(-14, 0, 14)) < 0.5:
				mid = x
		print("L mid_turret=", mid != null)
		if mid != null:
			var p = mid.global_position
			var cell = Vector2i(int(floor(p.x)), int(floor(p.z)))
			print("L center_solid=", PathFinder.astar.is_point_solid(cell))
			var solid_cnt := 0
			for dx in range(-5, 6):
				for dz in range(-5, 6):
					if PathFinder.astar.is_point_solid(Vector2i(cell.x + dx, cell.y + dz)):
						solid_cnt += 1
			print("L solid_in_11x11=", solid_cnt)
			# 从塔一侧走到另一侧：应绕行
			var a := p + Vector3(-9, 0, 0)
			var b := p + Vector3(9, 0, 0)
			var path = PathFinder.find_path(a, b)
			var max_dev := 0.0
			for w in path:
				max_dev = maxf(max_dev, absf(w.z - p.z))
			print("L path_pts=", path.size(), " max_deviation=", snappedf(max_dev, 0.1))
			# 路径不穿塔心
			var min_d := 999.0
			for w in path:
				min_d = minf(min_d, Vector2(w.x - p.x, w.z - p.z).length())
			print("L min_dist_to_tower=", snappedf(min_d, 0.1))
			# 摧毁后放开
			PathFinder.clear_turret_base(p)
			print("L after_clear_solid=", PathFinder.astar.is_point_solid(cell))
		get_tree().quit()
