content.arguments:
{"command":"$p = (Resolve-Path 'scripts\entities\Turret.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = 'func die(killer):' + $eol + '	# 塔毁后底座不再是障碍，放开寻路网格' + $eol + '	PathFinder.clear_turret_base(global_position)' + $eol + '	if _lock_beam != null and is_instance_valid(_lock_beam):'
$new = 'func die(killer):' + $eol + '	if _lock_beam != null and is_instance_valid(_lock_beam):'
if ($t.Contains($old)) { $t = $t.Replace($old, $new); 'removed die hook' } else { 'MISS die hook' }
[System.IO.File]::WriteAllText($p, $t)

$pf = (Resolve-Path 'scripts\core\PathFinder.gd'); $pt = [System.IO.File]::ReadAllText($pf)
$pe = if ($pt.Contains("`r`n")) { "`r`n" } else { "`n" }
# 删除 clear_turret_base（不再允许放开塔底座），注释同步
$start = $pt.IndexOf('# 塔被摧毁：放开该塔底座的障碍格，让单位可以通行')
if ($start -ge 0) {
	$endMark = 'func _mark_solid(wx: float, wz: float) -> void:'
	$end = $pt.IndexOf($endMark, $start)
	$pt = $pt.Substring(0, $start) + $pt.Substring($end)
	'removed clear func'
} else { 'MISS clear func' }
$pt = $pt.Replace('var _turret_solid_cells: Array = []  # 塔底座障碍格（塔被摧毁时放开）', 'var _turret_solid_cells: Array = []  # 塔底座障碍格（塔被摧毁后依然保留，废墟仍不可通行）')
$pt = $pt.Replace('	# 防御塔底座也是实体障碍：标记为不可通行，所有单位寻路需绕行（塔摧毁后由 clear_turret_base 放开）', '	# 防御塔底座也是实体障碍：标记为不可通行，所有单位寻路需绕行（塔被摧毁后废墟依旧阻挡）')
[System.IO.File]::WriteAllText($pf, $pt)
Select-String -Path scripts\core\PathFinder.gd -Pattern 'clear_turret_base|TURRET_BLOCK_RADIUS|_turret_solid_cells' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }
Select-String -Path scripts\entities\Turret.gd -Pattern 'clear_turret' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Keep turret base blocked after destruction"}

