Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' .cache\godot47.exe -Force
@'
extends Node

var t := 0
var bm = null
var started := false
var prev := {}
var stat := {}   # lane -> {dist, rev, stuck, samples, first_pos}
var frames := 0

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _lane_of(m) -> String:
	if not m.waypoints or m.waypoints.is_empty():
		return "?"
	var w: Vector3 = m.waypoints[0]
	if absf(w.z - 55.0) < 0.5: return "farm"
	if absf(w.z - 40.0) < 0.5: return "mid"
	if absf(w.x + 55.0) < 0.5: return "clash"
	return "?%.0f,%.0f" % [w.x, w.z]

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
		started = true
		return
	if not started or t < 120:
		return
	frames += 1
	var ms = get_tree().get_nodes_in_group("minions")
	for m in ms:
		if m.team != 0:
			continue
		var lane := _lane_of(m)
		if not stat.has(lane):
			stat[lane] = {"dist": 0.0, "rev": 0, "samples": 0, "max_still": 0, "still": 0, "minwp": 99.0, "wp_adv": 0, "last_pos": m.global_position, "last_dir": Vector3.ZERO}
		var s = stat[lane]
		var pos: Vector3 = m.global_position
		var lp: Vector3 = s["last_pos"]
		var step: float = pos.distance_to(lp)
		if frames > 1 and step < 30.0:
			s["dist"] += step
			var dir: Vector3 = (pos - lp)
			if dir.length() > 0.05:
				dir = dir.normalized()
				var ld: Vector3 = s["last_dir"]
				if ld.length() > 0.1 and ld.dot(dir) < -0.2:
					s["rev"] += 1
				s["last_dir"] = dir
		s["last_pos"] = pos
		s["samples"] = int(s["samples"]) + 1
	# 只统计前 30 秒
	if frames % 60 == 0:
		print("L t=", frames, " minions_total=", ms.size())
	if frames == 900:
		for k in stat:
			var s = stat[k]
			print("L lane=", k, " samples=", s["samples"], " travel=", snappedf(s["dist"], 0.1), " reversals=", s["rev"])
		# 蓝方各lane单个小兵轨迹
		for lane in ["farm", "mid", "clash"]:
			for m in ms:
				if m.team != 0:
					continue
				if _lane_of(m) == lane:
					var path := []
					var last: Vector3 = m.global_position
					# 该小兵当前所在位置序列只取当帧
					print("L now_", lane, " pos=(%.1f,%.1f) idx=%d/%d" % [m.global_position.x, m.global_position.z, m.waypoint_index, m.waypoints.size()])
					break
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx30\probe.gd
@'
