$new = @'
extends Node

var t := 0
var bm = null
var started := false
var tracked := {}
var frames := 0

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _lane_of(m) -> String:
	if not m.waypoints or m.waypoints.is_empty():
		return "?"
	var w: Vector3 = m.waypoints[0]
	if absf(w.z - 55.0) < 0.5: return "farm"
	if absf(w.z - 40.0) < 0.5: return "mid"
	if absf(w.x + 55.0) < 0.5: return "clash"
	return "?"

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
		started = true
		return
	if not started or t < 100:
		return
	frames += 1
	if frames % 20 != 0:
		return
	var ms = get_tree().get_nodes_in_group("minions")
	for m in ms:
		if m.team != 0:
			continue
		var lane := _lane_of(m)
		if lane == "?":
			continue
		var id: int = m.get_instance_id() % 10000
		var key := "%s_%d" % [lane, id]
		if not tracked.has(key):
			if lane != "farm" and lane != "clash":
				continue
			tracked[key] = []
		var arr: Array = tracked[key]
		if arr.size() < 14:
			arr.append(Vector2(m.global_position.x, m.global_position.z))
	if frames >= 560:
		for k in tracked:
			var arr: Array = tracked[k]
			var parts := PackedStringArray()
			for v in arr:
				parts.append("(%.0f,%.0f)" % [v.x, v.y])
			print("TRK ", k, " ", " ".join(parts))
		get_tree().quit()
