{"command":"$p = (Resolve-Path 'scripts\entities\Minion.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = @'
	# 无有效目标 → 沿路点移动
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		var dir = (target_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, target_pos)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < 1.0:
			waypoint_index += 1
'@
$new = @'
	# 无有效目标 → 沿路点移动
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		# 路点落在塔基障碍格内（如"己方高地塔"这类以塔位作路点）：提前切点并直线通过，
		# 否则永远到不了塔心，会绕着塔基打转（上路小兵路径发飘的主因）
		var blocked_goal := false
		if PathFinder.initialized and PathFinder.astar != null:
			var tcell := Vector2i(int(floor(target_pos.x)), int(floor(target_pos.z)))
			blocked_goal = PathFinder.astar.is_point_solid(tcell)
		var dir = (target_pos - global_position).normalized()
		if not blocked_goal or global_position.distance_to(target_pos) > 8.0:
			dir = _avoid_walls(dir, delta, target_pos)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < (4.6 if blocked_goal else 1.0):
			waypoint_index += 1
'@.Replace("`n", $eol)
$oldE = $old.Replace("`n", $eol)
if ($t.Contains($oldE)) { $t = $t.Replace($oldE, $new); 'minion patch ok' } else { 'MISS minion patch' }
[System.IO.File]::WriteAllText($p, $t)
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx30/probe.tscn','--quit-after','1500' -PassThru -RedirectStandardOutput 'devfx30\t3.out' -RedirectStandardError 'devfx30\t3.err'
$d = $a.WaitForExit(280000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx30\t3.out | Select-String -Pattern '^TRK ' | Select-Object -First 5 | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx30\t3.err | Select-String -Pattern 'Parse Error|SCRIPT ERROR' | Select-Object -First 5 | ForEach-Object { $_.Line.Trim() }","description":"Fix minion waypoint on blocked tower cells","timeoutMs":300000}

