@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _solid(x: int, z: int) -> bool:
	return PathFinder.astar.is_point_solid(Vector2i(x, z))

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 40:
		print("GRID x=-42..-8 z=60..46  (#=solid)")
		for z in range(60, 45, -1):
			var row := "%3d " % z
			for x in range(-42, -7):
				row += "#" if _solid(x, z) else "."
			print("G ", row)
		var path = PathFinder.find_path(Vector3(-42, 0, 54), Vector3(-15, 0, 56))
		var parts := PackedStringArray()
		for w in path:
			parts.append("(%.0f,%.0f)" % [w.x, w.z])
		print("P path_to_inner_tower=", " ".join(parts))
		var path2 = PathFinder.find_path(Vector3(-42, 0, 54), Vector3(-35, 0, 55))
		var p2 := PackedStringArray()
		for w in path2:
			p2.append("(%.0f,%.0f)" % [w.x, w.z])
		print("P path_to_high_tower=", " ".join(p2))
		get_tree().quit()
