content.arguments:
{"command":"$pf = (Resolve-Path 'scripts\core\PathFinder.gd'); $pt = [System.IO.File]::ReadAllText($pf)
$pe = if ($pt.Contains("`r`n")) { "`r`n" } else { "`n" }
function RepP([string]$a, [string]$b, [string]$tag) { if ($script:pt.Contains($a)) { $script:pt = $script:pt.Replace($a, $b); "OK $tag" } else { "MISS $tag" } }
RepP 'var _turret_solid_cells: Array = []  # 塔底座障碍格（塔被摧毁后依然保留，废墟仍不可通行）' ('var _turret_solid_cells: Array = []  # 塔底座障碍格（塔被摧毁后依然保留，废墟仍不可通行）' + $pe + 'var _turret_blocks: Array = []  # [{pos, cells}]：小兵用小净空绕塔时可临时放开外圈') 'blocks var'
# 记录每座塔的障碍格
RepP ('		_mark_solid_radius(turret.global_position.x, turret.global_position.z, TURRET_BLOCK_RADIUS)') ('		_mark_solid_radius(turret.global_position.x, turret.global_position.z, TURRET_BLOCK_RADIUS)' + $pe + '		_turret_blocks.append({"pos": turret.global_position, "cells": _last_mark_cells.duplicate()})') 'record blocks'
RepP ('	_turret_solid_cells.clear()' + $pe + '	for turret in get_tree().get_nodes_in_group("turrets"):') ('	_turret_solid_cells.clear()' + $pe + '	_turret_blocks.clear()' + $pe + '	for turret in get_tree().get_nodes_in_group("turrets"):') 'clear blocks'
# _mark_solid_radius 记录本次标记的格子
RepP (@'
func _mark_solid_radius(wx: float, wz: float, radius: float) -> void:
	var cx := int(floor(wx / CELL_SIZE))
	var cz := int(floor(wz / CELL_SIZE))
	var rc := int(ceil(radius))
	for dx in range(-rc, rc + 1):
		for dz in range(-rc, rc + 1):
			if dx * dx + dz * dz > radius * radius:
				continue
			var cell := Vector2i(cx + dx, cz + dz)
			if _is_in_bounds(cell):
				astar.set_point_solid(cell, true)
				_turret_solid_cells.append(cell)
'@) (@'
var _last_mark_cells: Array = []

func _mark_solid_radius(wx: float, wz: float, radius: float) -> void:
	var cx := int(floor(wx / CELL_SIZE))
	var cz := int(floor(wz / CELL_SIZE))
	var rc := int(ceil(radius))
	_last_mark_cells.clear()
	for dx in range(-rc, rc + 1):
		for dz in range(-rc, rc + 1):
			if dx * dx + dz * dz > radius * radius:
				continue
			var cell := Vector2i(cx + dx, cz + dz)
			if _is_in_bounds(cell):
				astar.set_point_solid(cell, true)
				_turret_solid_cells.append(cell)
				_last_mark_cells.append(cell)
'@) 'mark record'
# find_path 增加 low_clearance 参数：小兵用更小净空绕塔（保持贴兵线），英雄用全净空
