{"command":"$p = (Resolve-Path 'scripts\entities\Minion.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$old = @'
		var dist = global_position.distance_to(current_target.global_position) 
		if dist <= attack_range*0.01:
'@.Replace("`n", $eol)
$new = @'
		var dist = global_position.distance_to(current_target.global_position) 
		# 塔基半径 3.2：以塔基边缘判定攻击距离（塔基是障碍，否则近战兵永远够不到塔心）
		var reach: float = attack_range*0.01 + (3.2 if current_target is Turret else 0.0)
		if dist <= reach:
'@.Replace("`n", $eol)
if ($t.Contains($old)) { $t = $t.Replace($old, $new); 'reach patch ok' } else { 'MISS reach' }
[System.IO.File]::WriteAllText($p, $t)
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx30/probe.tscn','--quit-after','3100' -PassThru -RedirectStandardOutput 'devfx30\t8.out' -RedirectStandardError 'devfx30\t8.err'
$d = $a.WaitForExit(290000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx30\t8.out | Select-String -Pattern '^TRK farm' | Select-Object -First 2 | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx30\t8.err | Select-String -Pattern 'Parse Error|SCRIPT ERROR' | Select-Object -First 3 | ForEach-Object { $_.Line.Trim() }","description":"Allow melee minions to hit tower edge","timeoutMs":300000}

