extends Node

var t := 0
var bm = null
var hp0 := {}

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 120:
		for x in get_tree().get_nodes_in_group("turrets"):
			if x.team == 1:
				hp0[x.get_instance_id()] = x.health
		print("L red_turrets=", hp0.size())
	elif t == 1300:
		var hurt := 0
		var total := 0
		for x in get_tree().get_nodes_in_group("turrets"):
			if x.team == 1 and hp0.has(x.get_instance_id()):
				total += 1
				if x.health < float(hp0[x.get_instance_id()]):
					hurt += 1
		print("L red_turrets_alive=", total, " damaged=", hurt)
		# 小兵是否还在正常存在/行进
		var ms = get_tree().get_nodes_in_group("minions")
		var blue := 0
		for m in ms:
			if m.team == 0: blue += 1
		print("L blue_minions=", blue)
		get_tree().quit()
