content.arguments:
{"command":"$p = (Resolve-Path 'scripts\core\SfxManager.gd'); $t = [System.IO.File]::ReadAllText($p)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$msgs = New-Object System.Collections.ArrayList
function Rep4([string]$oldTxt, [string]$newTxt, [string]$tag) {
  $o = $oldTxt.Replace("`n", $script:eol); $n = $newTxt.Replace("`n", $script:eol)
  if ($script:t.Contains($o)) { $script:t = $script:t.Replace($o, $n); [void]$script:msgs.Add("OK $tag") } else { [void]$script:msgs.Add("MISS $tag") }
}
Rep4 '	_play_sfx("tower_down_own" if tower_team == Config.Team.PLAYER else "tower_down_enemy")' '	_play_sfx("tower_down_own" if Config.is_ally(tower_team) else "tower_down_enemy")' 'tower down'
Rep4 '	_play_sfx("vanguard_down_own" if minion_team == Config.Team.PLAYER else "vanguard_down_enemy")' '	_play_sfx("vanguard_down_own" if Config.is_ally(minion_team) else "vanguard_down_enemy")' 'vanguard down'
Rep4 '		return _scale_cfg(tw, 0.95 if int(parts[2]) == Config.Team.PLAYER else 1.06)' '		return _scale_cfg(tw, 0.95 if Config.is_ally(int(parts[2])) else 1.06)' 'tower sfx scale'
Rep4 '	var my_side := actor_team == Config.Team.PLAYER' '	var my_side := Config.is_ally(actor_team)' 'my_side'
Rep4 @'
		if victim_team == Config.Team.PLAYER:
			return "" if victim == "crystal" else "tower_lost"
		if victim_team == Config.Team.ENEMY:
			return "" if victim == "crystal" else "my_push"
'@ @'
		if Config.is_ally(victim_team):
			return "" if victim == "crystal" else "tower_lost"
		if victim_team == Config.Team.ENEMY or victim_team == Config.Team.PLAYER:
			return "" if victim == "crystal" else "my_push"
'@ 'tower destroyed announce'
[System.IO.File]::WriteAllText($p, $t)
$msgs","description":"SfxManager relative team sounds"}

