	# 移动端摇杆：世界方向移动（屏幕右→+X，屏幕上→-Z），并朝移动方向转向
	if joy_vec.length() > 0.1:
		move_vec = Vector3(joy_vec.x * cam_flip, 0, -joy_vec.y * cam_flip).normalized()
