{"command":"$p = (Resolve-Path 'scripts\entities\Hero.gd').Path
$t = [System.IO.File]::ReadAllText($p)
$hasCR = $t.Contains("`r`n")
$lines = [System.Collections.ArrayList]($t -split "`r`n")
if (-not $hasCR) { $lines = [System.Collections.ArrayList]($t -split "`n") }
$idx = -1
for ($i = 0; $i -lt $lines.Count; $i++) {
  if ($lines[$i] -match 'move_vec = Vector3\(joy_vec\.x, 0, -joy_vec\.y\)\.normalized\(\)') { $idx = $i; break }
}
"joy line idx=$idx"
if ($idx -ge 0) {
  $lines[$idx] = "`t`t`tmove_vec = Vector3(joy_vec.x * cam_flip, 0, -joy_vec.y * cam_flip).normalized()"
  $lines.Insert($idx - 1, "`t`t# 玩家在红方时镜头绕Y轴转180°：屏幕方向整体取反，保持与蓝方同一手感")
  $lines.Insert($idx, "`t`tvar cam_flip := -1.0 if Config.player_team == Config.Team.ENEMY else 1.0")
}
for ($i = 0; $i -lt $lines.Count; $i++) {
  if ($lines[$i] -match 'move_vec = Vector3\(input_dir\.x, 0, -input_dir\.z\)\.normalized\(\)') {
    $lines[$i] = $lines[$i].Replace('-input_dir.z', '-input_dir.z * cam_flip').Replace('input_dir.x,', 'input_dir.x * cam_flip,')
    "dir line fixed at $i"
  }
}
$out = $lines -join ($(if ($hasCR) { "`r`n" } else { "`n" }))
[System.IO.File]::WriteAllText($p, $out)
Select-String -Path scripts\entities\Hero.gd -Pattern 'cam_flip' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }","description":"Line-based insert of cam_flip logic"}

