{"command":"@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.ENEMY
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		for x in get_tree().get_nodes_in_group("heroes"):
			print("L hero team=", x.team, " pos=", x.global_position.round(), " ai=", x.is_ai)
	elif t == 1800:
		var ms = get_tree().get_nodes_in_group("minions")
		var blue := 0
		var red := 0
		for m in ms:
			if m.team == 0: blue += 1
			else: red += 1
		print("L after30s minions blue=", blue, " red=", red, " game_over=", bm.game_over, " hero_hp=", int(bm.hero.health))
		print("L mm=", bm.minimap.player_team, " kill_stats=", bm.team_player_kills, "-", bm.team_enemy_kills)
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx31\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx31/probe.tscn','--quit-after','1900' -PassThru -RedirectStandardOutput 'devfx31\p3.out' -RedirectStandardError 'devfx31\p3.err'
$d = $a.WaitForExit(280000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx31\p3.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx31\p3.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 8 | ForEach-Object { $_.Line.Trim() }","description":"Red-team 30s gameplay runtime probe","timeoutMs":300000}

