{"command":"$root = (Get-Location).Path
$msgs = New-Object System.Collections.ArrayList
function P([string]$rel, [string]$oldTxt, [string]$newTxt, [string]$tag) {
  $fp = Join-Path $script:root $rel
  $t = [System.IO.File]::ReadAllText($fp)
  $eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
  $o = $oldTxt.Replace("`n", $eol); $n = $newTxt.Replace("`n", $eol)
  if ($t.Contains($o)) { $t = $t.Replace($o, $n); [System.IO.File]::WriteAllText($fp, $t); [void]$script:msgs.Add("OK $tag") } else { [void]$script:msgs.Add("MISS $tag") }
}
# PathFinder: 删除塔基网格障碍与 low_clearance 机制
P 'scripts\core\PathFinder.gd' @'
const TURRET_BLOCK_RADIUS: float = 3.6  # 防御塔底座半径：网格标记为不可通行，必须绕行
'@ '' 'pf const'
P 'scripts\core\PathFinder.gd' @'
var _turret_solid_cells: Array = []  # 塔底座障碍格（塔被摧毁后依然保留，废墟仍不可通行）
var _turret_blocks: Array = []  # [{pos, cells}]：小兵用小净空绕塔时可临时放开外圈
'@ '' 'pf vars'
P 'scripts\core\PathFinder.gd' @'
	# 防御塔底座也是实体障碍：标记为不可通行，所有单位寻路需绕行（塔被摧毁后废墟依旧阻挡）
	_turret_solid_cells.clear()
	_turret_blocks.clear()
	for turret in get_tree().get_nodes_in_group("turrets"):
		if not is_instance_valid(turret):
			continue
		_mark_solid_radius(turret.global_position.x, turret.global_position.z, TURRET_BLOCK_RADIUS)
		_turret_blocks.append({"pos": turret.global_position, "cells": _last_mark_cells.duplicate()})

'@ '' 'pf mark block'
P 'scripts\core\PathFinder.gd' @'
var _last_mark_cells: Array = []

func _mark_solid_radius(wx: float, wz: float, radius: float) -> void:
	var cx := int(floor(wx / CELL_SIZE))
	var cz := int(floor(wz / CELL_SIZE))
	var rc := int(ceil(radius))
	_last_mark_cells.clear()
	for dx in range(-rc, rc + 1):
		for dz in range(-rc, rc + 1):
			if dx * dx + dz * dz > radius * radius:
				continue
			var cell := Vector2i(cx + dx, cz + dz)
			if _is_in_bounds(cell):
				astar.set_point_solid(cell, true)
				_turret_solid_cells.append(cell)
				_last_mark_cells.append(cell)


'@ '' 'pf mark radius func'
P 'scripts\core\PathFinder.gd' 'func find_path(from: Vector3, to: Vector3, bias_dir: Vector3 = Vector3.ZERO, team: int = -1, attack_range: float = -1.0, attack_target: Vector3 = Vector3.ZERO, low_clearance: float = -1.0) -> PackedVector3Array:' 'func find_path(from: Vector3, to: Vector3, bias_dir: Vector3 = Vector3.ZERO, team: int = -1, attack_range: float = -1.0, attack_target: Vector3 = Vector3.ZERO) -> PackedVector3Array:' 'pf sig'
P 'scripts\core\PathFinder.gd' @'
	# 小兵：临时放开塔基障碍外圈（只保留塔心 low_clearance 范围），避免整条兵线被推到塔基外 4~5m
	var _released: Array = []
	if low_clearance >= 0.0:
		for blk in _turret_blocks:
			var bp: Vector3 = blk["pos"]
			for cell in blk["cells"]:
				if Vector2(cell.x - bp.x, cell.y - bp.z).length() > low_clearance:
					astar.set_point_solid(cell, false)
					_released.append(cell)

'@ '' 'pf release'
P 'scripts\core\PathFinder.gd' @'
			for cell in _released:
				astar.set_point_solid(cell, true)
'@ '' 'pf restore fail'
P 'scripts\core\PathFinder.gd' @'
	for cell in _released:
		astar.set_point_solid(cell, true)
	return path_3d
'@ @'
	return path_3d
'@ 'pf restore ok'
# GameEntity: 去掉 low_clearance 参数
P 'scripts\entities\GameEntity.gd' 'func _avoid_walls(move_dir: Vector3, delta: float, destination: Vector3 = Vector3.ZERO, attack_range: float = -1.0, attack_target: Vector3 = Vector3.ZERO, low_clearance: float = -1.0) -> Vector3:' 'func _avoid_walls(move_dir: Vector3, delta: float, destination: Vector3 = Vector3.ZERO, attack_range: float = -1.0, attack_target: Vector3 = Vector3.ZERO) -> Vector3:' 'ge sig'
P 'scripts\entities\GameEntity.gd' '_nav_path = PathFinder.find_path(global_position, desired, move_dir.normalized(), team if self is Hero else -1, attack_range, attack_target, low_clearance)' '_nav_path = PathFinder.find_path(global_position, desired, move_dir.normalized(), team if self is Hero else -1, attack_range, attack_target)' 'ge call'
# Minion: 还原路点直行（塔不再挡路）
P 'scripts\entities\Minion.gd' @'
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		# 路点本身常是防御塔塔位（塔基现在是不可通行障碍）：以"塔后一点"作为导航目标，
		# 让小兵沿切线绕过塔基后继续沿兵线走，而不是绕着塔心打转/整段贴塔偏移
		var blocked_goal := false
		if PathFinder.initialized and PathFinder.astar != null:
			var tcell := Vector2i(int(floor(target_pos.x)), int(floor(target_pos.z)))
			blocked_goal = PathFinder.astar.is_point_solid(tcell)
		var steer_pos: Vector3 = target_pos
		if blocked_goal and waypoint_index + 1 < waypoints.size():
			var beyond: Vector3 = waypoints[waypoint_index + 1]
			var nd: Vector3 = beyond - target_pos
			nd.y = 0.0
			if nd.length() > 0.1:
				steer_pos = target_pos + nd.normalized() * 7.0
		var dir = (steer_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, steer_pos, -1.0, Vector3.ZERO, 3.4)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < (4.6 if blocked_goal else 1.0):
			waypoint_index += 1
'@ @'
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		var dir = (target_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, target_pos)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < 1.0:
			waypoint_index += 1
'@ 'minion waypoint restore'
$msgs","description":"Remove turret grid blocking and minion hacks"}

