		dir = _avoid_walls(dir, delta, steer_pos, -1.0, Vector3.ZERO, 3.4)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < (4.6 if blocked_goal else 1.0):
			waypoint_index += 1
'@ @'
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		var dir = (target_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, target_pos)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < 1.0:
			waypoint_index += 1
'@ 'minion waypoint restore'
$msgs","description":"Remove turret grid blocking and minion hacks"}

