content.arguments:
{"command":"$fp = (Resolve-Path 'scripts\entities\Minion.gd').Path
$t = [System.IO.File]::ReadAllText($fp)
$eol = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
$msgs = New-Object System.Collections.ArrayList
function MP([string]$oldTxt, [string]$newTxt, [string]$tag) {
  $o = $oldTxt.Replace("`n", $script:eol); $n = $newTxt.Replace("`n", $script:eol)
  if ($script:t.Contains($o)) { $script:t = $script:t.Replace($o, $n); [void]$script:msgs.Add("OK $tag") } else { [void]$script:msgs.Add("MISS $tag") }
}
MP @'
var _death_anim_started: bool = false
'@ @'
var _death_anim_started: bool = false
var _wp_idx_cached: int = -1      # 路点到达半径缓存（塔位路点会被塔基推挤，半径需放宽）
var _wp_reach: float = 1.0
'@ 'wp cache vars'
MP @'
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		var dir = (target_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, target_pos)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < 1.0:
			waypoint_index += 1
'@ @'
	if waypoint_index < waypoints.size():
		var target_pos = waypoints[waypoint_index]
		# 塔位路点：塔基会把单位推开，永远站不到路点中心 → 放宽到达半径，避免绕塔打转
		if waypoint_index != _wp_idx_cached:
			_wp_idx_cached = waypoint_index
			_wp_reach = 1.0
			for tu in get_tree().get_nodes_in_group("turrets"):
				if is_instance_valid(tu) and tu.global_position.distance_to(target_pos) < 5.0:
					_wp_reach = 4.6
					break
			if _wp_reach <= 1.0:
				for st in get_tree().get_nodes_in_group("tower_stumps"):
					if is_instance_valid(st) and st.global_position.distance_to(target_pos) < 5.0:
						_wp_reach = 4.6
						break
		var dir = (target_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, target_pos)
		global_position += dir * move_speed*0.01 * delta
		rotation.y = atan2(dir.x, dir.z)
		_play_anim("walk")
		if global_position.distance_to(target_pos) < _wp_reach:
			waypoint_index += 1
'@ 'wp reach logic'
[System.IO.File]::WriteAllText($fp, $t)
$msgs","description":"Add tower waypoint arrival radius"}

