{"command":"@'
extends Node

var t := 0
var bm = null
var mn = null
var tgt = null
var hp0 := 0.0
var m2 = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		for x in get_tree().get_nodes_in_group("minions"):
			if x.team == 0 and x.display_name == "melee" and x.waypoints.size() > 3 and mn == null:
				mn = x
			elif x.team == 0 and x.display_name == "melee" and x != mn and m2 == null:
				m2 = x
		for x in get_tree().get_nodes_in_group("turrets"):
			if x.team == 1 and x.global_position.distance_to(Vector3(58, 0, 28)) < 0.5: tgt = x
		hp0 = tgt.health
		m2.global_position = Vector3(52, 0, 28)
		m2.current_target = null
		print("L tracer=", mn != null, " test_minion=", m2 != null, " tower=", tgt != null)
	elif t > 60 and t % 180 == 0 and t <= 1800 and is_instance_valid(mn):
		var p: Vector3 = mn.global_position
		print("TRK (", int(p.x), ",", int(p.z), ") wp=", mn.waypoint_index)
	elif t == 1500:
		print("L tower_hp=", int(tgt.health), " dmg=", int(hp0 - tgt.health))
		var ms = get_tree().get_nodes_in_group("minions")
		var blue := 0
		for m in ms:
			if m.team == 0: blue += 1
		print("L blue_minions=", blue)
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx32\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx32/probe.tscn','--quit-after','1550' -PassThru -RedirectStandardOutput 'devfx32\p2.out' -RedirectStandardError 'devfx32\p2.err'
$d = $a.WaitForExit(280000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx32\p2.out | Select-String -Pattern '^L |^TRK ' | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx32\p2.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 6 | ForEach-Object { $_.Line.Trim() }","description":"Probe minion lane and tower damage after fix","timeoutMs":300000}

