				astar.set_point_weight_scale(cell, TURRET_DANGER_WEIGHT)
'@ @'
				astar.set_point_weight_scale(cell, maxf(TURRET_DANGER_WEIGHT, float(_turret_base_weight.get(cell, 1.0))))
'@ 'danger weight max'
PF 'scripts\core\PathFinder.gd' 'const TURRET_DANGER_WEIGHT' 'const TURRET_BASE_WEIGHT: float = 6.0   # 塔基附近代价：可通行但寻路优先绕行
const TURRET_DANGER_WEIGHT' 'base weight const'
# Minion: 去掉切线绕塔（A* 已绕行），到达半径 5.0
PF 'scripts\entities\Minion.gd' @'
		var dir = (target_pos - global_position).normalized()
		# 塔基不再写入寻路网格（靠推挤挡人）：贴着塔基走会正面顶塔 → 提前沿切线绕开
		dir = _steer_around_towers(dir, target_pos)
		dir = _avoid_walls(dir, delta, target_pos)
'@ @'
		var dir = (target_pos - global_position).normalized()
		dir = _avoid_walls(dir, delta, target_pos)
'@ 'minion remove deflect call'
PF 'scripts\entities\Minion.gd' @'
# 塔基/塔墩避让：前进方向正对塔基时混入切线方向，让小兵沿塔基外沿滑过去而不是顶住
func _steer_around_towers(dir: Vector3, target_pos: Vector3) -> Vector3:
	var steer := dir
	for tu in get_tree().get_nodes_in_group("turrets"):
		if not is_instance_valid(tu) or tu.health <= 0:
			continue
		if tu.global_position.distance_to(target_pos) < 3.0:
			continue   # 目标就是这座塔（要走近攻击），不绕
		steer = _deflect_around(steer, tu.global_position, target_pos)
	for st in get_tree().get_nodes_in_group("tower_stumps"):
		if is_instance_valid(st):
			steer = _deflect_around(steer, st.global_position, target_pos)
	return steer

func _deflect_around(dir: Vector3, center: Vector3, target_pos: Vector3) -> Vector3:
	var to_t: Vector3 = center - global_position
	to_t.y = 0.0
	var d: float = to_t.length()
	if d > 8.0 or d < 0.01:
		return dir
	var n: Vector3 = to_t / d
	if dir.dot(n) <= 0.1:
		return dir
	var tangent := Vector3(-n.z, 0.0, n.x)
	var to_target: Vector3 = target_pos - global_position
	to_target.y = 0.0
	if tangent.dot(to_target) < 0.0:
		tangent = -tangent
	var w: float = clampf((7.5 - d) / 6.5, 0.0, 1.0)
	if d < 4.2:
		w = 1.0
	return (dir * (1.0 - w) + tangent * w).normalized()

