extends Node

var t := 0
var bm = null
var mn = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		for x in get_tree().get_nodes_in_group("minions"):
			if x.team == 0 and x.display_name == "melee" and x.waypoints.size() > 3:
				mn = x; break
		print("L set=", mn != null)
	elif t > 60 and t % 150 == 0 and t <= 3000 and is_instance_valid(mn):
		var p: Vector3 = mn.global_position
		print("TRK (", int(p.x), ",", int(p.z), ") wp=", mn.waypoint_index, " hp=", int(mn.health))
	elif t == 3050:
		var ms = get_tree().get_nodes_in_group("minions")
		var alive := 0
		for m in ms:
			if m.team == 0 and m.health > 0: alive += 1
		print("L blue_alive=", alive)
		get_tree().quit()
