{"command":"$root=(Get-Location).Path
$msgs=New-Object System.Collections.ArrayList
function ER2([string]$rel,[string]$oldTxt,[string]$newTxt,[string]$tag){
  $fp=Join-Path $script:root $rel
  $t=[System.IO.File]::ReadAllText($fp)
  $eol=if($t.Contains("`r`n")){"`r`n"}else{"`n"}
  $o=$oldTxt.Replace("`n",$eol); $n=$newTxt.Replace("`n",$eol)
  if($t.Contains($o)){$t=$t.Replace($o,$n);[System.IO.File]::WriteAllText($fp,$t);[void]$script:msgs.Add("OK $tag")}else{[void]$script:msgs.Add("MISS $tag")}
}
