{"command":"@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 70:
		var near := 0
		var min_d := 999.0
		for w in get_tree().get_nodes_in_group("walls"):
			var d: float = w.global_position.distance_to(Vector3(-62, 0, 62))
			if d < 8.0:
				near += 1
				min_d = minf(min_d, d)
		print("L spring_walls_near8=", near, " min_d=", "%.2f" % min_d)
		for p: Vector3 in [Vector3(-60, 0, 60), Vector3(-61, 0, 61), Vector3(-62, 0, 62), Vector3(-61, 0, 59)]:
			var c := Vector2i(int(floor(p.x)), int(floor(p.z)))
			print("L solid(", int(p.x), ",", int(p.z), ")=", PathFinder.astar.is_point_solid(c))
		bm.hero.global_position = Vector3(-56, 0, 56)
		bm.hero.move_target = Vector3(-62, 0, 62)
	elif t == 260:
		var hp: Vector3 = bm.hero.global_position
		print("L center hero=(", "%.2f" % hp.x, ",", "%.2f" % hp.z, ") dist=", "%.2f" % hp.distance_to(Vector3(-62, 0, 62)), " in_spring=", bm.hero.is_in_own_fountain())
		bm.hero.move_target = Vector3(-50, 0, 50)
	elif t == 440:
		var hp2: Vector3 = bm.hero.global_position
		print("L exit hero=(", "%.1f" % hp2.x, ",", "%.1f" % hp2.z, ")")
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx34\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx34/probe.tscn','--quit-after','470' -PassThru -RedirectStandardOutput 'devfx34\p2.out' -RedirectStandardError 'devfx34\p2.err'
$d = $a.WaitForExit(220000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx34\p2.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx34\p2.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 6 | ForEach-Object { $_.Line.Trim() }","description":"Probe spring walkability after changes","timeoutMs":260000}

