content.arguments:
{"command":"$root=(Get-Location).Path
$msgs=New-Object System.Collections.ArrayList
function E6([string]$rel,[string]$oldTxt,[string]$newTxt,[string]$tag){
  $fp=Join-Path $script:root $rel
  $t=[System.IO.File]::ReadAllText($fp)
  $eol=if($t.Contains("`r`n")){"`r`n"}else{"`n"}
  $o=$oldTxt.Replace("`n",$eol); $n=$newTxt.Replace("`n",$eol)
  if($t.Contains($o)){$t=$t.Replace($o,$n);[System.IO.File]::WriteAllText($fp,$t);[void]$script:msgs.Add("OK $tag")}else{[void]$script:msgs.Add("MISS $tag")}
}
# 撤回寻路网格的泉水清格（石环恢复后保持原有阻挡）
E6 'scripts\core\PathFinder.gd' @'
	# 泉水小院（基地角）可通行：清掉边界实心格，单位能走进泉水
	for spring in [Vector2(-62, 62), Vector2(62, -62)]:
		for dx in range(-5, 6):
			for dz in range(-5, 6):
				if dx * dx + dz * dz > 22:
					continue
				var scell := Vector2i(int(spring.x) + dx, int(spring.y) + dz)
				if _is_in_bounds(scell):
					astar.set_point_solid(scell, false)

'@ '' 'pf revert spring cells'
# 撤回 Wall.visual_only
E6 'scripts\entities\Wall.gd' @'
var outer_len: float = 2.0
# 纯视觉墙：只出模型，不产生碰撞、不进 walls 组（不参与推挤/寻路障碍）
var visual_only: bool = false
'@ @'
var outer_len: float = 2.0
'@ 'wall revert flag'
E6 'scripts\entities\Wall.gd' @'
	_set_shadow_off(vis)

	if visual_only:
		collision_layer = 0
		return

	# 碰撞形状
'@ @'
	_set_shadow_off(vis)

	# 碰撞形状
'@ 'wall revert visual only'
$msgs","description":"Revert nav unmark and visual-only wall flag"}

