content.arguments:
{"command":"$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','--export-release','"Windows Desktop"','HonorKing.exe' -PassThru -RedirectStandardOutput 'devfx40\e.out' -RedirectStandardError 'devfx40\e.err'
$d = $a.WaitForExit(900000); if (-not $d) { $a.Kill(); "EXPORT TIMEOUT" }
"exit=$($a.ExitCode)"
Get-Content devfx40\e.err -ErrorAction SilentlyContinue | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 6 | ForEach-Object { $_.Line.Trim() }
$a2 = Start-Process -FilePath (Resolve-Path 'HonorKing.exe') -ArgumentList '--headless','--quit-after','300' -PassThru -RedirectStandardOutput 'devfx40\r.out' -RedirectStandardError 'devfx40\r.err'
$d2 = $a2.WaitForExit(180000); if (-not $d2) { $a2.Kill(); "RUN TIMEOUT" }
"run_exit=$($a2.ExitCode)"
"run_err=$((Get-Content devfx40\r.err -ErrorAction SilentlyContinue | Select-String -Pattern 'SCRIPT ERROR|Parse Error').Count)"
Get-Process godot47 -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Sleep -Milliseconds 300
foreach ($dir in @('devfx40','.cache')) { if (Test-Path $dir) { Remove-Item $dir -Recurse -Force -ErrorAction SilentlyContinue } }
if ((Test-Path 'devfx40') -or (Test-Path '.cache')) { "cleanup_incomplete" } else { "cleanup_ok" }
pwsh -NoProfile -File scripts\dev\notify.ps1 -Title "HonorKing · 小兵攻击动画加强" -Message "近战/超级兵攻击改为横向挥砍：蓄力挤压→前冲横砍拉伸腾空→回弹收势，逐兵随机节奏幅度，命中加武器刀光" 2>&1 | Select-Object -Last 1","description":"Export, smoke, cleanup, notify","timeoutMs":900000}

