{"command":"New-Item -ItemType Directory -Force devfx42, .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' '.cache\godot47.exe' -Force
@'
extends Node

var t := 0
var bm = null
var panel = null
var stage := 0

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _click(gp: Vector2) -> void:
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = gp
	ev.global_position = gp
	get_viewport().push_input(ev)

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 90:
		UiManager._show_death_recap(bm.hero)
		panel = UiManager.death_recap_panel
		print("L panel pos=", panel.global_position, " size=", panel.size, " s=", "%.2f" % panel._s(), " anchors=", panel.anchor_left, ",", panel.anchor_top)
	elif t == 120:
		var L = panel._layout()
		print("L src_rows=", L["src_rows"], " n_sources=", mini((panel.data.get("sources", []) as Array).size(), 4))
		var r: Rect2 = panel._source_rect(1, L)
		var center: Vector2 = r.get_center()
		var gp: Vector2 = panel.global_position + center * panel._s()
		print("L click row1 local=", center, " screen=", gp)
		_click(gp)
	elif t == 150:
		print("L expanded_after_row1=", panel._expanded)
		var L2 = panel._layout()
		var cr: Rect2 = panel._close_rect()
		var gp2: Vector2 = panel.global_position + cr.get_center() * panel._s()
		print("L click close screen=", gp2)
		_click(gp2)
	elif t == 180:
		print("L panel_visible_after_close=", panel.visible)
		get_tree().quit()
