	ev.position = gp
	ev.global_position = gp
	get_viewport().push_input(ev)

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 90:
		panel = DRV.new()
		UiManager.add_child(panel)
		var d := {
			"killer": "安琪拉", "killer_hero": "安琪拉", "killer_team": 1, "respawn": 10.0, "respawn_total": 20.0,
			"cc": 0.0, "total": 1300.0, "phys": 400.0, "mag": 900.0, "true": 0.0,
			"sources": [
				{"name": "安琪拉", "hero": "安琪拉", "team": 1, "total": 900.0, "skills": "1技能", "hits": [{"t": 1.0, "v": 300.0, "is_magic": true}, {"t": 2.0, "v": 600.0, "is_magic": true}]},
				{"name": "后羿", "hero": "后羿", "team": 1, "total": 400.0, "skills": "普攻", "hits": []},
			],
			"attrib": [], "advice": "建议：注意走位",
		}
		panel.set_data(d)
		panel.set_anchors_preset(Control.PRESET_CENTER)
		var sz: Vector2 = panel.size
		panel.offset_left = -sz.x * 0.5
		panel.offset_right = sz.x * 0.5
		panel.offset_top = -sz.y * 0.5 + 8.0
		panel.offset_bottom = sz.y * 0.5 + 8.0
		panel.modulate.a = 1.0
		print("L grect=", panel.get_global_rect(), " visible=", panel.visible)
	elif t == 140:
		var L = panel._layout()
		var r: Rect2 = panel._source_rect(1, L)
		var gp: Vector2 = panel.global_position + r.get_center() * panel._s()
		print("L row1 screen=", gp, " row0=", panel._source_rect(0, L))
		_click(gp)
	elif t == 170:
		print("L expanded=", panel._expanded)
		if panel._expanded >= 0:
			var L2 = panel._layout()
			print("L after_expand grect=", panel.get_global_rect(), " hit_rows_exists=", L2.has("hit_rows"))
			var hit_r: Rect2 = panel._source_rect(1, L2)
			_click(panel.global_position + hit_r.get_center() * panel._s())
	elif t == 200:
		print("L expanded_final=", panel._expanded, " hit_page=", panel._hit_page)
		get_tree().quit()
