{"command":"@'
extends Node

const DRV = preload("res://scripts/ui/DeathRecapView.gd")
var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 90:
		var names: Array = []
		for n in get_tree().get_nodes_in_group("heroes"):
			names.append(str(n.display_name))
		print("L heroes=", names)
		var h = bm.hero
		var now = Time.get_ticks_msec() / 1000.0
		h.damage_log = [
			{"time": now - 1.5, "source": "安琪拉", "amount": 300.0, "is_magic": true, "skill_id": 1, "crit": false},
			{"time": now - 1.2, "source": "后羿", "amount": 200.0, "is_magic": false, "skill_id": 0, "crit": false},
			{"time": now - 0.9, "source": "近战兵", "amount": 40.0, "is_magic": false, "skill_id": 0, "crit": false},
		]
		var d: Dictionary = DRV.build(h, bm)
		print("L src_names=", d.get("sources").map(func(s): return s["name"]), " attribs=", d.get("attrib").map(func(a): return a["text"]))
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx43\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx43/probe.tscn','--quit-after','120' -PassThru -RedirectStandardOutput 'devfx43\p2.out' -RedirectStandardError 'devfx43\p2.err'
$d = $a.WaitForExit(200000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx43\p2.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
Get-Content devfx43\p2.err -ErrorAction SilentlyContinue | Select-String -Pattern 'SCRIPT ERROR|Parse Error' | Select-Object -First 4 | ForEach-Object { $_.Line.Trim() }","description":"Debug hero source count","timeoutMs":240000}

