{"command":"@'
extends Node

const DRV = preload("res://scripts/ui/DeathRecapView.gd")
var t := 0
var panel = null
var got := Vector2(-999, -999)
var target_canvas := Vector2.ZERO

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 40:
		panel = DRV.new()
		UiManager.add_child(panel)
		panel.z_index = 200
		var d := {
			"killer": "孙悟空", "killer_hero": "孙悟空", "killer_team": 1, "respawn": 12.0, "respawn_total": 20.0,
			"cc": 0.0, "total": 1300.0, "phys": 400.0, "mag": 900.0, "true": 0.0,
			"sources": [
				{"name": "孙悟空", "hero": "孙悟空", "team": 1, "total": 900.0, "skills": "1技能", "hits": [{"t": 1.0, "v": 300.0, "is_magic": true}]},
				{"name": "妲己", "hero": "妲己", "team": 1, "total": 400.0, "skills": "普攻", "hits": []},
			],
			"attrib": [], "advice": "",
		}
		panel.set_data(d)
		panel.position = Vector2(200, 60)
		panel.modulate.a = 1.0
		panel.gui_input.connect(func(ev):
			if ev is InputEventMouseButton and ev.pressed:
				got = ev.position)
		var win := DisplayServer.window_get_size()
		print("L canvas_vp=", get_viewport().get_visible_rect().size, " win_size=", win, " win_pos=", DisplayServer.window_get_position(),
			" s=", "%.3f" % panel._s(), " grect=", panel.get_global_rect(), " content_scale=", get_tree().get_root().content_scale_size,
			" cs_mode=", get_tree().get_root().content_scale_mode, " cs_factor=", get_tree().get_root().content_scale_factor)
	elif t == 70:
		var L = panel._layout()
		var r: Rect2 = panel._source_rect(1, L)
		target_canvas = panel.global_position + r.get_center() * panel._s()
		var win := DisplayServer.window_get_size()
		var vp := get_viewport().get_visible_rect().size
		var k := Vector2(win) / vp
		var win_pos: Vector2 = DisplayServer.window_get_position()
		var screen_pt: Vector2 = win_pos + target_canvas * k
		print("L target_canvas=", target_canvas, " k=", k, " screen_pt=", screen_pt)
		var mm := InputEventMouseMotion.new()
		mm.position = target_canvas * k
		mm.global_position = mm.position
		Input.parse_input_event(mm)
		var ev := InputEventMouseButton.new()
		ev.button_index = MOUSE_BUTTON_LEFT
		ev.pressed = true
		ev.position = target_canvas * k
		ev.global_position = ev.position
		Input.parse_input_event(ev)
		print("L sent click at win coords ", ev.position)
	elif t == 100:
		print("L got_local=", got, " expected=", Vector2(200, 60) + Vector2.ZERO, " expanded=", panel._expanded)
		var ev2 := InputEventMouseButton.new()
		ev2.button_index = MOUSE_BUTTON_LEFT
		ev2.pressed = false
		ev2.position = Vector2.ZERO
		Input.parse_input_event(ev2)
	elif t == 120:
		print("L final=", panel._expanded)
		get_tree().quit()
