{"command":"New-Item -ItemType Directory -Force devfx45 | Out-Null
@'
extends Node

const DRV = preload("res://scripts/ui/DeathRecapView.gd")
var t := 0
var panel = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _press(mouse_ev: bool, local_px: Vector2) -> void:
	if mouse_ev:
		var ev := InputEventMouseButton.new()
		ev.button_index = MOUSE_BUTTON_LEFT
		ev.pressed = true
		ev.position = local_px
		panel._gui_input(ev)
	else:
		var ev2 := InputEventScreenTouch.new()
		ev2.pressed = true
		ev2.position = local_px
		panel._gui_input(ev2)

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		var bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 90:
		panel = DRV.new()
		UiManager.add_child(panel)
		panel.set_data({
			"killer": "孙悟空", "killer_hero": "孙悟空", "killer_team": 1, "respawn": 12.0, "respawn_total": 20.0,
			"cc": 0.0, "total": 1300.0, "phys": 400.0, "mag": 900.0, "true": 0.0,
			"sources": [
				{"name": "孙悟空", "hero": "孙悟空", "team": 1, "total": 900.0, "skills": "1技能", "hits": [{"t": 1.0, "v": 300.0, "is_magic": true}, {"t": 0.6, "v": 200.0, "is_magic": true}]},
				{"name": "妲己", "hero": "妲己", "team": 1, "total": 400.0, "skills": "普攻", "hits": []},
			],
			"attrib": [], "advice": "",
		})
		panel.position = Vector2(100, 40)
	elif t == 120:
		var L = panel._layout()
		var r: Rect2 = panel._source_rect(1, L)
		var px: Vector2 = r.get_center() * panel._s()
		# 模拟"一次真实点击"：桌面端会同时到达 Mouse + ScreenTouch 两条事件
		_press(true, px)
		_press(false, px)
	elif t == 140:
		print("L expanded_one_click=", panel._expanded, " (期望 1)")
		var L = panel._layout()
		var r: Rect2 = panel._source_rect(1, L)
		_press(true, r.get_center() * panel._s())
		_press(false, r.get_center() * panel._s())
	elif t == 160:
		print("L expanded_second_click=", panel._expanded, " (期望 -1 收起)")
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx45\probe.gd
@'
