@'
extends Node

var t := 0
var bm = null
var h = null
var fx_before := 0
var done := false

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _count_fx() -> int:
	return get_tree().get_nodes_in_group("vfx_fx").size() + get_tree().get_nodes_in_group("fx").size()

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("小乔", "flash")
	elif t == 90:
		h = bm.hero
		print("L hero=", h.display_name, " skills=", h.skills[1].skill_name if h.skills.size() > 1 else "none")
		fx_before = get_tree().get_node_count()
		# 直接执行 2 技能效果（与真实施法同一条代码路径）
		var pos: Vector3 = h.global_position + Vector3(0, 0, -3)
		SkillDatabase.apply_skills(h, 2, pos)
	elif t == 150:
		var props := get_tree().get_nodes_in_group("vfx_prop")
		var fxs := get_tree().get_nodes_in_group("vfx_fx")
		print("L props=", props.size(), " fx=", fxs.size(), " node_delta=", get_tree().get_node_count() - fx_before)
		for p in props:
			var kinds: Array = []
			for c in p.get_children():
				kinds.append(c.get_class())
			print("L prop_children=", kinds)
		done = true
	elif t == 220:
		print("L final_props=", get_tree().get_nodes_in_group("vfx_prop").size(), " final_fx=", get_tree().get_nodes_in_group("vfx_fx").size())
		get_tree().quit()
