elif dist > 1.5: ratio = maxf(0.7, 1.1 - (dist - 1.5) * 0.4)
ent.take_damage(int(w_dmg_base * ratio), self, false, 2, 0)
ent.knockup_timer = max(ent.knockup_timer, 0.5)
_cc_burst(ent)
