@'
extends Node

var t := 0
var bm = null
var h = null
var hero_name := "小乔"
var foe = null
var foe_hp0 := 0.0

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	var ua := OS.get_cmdline_user_args()
	if ua.size() > 0:
		hero_name = ua[0]
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _cast(idx: int) -> void:
	if h == null or h.health <= 0: return
	var pos: Vector3 = h.global_position + Vector3(0, 0, -4)
	if foe != null and is_instance_valid(foe):
		pos = foe.global_position
	SkillDatabase.apply_skills(h, idx, pos)

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body(hero_name, "flash")
	elif t == 90:
		h = bm.hero
		for e in get_tree().get_nodes_in_group("heroes"):
			if e != h and e.team != h.team and e.health > 0:
				foe = e
				break
		if foe != null:
			foe.global_position = h.global_position + Vector3(0, 0, -4.5)
			foe_hp0 = foe.health
		print("L hero=", h.display_name, " foe=", foe.display_name if foe != null else "none")
		h.mana = 9999
		_cast(1)
	elif t == 140:
		_cast(2)
	elif t == 190:
		if foe != null and is_instance_valid(foe):
			foe.global_position = h.global_position + Vector3(0, 0, -4.5)
			foe_hp0 = foe.health
		_cast(3)
		var high := 0
		for c in h.get_parent().get_children():
			if c is Bullet and c.global_position.y > 6.0:
				high += 1
		print("L ult_bullets_high=", high)
	elif t == 230:
		_cast(3)
	elif t == 250:
		var drop_hits := 0
		for c in h.get_parent().get_children():
			if c is Bullet and c.drop_mode:
				drop_hits += 1
		print("L drop_bullets_alive=", drop_hits, " foe_hp_delta=", "%.1f" % (foe_hp0 - foe.health) if foe != null and is_instance_valid(foe) else "no foe")
	elif t == 300:
		print("L done hero=", h.display_name, " alive=", h.health > 0, " hp=", "%.0f" % h.health)
		get_tree().quit()
