{"command":"New-Item -ItemType Directory -Force devfx51, .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' '.cache\godot47.exe' -Force
@'
extends Node

func _ready() -> void:
	var vis := TurretMesh.visual("crystal", 0)
	var aabb := AABB()
	var first := true
	for c in vis.get_children():
		if c is MeshInstance3D and (c as MeshInstance3D).mesh != null:
			var mi := c as MeshInstance3D
			var box: AABB = mi.transform * mi.mesh.get_aabb()
			if first:
				aabb = box
				first = false
			else:
				aabb = aabb.merge(box)
		elif c is Node3D:
			for cc in c.get_children():
				if cc is MeshInstance3D and (cc as MeshInstance3D).mesh != null:
					var mi2 := cc as MeshInstance3D
					var box2: AABB = mi2.transform * mi2.mesh.get_aabb()
					if first:
						aabb = box2
						first = false
					else:
						aabb = aabb.merge(box2)
	print("L size=", aabb.size, " radius_x=", "%.2f" % (aabb.size.x * 0.5), " min_y=", "%.2f" % aabb.position.y)
	vis.queue_free()
	get_tree().quit()
