{"file_path":"C:\Users\18749\Documents\honor-king\scripts\net\NetSession.gd","new_string":"func _setup_peer() -> void:
	var is_web := OS.has_feature("web")
	match mode:
		Mode.HOST:
			if is_web:
				# 浏览器内无法监听端口（网页版只能当客户端，房间需由桌面主机开）
				printerr("[Net] 网页版无法创建房间，请使用桌面主机")
				mode = Mode.NONE
				return
			var peer := ENetMultiplayerPeer.new()
			var err := peer.create_server(host_port, 8)
			if err != OK:
				printerr("[Net] 主机创建失败 err=", err)
				mode = Mode.NONE
				return
			multiplayer.multiplayer_peer = peer
			players[1] = { "name": "主机" if cli_mode else "房主" }
			multiplayer.peer_connected.connect(_on_peer_connected)
			multiplayer.peer_disconnected.connect(_on_peer_disconnected)
			print("[Net] HOST 端口=", host_port, " 等待玩家加入…")
		Mode.CLIENT:
			var peer: MultiplayerPeer
			var err: int
			if is_web:
				# 网页版：浏览器只支持 WebSocket，连桌面主机需主机端另开 WS 服务
				var ws := WebSocketMultiplayerPeer.new()
				err = ws.create_client(_web_ws_url())
				peer = ws
			else:
				var enet := ENetMultiplayerPeer.new()
				err = enet.create_client(join_address, host_port)
				peer = enet
			if err != OK:
				printerr("[Net] 客户端创建失败 err=", err)
				mode = Mode.NONE
				return
			multiplayer.multiplayer_peer = peer
			multiplayer.connected_to_server.connect(_on_connected_to_server)
			multiplayer.connection_failed.connect(_on_connection_failed)
			multiplayer.peer_disconnected.connect(_on_peer_disconnected)
			print("[Net] CLIENT 连接 ", join_address, ":", host_port, " …")
			_ensure_overlay()
		_:
			return

# 网页版联机地址：ws://<join_address>:<host_port>；支持 URL 参数 ?host=ip:port 覆盖
func _web_ws_url() -> String:
	var addr := join_address
	var port := host_port
	if OS.has_feature("web"):
		var q := str(JavaScriptBridge.eval("window.location.search", true))
		var m := RegEx.create_from_string("[?&]host=([^&]+)").search(q)
		if m != null:
			var hp := m.get_string(1).uri_decode()
			if hp.contains(":"):
				addr = hp.get_slice(":", 0)
				port = int(hp.get_slice(":", 1))
			else:
				addr = hp
	return "ws://%s:%d" % [addr, port]
