@'
# serve_web.ps1 — 本地起静态服务器预览网页版（默认 build/web）
param(
    [int]$Port = 8080,
    [string]$Root = (Join-Path $PSScriptRoot '..\..\build\web')
)
$root = (Resolve-Path $Root -ErrorAction Stop).Path
$index = Join-Path $root 'index.html'
if (-not (Test-Path $index)) { Write-Error "找不到 $index，请先导出 Web：`n  godot --headless --path . --export-release Web build/web/index.html"; exit 1 }

$py = $null
foreach ($cand in @('python', 'py', 'python3')) {
    $cmd = Get-Command $cand -ErrorAction SilentlyContinue
    if ($cmd) { $py = $cmd.Source; break }
}
if (-not $py) { Write-Error '需要 Python3 来起静态服务器（或改用任意静态服务器指向 build/web）'; exit 1 }

Write-Host "网页版预览： http://127.0.0.1:$Port/  (Ctrl+C 停止)"
Write-Host "注意：用 http://127.0.0.1 或 localhost 打开，file:// 无法运行 WebGL/WASM"
Push-Location $root
try { & $py -m http.server $Port --bind 127.0.0.1 } finally { Pop-Location }
'@ | Set-Content -Encoding UTF8 scripts\dev\serve_web.ps1
New-Item -ItemType Directory -Force build\web, .cache | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' '.cache\godot47.exe' -Force
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','--export-release','Web','build/web/index.html' -PassThru -RedirectStandardOutput 'build\web_export.out' -RedirectStandardError 'build\web_export.err'
$d = $a.WaitForExit(1800000); if (-not $d) { $a.Kill(); "EXPORT TIMEOUT" }
"exit=$($a.ExitCode)"
Get-Content build\web_export.out -ErrorAction SilentlyContinue | Select-Object -Last 8
"--- err ---"
Get-Content build\web_export.err -ErrorAction SilentlyContinue | Select-Object -Last 12","description":"Add serve script and export web build","timeoutMs":1900000}

