func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _mat_info(mi) -> String:
	if mi == null or not is_instance_valid(mi):
		return "null"
	var m = mi.material_override
	if m is ShaderMaterial:
		var sm := m as ShaderMaterial
		return "shaderMat(code=%d,col=%s,dash=%s)" % [sm.shader.code.length(), str(sm.get_shader_parameter("ring_color")), str(sm.get_shader_parameter("dash_count"))]
	return str(m)

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 90:
		# 塔范围圈
		var turrets := get_tree().get_nodes_in_group("turrets")
		if turrets.size() > 0:
			var tp = turrets[0]
			var ring = tp.get_node_or_null("RangeRing")
			print("L turret_rings=", turrets.size(), " ring=", _mat_info(ring), " radius=", ring.scale.x if ring else -1.0)
		# 玩家攻击范围圈
		var h = bm.hero
		print("L hero_ring=", _mat_info(h.attack_range_ring), " scale_x=", "%.2f" % h.attack_range_ring.scale.x)
		# 野怪活动圈
		var found := 0
		for c in bm.get_children():
			if c is JungleMonster:
				var ar = c.get_node_or_null("ActivityRing")
				if ar != null:
					found += 1
					if found == 1:
						print("L jungle_ring=", _mat_info(ar), " radius=", "%.1f" % ar.scale.x)
		print("L jungle_rings=", found)
		# shader 自身可加载/可编译
		var sh: Shader = load("res://shaders/fx_ground_ring.gdshader")
		print("L shader_ok=", sh != null, " code_len=", sh.code.length() if sh else 0)
		get_tree().quit()
