{"command":"@'
extends Node

var t := 0
var bm = null
var r1: MeshInstance3D
var r2: MeshInstance3D

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 150:
		var base: Vector3 = bm.hero.global_position
		r1 = MeshFactory.create_ground_ring(3.25, Color(1, 1, 1, 0.32), 96.0)
		add_child(r1); r1.global_position = base + Vector3(0, 0.03, 0)
		r2 = MeshFactory.create_ground_ring(9.4, Color(1.0, 0.9, 0.35, 0.45))
		add_child(r2); r2.global_position = base + Vector3(0, 0.03, 0)
		print("L rings_built")
	elif t == 200:
		get_tree().paused = true
		_compare()

func _snap() -> Image:
	await RenderingServer.frame_post_draw
	return get_viewport().get_texture().get_image()

func _compare() -> void:
	var a: Image = await _snap()
	var av := a.get_region(Rect2i(0, 0, a.get_width(), a.get_height()))
	r1.visible = false
	r2.visible = false
	var b: Image = await _snap()
	var diff := 0
	var maxd := 0.0
	var ring_px := 0
	for y in range(0, av.get_height(), 2):
		for x in range(0, av.get_width(), 2):
			var ca := av.get_pixel(x, y)
			var cb := b.get_pixel(x, y)
			var d: float = abs(ca.r - cb.r) + abs(ca.g - cb.g) + abs(ca.b - cb.b)
			if d > 0.02:
				diff += 1
				if d > maxd: maxd = d
				if d > 0.05: ring_px += 1
	print("L diff_px=", diff, " strong_px=", ring_px, " max_diff=", "%.3f" % maxd,
		" sampled=", (av.get_width()/2) * (av.get_height()/2))
	get_tree().paused = false
	get_tree().quit()
