{"command":"@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("兰陵王", "flash")
	elif t == 70:
		var h = bm.hero
		var tc = get_node_or_null("/root/TouchController")
		print("L lvl=", h.level, " levels=", h.skill_levels, " has4=", h.skills[3] != null)
		var ex = tc._extra_skill_button
		print("L 4th@lvl1 max=", ex.max_level, " lvl=", ex.skill_level, " visible=", ex.visible, " name=", ex.display_name)
		# 升到4级
		for k in 3:
			h.level_up()
		print("L after_level_up lvl=", h.level, " levels=", h.skill_levels)
	elif t == 85:
		var h = bm.hero
		var tc = get_node_or_null("/root/TouchController")
		var ex = tc._extra_skill_button
		print("L 4th@lvl4 max=", ex.max_level, " lvl=", ex.skill_level, " visible=", ex.visible, " name=", ex.display_name, " art=", (str(ex.art_skill.skill_name) if ex.art_skill else "null"))
		# 主动装备：塞两件主动装
		h.equipment_slots.append("golden_body")
		h.equipment_slots.append("purify")
		h._apply_equipment_bonuses()
	elif t == 100:
		var tc = get_node_or_null("/root/TouchController")
		var n := 0
		for ab in tc._active_equip_buttons:
			print("L active[", n, "] cls=", ab.get_class(), " visible=", ab.visible, " item=", ab.item_name, " tier=", ab.item_tier, " name=", ab.display_name, " cd=", "%.2f" % ab.cd_ratio, "/", "%.0f" % ab.cd_total)
			n += 1
		get_tree().quit()
