{"command":"@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false   # 探针跳过开场流程，强制解除暂停
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("兰陵王", "flash")
	elif t == 45:
		var h = bm.hero
		var tc = get_node_or_null("/root/TouchController")
		var ex = tc._extra_skill_button
		print("L lvl1 max=", ex.max_level, " skill_lvl=", ex.skill_level, " vis=", ex.visible, " name=", ex.display_name, " root_vis=", tc._gameplay_root.visible)
		for k in 3:
			h.level_up()
		print("L hero_lvl=", h.level, " levels=", h.skill_levels)
	elif t == 60:
		var tc = get_node_or_null("/root/TouchController")
		var ex = tc._extra_skill_button
		print("L lvl4 max=", ex.max_level, " skill_lvl=", ex.skill_level, " vis=", ex.visible)
		bm.hero.equipment_slots.append("golden_body")
		bm.hero.equipment_slots.append("purify")
		bm.hero._apply_equipment_bonuses()
	elif t == 75:
		var tc = get_node_or_null("/root/TouchController")
		var n := 0
		for ab in tc._active_equip_buttons:
			print("L active", n, " visible=", ab.visible, " item=", ab.item_name, " tier=", ab.item_tier, " name=", ab.display_name, " cd=", "%.2f" % ab.cd_ratio, " total=", "%.0f" % ab.cd_total, " maxlevel=", ab.max_level)
			n += 1
		get_tree().quit()
