Shader `shaders/fx_shadow_path.gdshader`:

```glsl
shader_type spatial;
// 暗影之径：分路上的暗影能量覆盖层（紫色暗雾 + 双发光边线 + 沿路流动的能量脉络 + 心跳脉冲）
render_mode unshaded, blend_mix, depth_draw_never, cull_disabled;

uniform vec4 shadow_tint : source_color = vec4(0.42, 0.20, 0.85, 1.0);
uniform vec4 vein_tint : source_color = vec4(0.72, 0.45, 1.0, 1.0);
uniform float intensity : hint_range(0.0, 1.5) = 1.0;   // 淡入淡出
uniform float base_alpha : hint_range(0.0, 1.0) = 0.22;
uniform float edge_alpha : hint_range(0.0, 1.5) = 0.75;
uniform float vein_alpha : hint_range(0.0, 1.5) = 0.55;
uniform float flow_speed = 1.6;
uniform float edge_pos : hint_range(0.5, 1.0) = 0.93;
uniform float edge_width : hint_range(0.005, 0.1) = 0.030;

void fragment() {
	vec2 uv = UV;
	float across = abs(uv.x - 0.5) * 2.0;         // 0=路中 1=路缘
	// 基底暗雾：中间薄、靠边更浓（暗影从两侧渗上来）
	float base = mix(0.35, 1.0, smoothstep(0.05, 1.0, across));
	// 双发光路缘
	float edge = 1.0 - smoothstep(0.0, edge_width, abs(across - edge_pos));
	// 沿路流动的能量脉络：两层错相正弦 + 横向调制，形成流动的暗影纹路
	float flow = TIME * flow_speed;
	float s1 = sin(uv.y * 46.0 - flow) * 0.5 + 0.5;
	float s2 = sin(uv.y * 19.0 + flow * 1.7 + across * 4.0) * 0.5 + 0.5;
	float vein = smoothstep(0.62, 0.98, s1 * 0.55 + s2 * 0.45);
	// 路面横向扫过的波动带（像暗影在路面上推进）
	float sweep = smoothstep(0.55, 1.0, sin(uv.y * 7.0 - TIME * 0.9) * 0.5 + 0.5) * (1.0 - across * 0.5);
	// 心跳
	float pulse = 0.85 + 0.15 * sin(TIME * 2.0);
	vec3 col = mix(shadow_tint.rgb, vein_tint.rgb, clamp(vein + sweep * 0.35, 0.0, 1.0));
	ALBEDO = col * pulse;
	ALPHA = clamp((base * base_alpha + edge * edge_alpha + vein * vein_alpha) * intensity, 0.0, 1.0);
}
```

