{"command":"@'
extends Node

var t := 0
var bm = null
var hp = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
	hp = preload("res://scripts/ui/HeroPreview.gd").new()
	hp.render_size = Vector2i(360, 440)
	hp.size = Vector2(360, 440)
	add_child(hp)

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 10:
		hp.set_hero("亚瑟")
	elif t == 25:
		bm = get_tree().get_first_node_in_group("battle_manager")
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm._start_game_body("亚瑟", "flash")
	elif t == 40:
		bm.shadow_path_timers[0] = {}
		bm.shadow_path_timers[0][1] = 60.0
		bm._set_shadow_path_visual(1, true)
		hp.set_orbit_enabled(true)
	elif t == 55:
		# 手动推进淡入（无头下主循环未跑战斗帧，这里直接步进）
		for k in 6:
			bm._update_shadow_path_fades(0.1)
		var mat: ShaderMaterial = bm.shadow_path_mats.get(1)
		print("L fade_in intensity=", "%.2f" % float(mat.get_shader_parameter("intensity")))
		# 相机滑动：模拟水平+垂直拖动
		var p0: Vector3 = hp._camera.position
		var ev := InputEventScreenTouch.new(); ev.index = 0; ev.pressed = true; ev.position = Vector2(100, 100)
		hp._on_orbit_input(ev)
		var dr := InputEventScreenDrag.new(); dr.index = 0; dr.position = Vector2(240, 150)
		hp._on_orbit_input(dr)
		var rel := InputEventScreenTouch.new(); rel.index = 0; rel.pressed = false; rel.position = Vector2(240, 150)
		hp._on_orbit_input(rel)
		hp._apply_orbit()
		var p1: Vector3 = hp._camera.position
		print("L orbit yaw=", "%.2f" % hp._orbit_yaw, " pitch=", "%.3f" % hp._orbit_pitch, " cam0=", "%.2f,%.2f,%.2f" % [p0.x, p0.y, p0.z], " cam1=", "%.2f,%.2f,%.2f" % [p1.x, p1.y, p1.z], " dist0=", "%.2f" % (p0 - hp._orbit_focus).length(), " dist1=", "%.2f" % (p1 - hp._orbit_focus).length())
		# 俯仰夹紧
		var big := InputEventScreenDrag.new(); big.index = 0; big.position = Vector2(0, 5000)
		hp._on_orbit_input(big)
		print("L pitch_clamped=", "%.3f" % hp._orbit_pitch)
		bm._set_shadow_path_visual(1, false)
	elif t == 80:
		for k in 8:
			bm._update_shadow_path_fades(0.1)
		var mat: ShaderMaterial = bm.shadow_path_mats.get(1)
		var ovs: Array = bm.shadow_path_overlays.get(1, [])
		print("L fade_out intensity=", "%.3f" % float(mat.get_shader_parameter("intensity")), " vis=", ovs.map(func(o): return o.visible), " fade_keys=", bm.shadow_path_fade.keys())
		get_tree().quit()
