Get-Content devfx55\q.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' -Context 0,4 | Select-Object -First 3 | ForEach-Object { $_.Line.Trim(); $_.Context.PostContext | ForEach-Object { "   " + $_.Trim() } }","description":"Re-probe with manual fade stepping and enabled orbit","timeoutMs":300000}

