@'
extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 120:
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._on_hero_selected("亚瑟")
		var hp = bm.sel_preview_3d
		print("L select orbit_enabled=", hp.orbit_enabled, " mouse_filter=", hp.mouse_filter, " cam=", "%.2f,%.2f,%.2f" % [hp._camera.position.x, hp._camera.position.y, hp._camera.position.z])
		var ev := InputEventScreenTouch.new(); ev.index = 0; ev.pressed = true; ev.position = Vector2(100, 100)
		hp._on_orbit_input(ev)
		var dr := InputEventScreenDrag.new(); dr.index = 0; dr.position = Vector2(260, 170)
		hp._on_orbit_input(dr)
		hp._apply_orbit()
		print("L select orbit yaw=", "%.2f" % hp._orbit_yaw, " cam=", "%.2f,%.2f,%.2f" % [hp._camera.position.x, hp._camera.position.y, hp._camera.position.z])
	elif t == 150:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm._start_game_body("亚瑟", "flash")
	elif t == 200:
		bm.shadow_path_timers[0] = {}
		bm.shadow_path_timers[0][1] = 60.0
		bm._set_shadow_path_visual(1, true)
		for k in 8:
			bm._update_shadow_path_fades(0.1)
		# 把相机抬到中路看一眼
		var cam = bm.get_viewport().get_camera_3d()
		if cam:
			cam.position = Vector3(-18, 22, 18)
			cam.look_at(Vector3(-30, 0, 30))
		print("L shadow intensity=", "%.2f" % float((bm.shadow_path_mats[1] as ShaderMaterial).get_shader_parameter("intensity")))
	elif t == 215:
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_png("res://devfx55/shot.png")
		print("L shot_ok")
		get_tree().quit()
