content.arguments:
{"command":"@'
extends Node

var t := 0
var bm = null
var tr = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 90:
		var h = bm.hero
		for x in get_tree().get_nodes_in_group("turrets"):
			if x.team != h.team:
				tr = x
				break
		h.global_position = tr.global_position + Vector3(6, 0, 0)
		tr._update_range_preview()
		var cam = get_viewport().get_camera_3d()
		if cam:
			cam.position = tr.global_position + Vector3(8, 26, 22)
			cam.look_at(tr.global_position)
		get_tree().paused = true
		_compare()
	elif t == 200:
		get_tree().quit()

func _snap() -> Image:
	await RenderingServer.frame_post_draw
	return get_viewport().get_texture().get_image()

func _compare() -> void:
	var ring = tr.get_node_or_null("RangeRing")
	ring.visible = false
	var a: Image = await _snap()
	ring.visible = true
	var b: Image = await _snap()
	var diff := 0
	var strong := 0
	for y in range(0, a.get_height(), 3):
		for x in range(0, a.get_width(), 3):
			var ca := a.get_pixel(x, y)
			var cb := b.get_pixel(x, y)
			var d: float = absf(ca.r - cb.r) + absf(ca.g - cb.g) + absf(ca.b - cb.b)
			if d > 0.02:
				diff += 1
				if d > 0.08:
					strong += 1
	print("L ring_px=", diff, " strong_px=", strong, " sampled=", (a.get_width()/3) * (a.get_height()/3), " ring_y=", "%.2f" % ring.position.y)
	get_tree().paused = false
	get_tree().quit()
