	draw_arc(bc, br, 0.0, TAU, 26, Color(accent.r, accent.g, accent.b, 0.85), 2.0 * k, true)
	UiKit.text(self, Vector2(bc.x - br, bc.y + 9.0 * k), str(rank), int(28.0 * k), accent.lightened(0.35),
		HORIZONTAL_ALIGNMENT_CENTER, br * 2.0)
