	UiKit.text(self, Vector2(x + gr * 2.0 + 5.0, baseline), txt, font_size, col.lightened(0.32))
	var w := UiKit.font().get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, font_size).x
	return x + gr * 2.0 + w + 16.0

