{"file_path":"C:\Users\18749\Documents\honor-king\scripts\ui\UI_Manager.gd","new_string":"	var collapsed := false          # 点按收起：只留右侧装备图标
	var auto_collapsed := false     # 因金币不足自动收起；金币够了自动展开
	var user_toggled := false       # 用户手动点过折叠/展开：金币状态没变前不再被自动逻辑覆盖
	var _last_afford := false
	var _glow_t := 0.0              # 可购买发光拖尾相位（仅 affordable 时推进）
	func _process(delta: float) -> void:
		if affordable():
			_glow_t += delta
			queue_redraw()
	func affordable() -> bool:
		return cost > 0 and gold >= cost
	func set_collapsed_for_gold(should_collapse: bool) -> void:
		var aff := affordable()
		# 手动折叠/展开优先：只要「买得起」状态没变，就保持玩家的选择（否则刚展开又被自动收起，看起来点了没反应）
		if user_toggled:
			if aff == _last_afford:
				return
			user_toggled = false
		_last_afford = aff
		if should_collapse:
			if not collapsed:
				collapsed = true
				auto_collapsed = true
				offset_left = -124.0
				queue_redraw()
		elif auto_collapsed:
			collapsed = false
			auto_collapsed = false
			offset_left = -470.0
			queue_redraw()
	func _gui_input(ev: InputEvent) -> void:
		if ev is InputEventMouseButton and (ev as InputEventMouseButton).pressed \
				and (ev as InputEventMouseButton).button_index == MOUSE_BUTTON_LEFT:
			collapsed = not collapsed
			auto_collapsed = false
			user_toggled = true
			_last_afford = affordable()
			offset_left = -124.0 if collapsed else -470.0   # 收起时缩成图标大小，避免挡住后方面板
