{"command":"@'
extends Node

var t := 0
var bm = null
var h = null
var foe = null
var minion = null
var turret = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("沈梦溪", "flash")
	elif t == 90:
		h = bm.hero
		var base: Vector3 = h.global_position
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Hero and e.team != h.team and foe == null:
				foe = e
			elif e is Minion and e.team != h.team and minion == null:
				minion = e
			elif e is Turret and e.team != h.team and turret == null:
				turret = e
		foe.global_position = base + Vector3(3.0, 0, 0)
		minion.global_position = base + Vector3(-1.5, 0, 0)
		turret.global_position = base + Vector3(0, 0, 2.0)
		var cam := get_viewport().get_camera_3d()
		print("L cam=", cam != null)
		if cam:
			print("L cam_pos=", cam.global_position)
			var scr := cam.unproject_position(foe.global_position)
			var raw: Vector3 = h._screen_ray_world(scr)
			print("L scr=", scr, " raw=", raw, " raw_d_foe=", "%.2f" % raw.distance_to(foe.global_position))
		print("L nearest_hero=", h._nearest_skill_target(6.0) == foe)
		var sk = h.skills[0]
		print("L skill_type=", sk.type, " cast_range=", sk.cast_range)
		var aim: Vector3 = h._compute_skill_aim(Vector2.ZERO, sk, false)
		print("L tap_aim_self_dist=", "%.2f" % aim.distance_to(h.global_position), " d_foe=", "%.2f" % aim.distance_to(foe.global_position), " d_minion=", "%.2f" % aim.distance_to(minion.global_position), " d_turret=", "%.2f" % aim.distance_to(turret.global_position))
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx62\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--headless','--path','.','res://devfx62/probe.tscn','--quit-after','140' -PassThru -RedirectStandardOutput 'devfx62\p2.out' -RedirectStandardError 'devfx62\p2.err'
$d = $a.WaitForExit(200000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx62\p2.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== err ==="
Get-Content devfx62\p2.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' -Context 0,4 | Select-Object -First 2 | ForEach-Object { $_.Line.Trim(); $_.Context.PostContext | ForEach-Object { "   " + $_.Trim() } }","description":"Diagnose camera ray and aim","timeoutMs":300000}

