Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' '.cache\godot47.exe' -Force
@'
extends Node

func _ready() -> void:
	var m = load("res://model/hero/character-male-c.glb").instantiate()
	add_child(m)
	var ap := _find_ap(m)
	print("L anims=", ap.get_animation_list() if ap else "NONE")
	for a in ["sit", "drive", "idle", "attack-melee-right", "holding-right-shoot"]:
		if ap and ap.has_animation(a):
			print("L len(", a, ")=", "%.2f" % ap.get_animation(a).length, " loop=", ap.get_animation(a).loop_mode)
	var skel := _find_skel(m)
	if skel:
		print("L bones=", skel.get_bone_count())
		var names := []
		for i in range(skel.get_bone_count()):
			names.append(skel.get_bone_name(i))
		print("L bone_names=", names)
		for pose_anim in ["idle", "sit", "drive"]:
			if ap and ap.has_animation(pose_anim):
				ap.play(pose_anim)
				ap.seek(ap.get_animation(pose_anim).length * 0.6, true)
				ap.pause()
				var out := []
				for i in range(skel.get_bone_count()):
					var bn := skel.get_bone_name(i)
					if bn in ["hips", "pelvis", "root", "torso", "head", "leg-left", "leg-right", "spine"]:
						out.append("%s=%s" % [bn, str(skel.get_bone_global_pose(i).origin)])
				print("L pose[", pose_anim, "] ", out)
	var chair = load("res://model/hero/wheelchair.glb").instantiate()
	add_child(chair)
	var mi: MeshInstance3D = _find_mesh(chair)
	if mi:
		var aabb: AABB = mi.get_aabb()
		print("L chair_aabb=", aabb)
		var verts: PackedVector3Array = mi.mesh.surface_get_arrays(0)[Mesh.ARRAY_VERTEX]
		var hist := {}
		for v in verts:
			var k := int(round(v.y * 100.0 / 5.0))
			hist[k] = hist.get(k, 0) + 1
		var keys := hist.keys(); keys.sort()
		var lines := []
		for k in keys:
			lines.append("y=%.2f n=%d" % [float(k) * 0.05, hist[k]])
		print("L chair_yhist=", lines)
	get_tree().quit()

func _find_ap(n: Node) -> AnimationPlayer:
	if n is AnimationPlayer: return n
	for c in n.get_children():
		var r := _find_ap(c)
		if r: return r
	return null

func _find_skel(n: Node) -> Skeleton3D:
	if n is Skeleton3D: return n
	for c in n.get_children():
		var r := _find_skel(c)
		if r: return r
	return null

func _find_mesh(n: Node) -> MeshInstance3D:
	if n is MeshInstance3D: return n
	for c in n.get_children():
		var r := _find_mesh(c)
		if r: return r
	return null
