extends Node

var done := false

func _ready() -> void:
	var body = load("res://model/hero/character-male-c.glb").instantiate()
	add_child(body)
	var ap := _find_ap(body)
	var skel := _find_skel(body)
	var chair = load("res://model/hero/wheelchair.glb").instantiate()
	add_child(chair)
	var cm: MeshInstance3D = _find_mesh(chair)
	if ap and skel and cm:
		ap.play("wheelchair-sit")
		ap.seek(0.08, true)
		ap.pause()
		await get_tree().process_frame
		await get_tree().process_frame
		var st := skel.get_global_transform()
		var out := []
		for i in range(skel.get_bone_count()):
			var bn := skel.get_bone_name(i)
			if bn in ["root", "torso", "head", "leg-left"]:
				var w: Vector3 = st * skel.get_bone_global_pose(i).origin
				out.append("%s=%s" % [bn, str(w)])
		print("L body_world ", out)
		var ct: Transform3D = cm.get_global_transform()
		var aabb: AABB = cm.get_aabb()
		print("L chair_world_aabb y=[%.4f, %.4f] z=[%.4f, %.4f]" % [
			(ct * aabb.position).y, (ct * (aabb.position + aabb.size)).y,
			(ct * aabb.position).z, (ct * (aabb.position + aabb.size)).z])
		# 座板高度：取顶点 y 直方图峰值（0.18~0.24 视为座面）
		var verts: PackedVector3Array = cm.mesh.surface_get_arrays(0)[Mesh.ARRAY_VERTEX]
		var seat := 0.0
		var n := 0
		for v in verts:
			var w: Vector3 = ct * v
			if w.y > 0.16 and w.y < 0.26:
				seat += w.y
				n += 1
		print("L chair_seat_y=", "%.4f" % (seat / maxf(n, 1)), " n=", n)
	get_tree().quit()

