{"command":"@'
extends Node

const HeroWeapons = preload("res://scripts/core/HeroWeapons.gd")

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("狄仁杰", "flash")
	elif t == 90:
		var h = bm.hero
		var hm: Node3D = h.get_node_or_null("HeroModel")
		print("L inbattle hero=", h.display_name, " children=", _names(hm))
		for c in hm.get_children():
			print("L   ", c.name, " pos=", c.position, " scale=", c.scale)
		print("L inbattle aabb=", _aabb(hm), " anim=", h.anim_player.current_animation if h.anim_player else "none")
		if h.anim_player:
			print("L clip_len idle=", "%.2f" % h.anim_player.get_animation("idle").length, " walk=", "%.2f" % h.anim_player.get_animation("walk").length, " die=", "%.2f" % h.anim_player.get_animation("die").length)
		for n in ["马可波罗", "太乙真人"]:
			var body = load(HeroWeapons.WHEELCHAIR_BODY[n]).instantiate()
			var root := Node3D.new()
			root.name = n
			add_child(root)
			body.scale = Vector3(3, 3, 3)
			root.add_child(body)
			HeroWeapons.mount_wheelchair(root, body, n, 3.0)
			print("L build ", n, " children=", _names(root), " body_y=", "%.3f" % body.position.y, " aabb=", _aabb(root))
		get_tree().quit()

func _names(n: Node) -> Array:
	var a := []
	for c in n.get_children(): a.append(str(c.name))
	return a

func _aabb(n: Node3D) -> String:
	var lo := Vector3(1e9, 1e9, 1e9)
	var hi := Vector3(-1e9, -1e9, -1e9)
	var any := [false]
	_walk(n, lo, hi, any)
	if not any[0]: return "none"
	return "y[%.2f,%.2f] x[%.2f,%.2f]" % [lo.y, hi.y, lo.x, hi.x]

func _walk(n: Node, lo: Vector3, hi: Vector3, any: Array) -> void:
	if n is MeshInstance3D and n.mesh:
		var xf: Transform3D = n.global_transform
		var b: AABB = n.mesh.get_aabb()
		for i in range(8):
			var p: Vector3 = xf * b.get_endpoint(i)
			lo.x = minf(lo.x, p.x); lo.y = minf(lo.y, p.y); lo.z = minf(lo.z, p.z)
			hi.x = maxf(hi.x, p.x); hi.y = maxf(hi.y, p.y); hi.z = maxf(hi.z, p.z)
			any[0] = true
	for c in n.get_children():
		_walk(c, lo, hi, any)
