extends Node

var t := 0
var bm = null

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 20:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("狄仁杰", "flash")
	elif t == 60:
		var hm: Node3D = bm.hero.get_node_or_null("HeroModel")
		for c in hm.get_children():
			print("L child=", c.name, " pos=", c.position, " scale=", c.scale)
		print("L acc_box=", _box(hm.get_node_or_null("aid-glasses2")))
		get_tree().quit()

func _box(n: Node3D) -> String:
	if n == null: return "none"
	var lo := Vector3(1e9, 1e9, 1e9)
	var hi := Vector3(-1e9, -1e9, -1e9)
	var found := false
	var stack := [n]
	while not stack.is_empty():
		var cur: Node = stack.pop_back()
		if cur is MeshInstance3D and (cur as MeshInstance3D).mesh:
			var xf: Transform3D = (cur as Node3D).global_transform
			var bb: AABB = (cur as MeshInstance3D).mesh.get_aabb()
			for i in range(8):
				var p: Vector3 = xf * bb.get_endpoint(i)
				lo = Vector3(minf(lo.x, p.x), minf(lo.y, p.y), minf(lo.z, p.z))
				hi = Vector3(maxf(hi.x, p.x), maxf(hi.y, p.y), maxf(hi.z, p.z))
				found = true
		for c2 in cur.get_children():
			stack.append(c2)
	if not found: return "none"
	return "x[%.2f,%.2f] y[%.2f,%.2f] z[%.2f,%.2f]" % [lo.x, hi.x, lo.y, hi.y, lo.z, hi.z]
