{"file_path":"C:\Users\18749\Documents\honor-king\scripts\mobile\TouchController.gd","new_string":"	var reach: float = hero.attack_range * 0.01
	var list: Array = []
	for ent in get_tree().get_nodes_in_group("entities"):
		if ent == hero or not (ent is GameEntity) or ent.health <= 0 or ent.team == hero.team:
			continue
		# 锁敌条只锁定英雄：小兵/防御塔/野怪一律不上头像（用下方推塔/小兵优先级键处理）
		if not (ent is Hero):
			continue
		if (ent as Hero).is_invisible_to_enemy() or (ent as Hero).is_untargetable_by_enemies():
			continue   # 隐身/不可选中的英雄不该出现在索敌条上
		if hero.global_position.distance_to(ent.global_position) - ent.body_radius > reach:
			continue
		list.append(ent)
	if list.is_empty():
		_picker_root.visible = false
		return   # 范围内没有敌方英雄时隐藏
	if hero.manual_target != null and not is_instance_valid(hero.manual_target):
		hero.manual_target = null","old_string":"	var reach: float = hero.attack_range * 0.01
	var list: Array = []
	for ent in get_tree().get_nodes_in_group("entities"):
		if ent == hero or not (ent is GameEntity) or ent.health <= 0 or ent.team == hero.team:
			continue
		if not (ent is Hero or ent is Minion or ent is Turret or ent is JungleMonster):
			continue   # 排除墙体/草丛/治疗包等
		if ent is Hero and ((ent as Hero).is_invisible_to_enemy() or (ent as Hero).is_untargetable_by_enemies()):
			continue   # 隐身/不可选中的英雄不该出现在索敌条上
		if hero.global_position.distance_to(ent.global_position) - ent.body_radius > reach:
			continue
		list.append(ent)
	if list.size() < 2:
		_picker_root.visible = false
		return   # 只有一个敌人时不需要手动索敌（自动打最低血即可）"}

