{"command":"New-Item -ItemType Directory -Force .cache, devfx66 | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' -Destination '.cache\godot47.exe' -Force
@'
extends Node

var t := 0

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 25:
		var sh := MeshFactory.build_shuriken(4, 0.045, 0.215, 0.030, 26.0)
		print("L shuriken surfaces=", sh.get_surface_count(), " verts=", sh.surface_get_array_len(0), " aabb=", sh.get_aabb().size)
		var wheel := MeshFactory.build_saw_wheel(0.92, 1.34, 0.11, 28, 0.14, 4, 0.62)
		print("L wheel surfaces=", wheel.get_surface_count(), " verts=", wheel.surface_get_array_len(0), " aabb=", wheel.get_aabb().size)
		var dart: Node3D = Vfx._lyf_make_dart(Color(1, 0.52, 0.16))
		print("L dart_children=", _names(dart), " spin_children=", _names(dart.get_node("Spin")))
		print("L dart_aabb=", _aabb(dart))
		add_child(dart)
		dart.position = Vector3(0, 2, 0)
		Vfx.lyf_throw_dart(Vector3(0, 1.2, 0), Vector3(6, 1.2, 2))
		var blade: Node3D = SkillDatabase._lyf_slide_blade(self, Vector3(0, 0, 0), Vector3(6, 0, 0), 0.3)
		print("L blade_children=", _names(blade), " mesh_instances=", _count_mi(blade), " aabb=", _aabb(blade))
		var zone: Node3D = SkillDatabase._lyf_storm_visual(self, Vector3(10, 0, 10), 3.0)
		print("L zone_children=", _names(zone), " zone_mi=", _count_mi(zone))
	elif t == 60:
		print("L after_frames fx_nodes=", get_tree().get_nodes_in_group("vfx").size())
		get_tree().quit()

func _names(n: Node) -> Array:
	var a := []
	for c in n.get_children(): a.append(str(c.name))
	return a

func _count_mi(n: Node) -> int:
	var c := 0
	var st := [n]
	while not st.is_empty():
		var cur: Node = st.pop_back()
		if cur is MeshInstance3D: c += 1
		for k in cur.get_children(): st.append(k)
	return c

func _aabb(n: Node3D) -> String:
	var lo := Vector3(1e9, 1e9, 1e9)
	var hi := Vector3(-1e9, -1e9, -1e9)
	var any := false
	var st := [n]
	while not st.is_empty():
		var cur: Node = st.pop_back()
		if cur is MeshInstance3D and (cur as MeshInstance3D).mesh:
			var xf: Transform3D = (cur as Node3D).global_transform
			var bb: AABB = (cur as MeshInstance3D).mesh.get_aabb()
			for i in range(8):
				var p: Vector3 = xf * bb.get_endpoint(i)
				lo = Vector3(minf(lo.x, p.x), minf(lo.y, p.y), minf(lo.z, p.z))
				hi = Vector3(maxf(hi.x, p.x), maxf(hi.y, p.y), maxf(hi.z, p.z))
				any = true
		for k in cur.get_children(): st.append(k)
	if not any: return "none"
	return "size=(%.2f,%.2f,%.2f)" % [hi.x - lo.x, hi.y - lo.y, hi.z - lo.z]
