@'
extends Node

var vp: SubViewport
var pop: Control
var t := 0
var bm = null
var stage := 0

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	vp = SubViewport.new()
	vp.size = Vector2i(240, 120)
	vp.transparent_bg = true
	vp.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	add_child(vp)
	var Pop = load("res://scripts/ui/UI_Manager.gd").ValuePopup
	pop = Pop.new()
	pop.setup("+120g", "thumb", Color(1.0, 0.87, 0.40), 1.0, 30, "coin")
	pop.position = Vector2(20, 30)
	vp.add_child(pop)
	print("L popup size=", pop.size, " icon_w=", pop._icon_w())

func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 10:
		var img: Image = vp.get_texture().get_image()
		print("L popup_bbox=", _bbox(img, 240, 120))
		var w1: float = 30.0
		print("L thumb_badge_ascii:")
		_ascii(img, Vector2i(20, 30), Vector2i(int(w1), int(pop.size.y)))
		img.save_png("res://devfx68/popup.png")
		add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
	elif t == 40:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 70:
		var h = bm.hero
		h.global_position = Vector3(0, 0.5, 0)
		bm.spawn_exp_orb(Vector3(4, 0, 4), h, 30)
		var orb = _find(bm, "ExpOrb")
		print("L orb_found=", orb != null, " orb_scale=", (orb.scale if orb else Vector3.ZERO), " trail=", (orb.get_node_or_null("VfxTrail") != null if orb else false), " orb_pos=", (orb.position if orb else Vector3.ZERO))
		set_meta("orb_id", orb.get_instance_id() if orb else 0)
	elif t == 100:
		var orb = instance_from_id(int(get_meta("orb_id", 0)))
		print("L orb_mid_pos=", (orb.position if orb else "gone"))
	elif t == 140:
		var orb = instance_from_id(int(get_meta("orb_id", 0)))
		print("L orb_end=", ("gone" if orb == null or not is_instance_valid(orb) else str(orb.position)))
		get_tree().quit()

func _find(n: Node, nm: String) -> Node:
	if str(n.name) == nm: return n
	for c in n.get_children():
		var r := _find(c, nm)
		if r: return r
	return null

func _bbox(img: Image, w: int, h: int) -> String:
	var lo := Vector2i(9999, 9999); var hi := Vector2i(-1, -1)
	for y in range(h):
		for x in range(w):
			if img.get_pixel(x, y).a > 0.08:
				lo = Vector2i(mini(lo.x, x), mini(lo.y, y)); hi = Vector2i(maxi(hi.x, x), maxi(hi.y, y))
	if hi.x < 0: return "empty"
	return "x=%d y=%d w=%d h=%d" % [lo.x, lo.y, hi.x - lo.x + 1, hi.y - lo.y + 1]

func _ascii(img: Image, origin: Vector2i, sz: Vector2i) -> void:
	var rows := 16
	var cols := 22
	for ry in range(rows):
		var line := ""
		for rx in range(cols):
			var x: int = origin.x + int(float(rx) / float(cols) * float(sz.x))
			var y: int = origin.y + int(float(ry) / float(rows) * float(sz.y))
			line += "#" if img.get_pixel(clampi(x, 0, 239), clampi(y, 0, 119)).a > 0.25 else "."
		print("L |", line, "|")
'@ | Set-Content -Encoding UTF8 devfx68\probe.gd
@'
[gd_scene load_steps=2 format=3]
[ext_resource type="Script" path="res://devfx68/probe.gd" id="1"]
[node name="Probe" type="Node"]
script = ExtResource("1")
'@ | Set-Content -Encoding UTF8 devfx68\probe.tscn
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx68/probe.tscn','--quit-after','200','--resolution','1600x1000' -PassThru -RedirectStandardOutput 'devfx68\o.out' -RedirectStandardError 'devfx68\o.err'
$d = $a.WaitForExit(240000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx68\o.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx68\o.err | Select-String -Pattern 'SCRIPT ERROR' -Context 0,2 | Select-Object -First 3 | ForEach-Object { $_.Line.Trim() }","description":"Probe popup badge and exp orb","timeoutMs":400000}

