{"command":"@'
extends Node
var t := 0
var bm = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("亚瑟", "flash")
	elif t == 60:
		bm.hero.global_position = Vector3(0, 0.5, 0)
		bm.spawn_exp_orb(Vector3(3, 0, 3), bm.hero, 20)
		var orb = _find(bm, "ExpOrb")
		if orb:
			var core: MeshInstance3D = orb.get_child(0)
			var halo: MeshInstance3D = orb.get_child(1)
			print("L core_r=", core.mesh.radius, " halo_r=", halo.mesh.radius, " trail_amt=", (orb.get_node("VfxTrail") as CPUParticles3D).amount, " trail_life=", (orb.get_node("VfxTrail") as CPUParticles3D).lifetime)
	elif t == 70:
		get_tree().quit()
func _find(n: Node, nm: String) -> Node:
	if str(n.name) == nm: return n
	for c in n.get_children():
		var r := _find(c, nm)
		if r: return r
	return null
