{"command":"@'
extends Node
var t := 0
var bm = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("刘禅", "flash")
	elif t == 200:
		var h = bm.hero
		var sk = SkillDatabase.get_skill("刘禅", 1)
		print("L skill_ids=", sk != null, " slot1=", (sk.get("skill_name") if sk else "-"))
	elif t == 210:
		var h = bm.hero
		h.global_position = Vector3(0, 0.5, 0)
		h.level = 15
		h.actual_attack_damage = 200.0
		for i in range(3):
			SkillDatabase.apply_skills(h, i + 1, h.global_position + Vector3(0, 0, 3.0))
			print("L cast slot=", i, " props_now=", get_tree().get_nodes_in_group("vfx_prop").size())
	elif t == 220:
		var props := get_tree().get_nodes_in_group("vfx_prop")
		print("L props_after_all=", props.size(), " fx_nodes=", get_tree().get_nodes_in_group("vfx_fx").size())
	elif t == 260:
		var gears := 0
		var st := [bm]
		while not st.is_empty():
			var cur: Node = st.pop_back()
			if cur is MeshInstance3D and (cur as MeshInstance3D).mesh is ArrayMesh: gears += 1
			for k in cur.get_children(): st.append(k)
		print("L arraymesh_total=", gears)
		get_tree().quit()
