		_gold_text(my_taken), _gold_text(my_heal), float(my_cc) / 10.0], UiKit.FS_MD, UiKit.C_TEXT_DIM))
	var rank_txt := _rank_text(rec.get("rank", {}))
	if rank_txt != "":
		h.add_child(_lab(rank_txt.trim_prefix(" · "), UiKit.FS_MD, UiKit.C_GOLD))
	return panel


