content.arguments:
{"command":"$f='scripts\core\BattleHistory.gd'
$c = Get-Content $f -Raw
$c = $c.Replace('const PATH := "user://battle_history.json"', 'const PATH := "res://devfx71/hist_test.json"')
Set-Content -Encoding UTF8 $f $c
@'
extends Node
var t := 0
var bm = null
var panel = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("狄仁杰", "flash")
	elif t == 200:
		for e in get_tree().get_nodes_in_group("heroes"):
			if e is Hero:
				e.last_hits = 42
				e.jungle_gold = 333
				e.damage_taken_from_heroes = 1234.0
				e.healing_done = 88.0
				e.cc_duration_dealt = 2.5
				e.turret_damage = 999.0
				if e.equipment_slots.is_empty():
					e.equipment_slots.append("infinity_edge")
		var p: Dictionary = BattleHistory.payload_from_battle(bm)
		p["rank"] = {"old_label": "白银III", "new_label": "白银II", "star_change": 1, "promoted": false, "demoted": false, "protected": false}
		BattleHistory.record(p, "单机")
		var all: Array = BattleHistory.all()
		print("L n=", all.size(), " keys=", all[0].keys())
		print("L turrets=", all[0].get("turrets"), " rank_new=", (all[0].get("rank", {}) as Dictionary).get("new_label"))
		var r: Dictionary = all[0]["rows"][0]
		print("L row_items=", r.get("items"), " lh=", r.get("lh"), " taken=", r.get("taken"), " cc=", r.get("cc"), " role=", r.get("role"), " turret=", r.get("turret"))
	elif t == 230:
		panel = BattleHistoryPanel.new()
		add_child(panel)
	elif t == 240:
		print("L panel_children=", panel.get_child_count(), " title=", (panel.get("_title") as Label).text)
		panel.call("_show_detail", 0)
	elif t == 250:
		var body: VBoxContainer = panel.get("_body")
		print("L detail_title=", (panel.get("_title") as Label).text, " body_children=", body.get_child_count())
		# 打印详情页的文本，确认分项数据真的画出来了
		var texts := []
		_collect(body, texts)
		for s in texts: print("L TXT ", s)
		get_tree().quit()
func _collect(n: Node, out: Array) -> void:
	if n is Label: out.append((n as Label).text)
	for c in n.get_children(): _collect(c, out)
