{"command":"New-Item -ItemType Directory -Force .cache, devfx72 | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' -Destination '.cache\godot47.exe' -Force
@'
extends Node
var t := 0
var bm = null
var target = null
var painter = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _find(n: Node, nm: String) -> Node:
	if str(n.name) == nm: return n
	for c in n.get_children():
		var r := _find(c, nm)
		if r: return r
	return null
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 200:
		var hero = bm.hero
		# 找一个敌方小兵
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Minion and not Config.is_ally(int(e.team)):
				target = e
				break
		print("L target=", target != null, " target_class=", (target.get_class() if target else "-"))
		if target:
			var hero_pos: Vector3 = target.global_position + Vector3(1.0, 0.0, 0.0)
			hero.global_position = Vector3(hero_pos.x, 0.6, hero_pos.z)
			hero.actual_attack_damage = 800.0
			target.health = 300.0
			target.max_health = 4000.0
			print("L minion_hp=", target.health, " armor=", target.armor, " hero_aa=", hero.actual_attack_damage)
			hero.global_position = target.global_position + Vector3(1.2, 0.6, 0.0)
			hero._perform_attack(target)
			print("L aa_target_set=", hero.aa_target == target, " t=", hero.aa_target_t)
	elif t == 206:
		painter = _find(bm, "WorldBars")
		print("L painter=", painter != null)
		if painter:
			var hit := false
			var found := false
			for r in painter.rows:
				if not r.has("last_hit"): continue
				if bool(r.get("last_hit", false)):
					hit = true
					print("L LASTHIT row pos=", r.get("pos"), " hp=", r.get("hp"), " team_color=", r.get("team_color"))
			print("L rows=", painter.rows.size(), " any_last_hit=", hit)
	elif t == 208:
		# 反向验证：血量拉高到打不死 → 不应再是灰白
		if target:
			target.health = 3500.0
		elif true:
			pass
	elif t == 212:
		var any_hit := false
		if painter:
			for r in painter.rows:
				if bool(r.get("last_hit", false)): any_hit = true
		print("L high_hp_any_last_hit=", any_hit, " aa_t=", bm.hero.aa_target_t)
	elif t == 240:
		# 超时后目标失效验证
		print("L expired_aa_target=", bm.hero.aa_target == null, " any=", _any_last_hit())
		get_tree().quit()
func _any_last_hit() -> bool:
	if painter == null: return false
	for r in painter.rows:
		if bool(r.get("last_hit", false)): return true
	return false
