{"command":"@'
extends Node
var t := 0
var bm = null
var target = null
var cam = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _find(n: Node, nm: String) -> Node:
	if str(n.name) == nm: return n
	for c in n.get_children():
		var r := _find(c, nm)
		if r: return r
	return null
func _row_pos(w: float, h: float) -> Vector2:
	var anchor: float = target.body_radius * 2.0 + 1.0
	if target.has_method("bar_anchor_height"):
		anchor = target.bar_anchor_height()
	var sp: Vector2 = cam.unproject_position(target.global_position + Vector3.UP * anchor)
	return sp - Vector2(w, h) * 0.5
func _sample(pos: Vector2, w: float, h: float) -> String:
	var img := get_viewport().get_texture().get_image()
	var px := int(pos.x + w * 0.3)
	var py := int(pos.y + h * 0.5)
	var c := img.get_pixel(clampi(px, 0, img.get_width() - 1), clampi(py, 0, img.get_height() - 1))
	return "(%.2f,%.2f,%.2f)" % [c.r, c.g, c.b]
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 200:
		cam = bm.cam
		var hero = bm.hero
		var best = null
		var bd := 1e9
		for e in get_tree().get_nodes_in_group("entities"):
			if e is Hero or Config.is_ally(int(e.team)): continue
			var dd: float = hero.global_position.distance_to(e.global_position)
			if dd < bd: bd = dd; best = e
		target = best
		target.visible = true
		target.health = 300.0
		target.max_health = 4000.0
		hero.actual_attack_damage = 800.0
		hero.global_position = target.global_position + Vector3(2.0, 0.6, 0.0)
		print("L mode=capture cam_ok=", cam != null)
	elif t == 216:
		target.visible = true
		bm.hero.aa_target = target
		bm.hero.aa_target_t = 2.0
	elif t == 219:
		var pos := _row_pos(110.0, 15.0)
		print("L LOW row_pos=", pos, " last_hit_flag=", bm.hero.aa_target == target, " hp=", target.health)
		await get_tree().process_frame
		print("L LOW pixel=", _sample(pos, 110.0, 15.0))
	elif t == 230:
		target.health = 3900.0
		bm.hero.aa_target = target
		bm.hero.aa_target_t = 2.0
	elif t == 233:
		var pos := _row_pos(110.0, 15.0)
		var rows := []
		var painter = _find(bm, "WorldBars")
		for r in painter.rows:
			if r.has("last_hit"): rows.append(bool(r.get("last_hit", false)))
		print("L HIGH row_pos=", pos, " hp=", target.health, " rows_flags=", rows)
		await get_tree().process_frame
		print("L HIGH pixel=", _sample(pos, 110.0, 15.0))
	elif t == 260:
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx72\p4.gd
@'
