extends Node
var t := 0
var bm = null
var lows := []
var highs := []
var ally_minion = null
var enemy_hero = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _find(n: Node, nm: String) -> Node:
	if str(n.name) == nm: return n
	for c in n.get_children():
		var r := _find(c, nm)
		if r: return r
	return null
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 200:
		var hero = bm.hero
		hero.actual_attack_damage = 800.0
		hero.global_position = Vector3(0, 0.6, 0)
		# 三个敌方兵：两个残血（应灰白），一个满血（不应灰白）
		for i in 3:
			var pos := Vector3(-2.0 + i * 2.0, 0, 6.0)
			var m = bm.spawn_single_minion("melee", Config.Team.ENEMY, pos, [pos, pos + Vector3(0, 0, 20)], 1)
			m.global_position = pos
			m.max_health = 4000.0
			m.health = 300.0 if i < 2 else 3900.0
			if i < 2: lows.append(m)
			else: highs.append(m)
		# 一个己方残血兵（不应灰白）
		var p2 := Vector3(3.0, 0, 8.0)
		ally_minion = bm.spawn_single_minion("melee", Config.Team.PLAYER, p2, [p2, p2], 1)
		ally_minion.health = 200.0
		ally_minion.max_health = 4000.0
		# 一个敌方英雄拉到残血
		for e in get_tree().get_nodes_in_group("heroes"):
			if e is Hero and not Config.is_ally(int(e.team)):
				enemy_hero = e
				break
		if enemy_hero:
			enemy_hero.global_position = Vector3(0, 0.6, 4.0)
			enemy_hero.health = 200.0
			print("L enemy_hero=", enemy_hero.display_name, " hp=", enemy_hero.health, " armor=", enemy_hero.armor)
	elif t == 215:
		# 未攻击任何目标，仅靠“屏幕内”就要给出提示
		var painter = _find(bm, "WorldBars")
		var n_low := 0
		var n_all := 0
		for r in painter.rows:
			n_all += 1
			if bool(r.get("last_hit", false)): n_low += 1
		print("L rows=", n_all, " last_hit_rows=", n_low, " aa_target=", bm.hero.aa_target)
	elif t == 220:
		# 英雄血条像素采样
		var hud = _find(bm, "HUD")
		var ok := false
		if hud and enemy_hero:
			var ctl = hud.hero_info_controls.get(enemy_hero)
			if ctl:
				var bx: float = ctl.position.x + ctl.size.x * 0.5 - 140.0
				var by: float = ctl.position.y + 2.0 + 14.0
				var img := get_viewport().get_texture().get_image()
				var c := img.get_pixel(clampi(int(bx + 50.0), 0, img.get_width() - 1), clampi(int(by), 0, img.get_height() - 1))
				print("L HERO_BAR_CTL ok=true pos=", ctl.position, " pixel=", "(%.2f,%.2f,%.2f)" % [c.r, c.g, c.b])
				ok = true
			else:
				print("L HERO_BAR_CTL missing")
		print("L hero_sample_done=", ok)
	elif t == 240:
		get_tree().quit()
