var bm = null
var enemy_hero = null
var hud = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _find_hud(n: Node) -> Node:
	var s = n.get_script()
	if s != null and str(s.resource_path).ends_with("scripts/ui/HUD.gd"): return n
	for c in n.get_children():
		var r := _find_hud(c)
		if r: return r
	return null
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 200:
		bm.hero.global_position = Vector3(0, 0.6, 0)
		bm.hero.actual_attack_damage = 800.0
		for e in get_tree().get_nodes_in_group("heroes"):
			if e is Hero and not Config.is_ally(int(e.team)):
				enemy_hero = e
				break
		enemy_hero.global_position = Vector3(0, 0.6, 5.0)
		enemy_hero.health = 200.0
		print("L enemy=", enemy_hero.display_name, " hp=", enemy_hero.health)
	elif t == 216:
		hud = _find_hud(get_tree().root)
		print("L hud_found=", hud != null)
		if hud:
			var ctl = hud.hero_info_controls.get(enemy_hero)
			print("L ctl=", ctl != null, " pos=", (ctl.position if ctl else Vector2.ZERO))
			if ctl:
				var img := get_viewport().get_texture().get_image()
				var cx: float = ctl.position.x + ctl.size.x * 0.5
				var by: float = ctl.position.y + 2.0 + 14.0
				var c := img.get_pixel(clampi(int(cx), 0, img.get_width() - 1), clampi(int(by), 0, img.get_height() - 1))
				print("L HERO_LOW pixel=", "(%.2f,%.2f,%.2f)" % [c.r, c.g, c.b])
	elif t == 226:
		enemy_hero.health = enemy_hero.max_health
	elif t == 234:
		var ctl = hud.hero_info_controls.get(enemy_hero)
		var img := get_viewport().get_texture().get_image()
		var cx: float = ctl.position.x + ctl.size.x * 0.5
		var by: float = ctl.position.y + 2.0 + 14.0
		var c := img.get_pixel(clampi(int(cx), 0, img.get_width() - 1), clampi(int(by), 0, img.get_height() - 1))
		print("L HERO_FULL pixel=", "(%.2f,%.2f,%.2f)" % [c.r, c.g, c.b])
	elif t == 250:
		get_tree().quit()
