{"command":"$f='scripts\core\BattleManager.gd'
$c=Get-Content $f -Raw
$old=@'
	var left := PICK_COUNTDOWN
	while left > 0.0 and is_inside_tree():
		num.text = str(int(ceil(left)))
		await get_tree().create_timer(0.1).timeout
		left -= 0.1
'@
$new=@'
	var timer := get_tree().create_timer(PICK_COUNTDOWN)
	while timer.time_left > 0.0 and is_inside_tree():
		num.text = str(maxi(1, int(ceil(timer.time_left))))
		await get_tree().process_frame
'@
