{"command":"@'
extends Node
var t := 0
var bm = null
var foe = null
var mm = null
var px := Vector2.ZERO
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _sample(tag: String) -> void:
	var img := get_viewport().get_texture().get_image()
	var c := img.get_pixel(clampi(int(px.x), 0, img.get_width() - 1), clampi(int(px.y), 0, img.get_height() - 1))
	print("L ", tag, " px=", px, " rgb=", "(%.2f,%.2f,%.2f)" % [c.r, c.g, c.b])
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 210:
		mm = bm.minimap
		for e in get_tree().get_nodes_in_group("heroes"):
			if e is Hero and e.team != Config.player_team:
				foe = e
				break
		foe.global_position = Vector3(30, 0, 30)
		foe.health = 200.0
		var local: Vector2 = mm._world_to_minimap(foe.global_position)
		px = mm.global_position + local
		print("L minimap=", mm != null, " local=", local, " screen=", px)
	elif t == 216:
		_sample("ALIVE_ENEMY")
	elif t == 218:
		foe.health = 0.0
		foe.is_dead = true
	elif t == 226:
		_sample("DEAD_ENEMY")
		get_tree().quit()
