{"command":"$f='scripts\ui\MinimapDraw.gd'
$L=Get-Content $f
$new = @()
for ($i=0; $i -lt $L.Count; $i++) {
	if ($i -eq 278 -and $L[$i].Trim() -eq '_dbg_hero_calls += 1') { continue }   # 删一行（第279行）
	$new += $L[$i]
}
# 在函数体第一行插入计数（第280行 = 原 'func draw_hero' 下一行之后）
$out = @()
$inHero = $false
for ($i=0; $i -lt $new.Count; $i++) {
	$out += $new[$i]
	if ($new[$i] -match '^static func draw_hero\(') { $inHero = $true }
	elseif ($inHero -and $new[$i] -match '\)\s*->\s*void:\s*$') {
		$out += "`t_dbg_hero_calls += 1"
		$inHero = $false
	}
}
Set-Content -Encoding UTF8 $f $out
$b=Get-Content $f
276..284 | ForEach-Object { "D $_|" + ($b[$_-1] -replace "`t","<T>") }","description":"Insert counter inside draw_hero body"}

