$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx80/probe.tscn','--quit-after','400','--resolution','1600x1000','--fixed-fps','60' -PassThru -RedirectStandardOutput 'devfx80\o.out' -RedirectStandardError 'devfx80\o.err'
$d = $a.WaitForExit(300000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx80\o.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx80\o.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' -Context 0,1 | Select-Object -First 6 | ForEach-Object { $_.Line.Trim(); $_.Context.PostContext | ForEach-Object { "   " + $_.Trim() } }

New-Item -ItemType Directory -Force .cache, devfx80 | Out-Null
Copy-Item 'D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64.exe' -Destination '.cache\godot47.exe' -Force
@'
extends Node
var t := 0
var bm = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _report(tag: String) -> void:
	var b: Dictionary = UiManager._compute_recommended_bundle(bm.hero)
	var opts: Array = b.get("options", [])
	var names := ""
	for o in opts:
		names += "%s(%d) " % [str(o["name"]), int(o["cost"])]
	print("L ", tag, " best=", b["id"], " cost=", b["cost"], " opts=", opts.size(), " [", names, "]")
	UiManager._update_recommended_equip()
	print("L ", tag, " row_visible=", UiManager.rec_option_row.visible, " btns=", UiManager.rec_option_row.get_child_count())
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 200:
		print("L rec_list=", UiManager._get_recommended_items(bm.hero))
		bm.hero.gold = 400.0
	elif t == 206:
		_report("LOW_GOLD")
	elif t == 210:
		bm.hero.gold = 6000.0
	elif t == 216:
		_report("HIGH_GOLD")
	elif t == 222:
		var opts: Array = UiManager._compute_recommended_bundle(bm.hero).get("options", [])
		if opts.size() > 0:
			var pick: Dictionary = opts[opts.size() - 1]
			print("L buy_option id=", pick["id"], " gold_before=", int(bm.hero.gold))
			UiManager._shop_quick_buy(str(pick["id"]))
			print("L after_buy owned=", bm.hero.equipment_slots, " gold=", int(bm.hero.gold))
	elif t == 230:
		_report("AFTER_BUY")
		get_tree().quit()
