content.arguments:
{"command":"@'
extends Node
var t := 0
var bm = null
var ui = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _popup_col(tag: String) -> void:
	var ch: Array = ui.get_children()
	var i: int = ch.size() - 1
	while i >= 0:
		if ch[i] is Label:
			var l: Label = ch[i]
			var c: Color = l.get_theme_color("font_color")
			print("L ", tag, " color=(", "%.2f" % c.r, ",", "%.2f" % c.g, ",", "%.2f" % c.b, ") txt=", l.text)
			return
		i -= 1
	print("L ", tag, " no_label")
func _foe():
	for e in get_tree().get_nodes_in_group("heroes"):
		if e is Hero and e.team != Config.player_team:
			return e
	return null
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 200:
		ui = UiManager
		var foe = _foe()
		var hp0: float = bm.hero.health
		bm.hero.shield_remaining = 500.0
		bm.hero.take_damage(100.0, foe, false, 0)
		print("L SHIELD hp_delta=", "%.0f" % (bm.hero.health - hp0), " shield_left=", "%.0f" % bm.hero.shield_remaining)
		_popup_col("SHIELD_POPUP")
	elif t == 206:
		var foe = _foe()
		var hp1: float = bm.hero.health
		var sh1: float = bm.hero.shield_remaining
		bm.hero.take_true_damage(100.0, foe, false, -54)
		print("L TRUE hp_delta=", "%.0f" % (bm.hero.health - hp1), " shield_delta=", "%.0f" % (bm.hero.shield_remaining - sh1))
		_popup_col("TRUE_POPUP")
	elif t == 212:
		print("L NO_DRAGON ", ui._vanguard_info(bm))
	elif t == 216:
		bm.dragon_minion_type = "dragon"
		bm.dragon_minion_budget = 6
		bm.dragon_count = 0
		bm.dominant_buff_team = Config.player_team
		bm.vanguard_ever = true
		print("L OUR_DRAGON ", ui._vanguard_info(bm), " waves=", bm.vanguard_waves_left(Config.player_team), "/", bm.vanguard_waves_left(Config.Team.ENEMY))
	elif t == 220:
		bm.dominant_buff_team = Config.Team.ENEMY
		bm.dragon_count = 3
		print("L ENEMY_DRAGON ", ui._vanguard_info(bm))
		ui.toggle_hero_detail()
		print("L ROSTER_INFO ", ui.hero_detail_panel.hud_info, " visible=", ui.hero_detail_panel.visible)
		get_tree().quit()
'@ | Set-Content -Encoding UTF8 devfx82\probe.gd
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx82/probe.tscn','--quit-after','400','--resolution','1600x1000','--fixed-fps','60' -PassThru -RedirectStandardOutput 'devfx82\o5.out' -RedirectStandardError 'devfx82\o5.err'
$d = $a.WaitForExit(300000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx82\o5.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx82\o5.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' -Context 0,1 | Select-Object -First 5 | ForEach-Object { $_.Line.Trim(); $_.Context.PostContext | ForEach-Object { "   " + $_.Trim() } }","description":"Probe popup colors with real source","timeoutMs":400000}

