{"content":"extends Node
var t := 0
var bm = null
var hero: Hero = null
var far: Hero = null
var p0 := Vector3.ZERO
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _foes() -> Array:
	var out: Array = []
	for e in get_tree().get_nodes_in_group("heroes"):
		if e is Hero and e.team != Config.player_team:
			out.append(e)
	return out
func _process(_d: float) -> void:
	t += 1
	get_tree().paused = false
	if t == 5:
		PlayerPrefs.set_opt("siege_keys", false)
		PlayerPrefs.set_opt("lock_portrait", false)
		PlayerPrefs.set_opt("auto_chase", 0)
		PlayerPrefs.set_opt("move_preview", true)
	elif t == 40:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")
	elif t == 260:
		hero = bm.hero
		print("L SIEGE tower=", TouchController._tower_button.visible, " minion=", TouchController._minion_button.visible)
		var foes := _foes()
		if foes.size() >= 1:
			far = foes[0]
			var ai = far.get_node_or_null("HeroAI")
			if ai:
				ai.set_physics_process(false)
			far.set_physics_process(false)
			far.global_position = hero.global_position + Vector3(0, 0, 9.5)
			far.health = 500.0
			hero.manual_target = far
			p0 = hero.global_position
			print("L CHASE_START d=", "%.2f" % hero.global_position.distance_to(far.global_position), " reach=", "%.2f" % hero._aa_engage_reach())
	elif t == 300:
		var d1: float = hero.global_position.distance_to(far.global_position)
		var moved := hero.global_position - p0
		var dirn: Vector3 = (far.global_position - p0)
		dirn.y = 0.0
		print("L CHASE_END d=", "%.2f" % d1, " moved=", "%.2f" % moved.length(), " closed=", "%.2f" % (moved.dot(dirn.normalized())))
	elif t == 304:
		var wall: Node3D = null
		for w in get_tree().get_nodes_in_group("entities"):
			if w is Wall:
				wall = w
				break
		if wall == null:
			for n in get_tree().root.find_children("*", "StaticBody3D", true, false):
				if n is Wall:
					wall = n
					break
		if wall:
			var d := wall.global_position - hero.global_position
			d.y = 0.0
			var full: float = d.length()
			var endp: Vector3 = hero.clamp_dash_landing(d.normalized(), full + 6.0)
			print("L WALL dist=", "%.2f" % full, " end_off=", "%.2f" % hero.global_position.distance_to(endp), " (clamped if < full+6)")
		else:
			print("L WALL none")
		hero._update_dash_preview()
		print("L PREVIEW idle_null=", hero._dash_preview == null)
		get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\devfx83\probe.gd"}

