```gdscript
# 全图技能弹位置行（小地图绘制用）：[位置, 方向, gs]
func _mm_global_bullet_rows() -> Array:
	var out: Array = []
	var now := Time.get_ticks_msec()
	for bid in _bullets:
		var b: Dictionary = _bullets[bid]
		var gs := int(b.get("gs", 0))
		if gs <= 0:
			continue
		var f := minf((now - int(b.get("arr_ms", now))) * 0.001, SNAP_BULLET_EXT)
