script = ExtResource("1")
'@ | Set-Content -Encoding UTF8 devfx85\probe.tscn
$a = Start-Process -FilePath (Resolve-Path '.cache\godot47.exe') -ArgumentList '--path','.','res://devfx85/probe.tscn','--quit-after','260','--resolution','1600x1000','--fixed-fps','60' -PassThru -RedirectStandardOutput 'devfx85\o.out' -RedirectStandardError 'devfx85\o.err'
$d = $a.WaitForExit(200000); if (-not $d) { $a.Kill(); "TIMEOUT" }
Get-Content devfx85\o.out | Select-String -Pattern '^L ' | ForEach-Object { $_.Line.Trim() }
"=== errors ==="
Get-Content devfx85\o.err | Select-String -Pattern 'SCRIPT ERROR|Parse Error' -Context 0,1 | Select-Object -First 4 | ForEach-Object { $_.Line.Trim(); $_.Context.PostContext | ForEach-Object { "   " + $_.Trim() } }

Get-ChildItem -Filter "_probe_walka*" | Select-Object Name
Get-ChildItem -Filter "_probe_walka*" | Remove-Item -Force
git status --short | Where-Object { $_ -match '_probe_walka' } | ForEach-Object { $_ }

Get-ChildItem -Filter "_probe_walka*" | Select-Object Name
